  ["霹雳电球"] = {   id=100, en="Voltorb", zh="霹雳电球", type="Electric", species="Ball Pokémon", desc="Voltorb is extremely sensitive—it explodes at the slightest of shocks. It is rumored that it was first created when a Poké Ball was exposed to a powerful pulse of energy." },
