  ["顽皮雷弹"] = {   id=101, en="Electrode", zh="顽皮雷弹", type="Electric", species="Ball Pokémon", desc="One of Electrode’s characteristics is its attraction to electricity. It is a problematical Pokémon that congregates mostly at electrical power plants to feed on electricity that has just been generated." },
  ["electrode"] = {   id=101, en="Electrode", zh="顽皮雷弹", type="Electric", species="Ball Pokémon", desc="One of Electrode’s characteristics is its attraction to electricity. It is a problematical Pokémon that congregates mostly at electrical power plants to feed on electricity that has just been generated." },
  ["蛋蛋"] = {   id=102, en="Exeggcute", zh="蛋蛋", type="Grass, Psychic", species="Egg Pokémon", desc="Although they are the same size as other Exeggcute, the ones produced in Alola are quite heavy. Their shells are packed full." },
  ["exeggcute"] = {   id=102, en="Exeggcute", zh="蛋蛋", type="Grass, Psychic", species="Egg Pokémon", desc="Although they are the same size as other Exeggcute, the ones produced in Alola are quite heavy. Their shells are packed full." },
  ["椰蛋树"] = {   id=103, en="Exeggutor", zh="椰蛋树", type="Grass, Psychic", species="Coconut Pokémon", desc="Each of its three heads has its own thoughts. When they want to go in different directions, Exeggutor becomes unable to move." },
  ["exeggutor"] = {   id=103, en="Exeggutor", zh="椰蛋树", type="Grass, Psychic", species="Coconut Pokémon", desc="Each of its three heads has its own thoughts. When they want to go in different directions, Exeggutor becomes unable to move." },
  ["卡拉卡拉"] = {   id=104, en="Cubone", zh="卡拉卡拉", type="Ground", species="Lonely Pokémon", desc="It wears its mother’s skull on its head, so no one knows what its bare face looks like. However, it’s clear that it’s always crying." },
  ["cubone"] = {   id=104, en="Cubone", zh="卡拉卡拉", type="Ground", species="Lonely Pokémon", desc="It wears its mother’s skull on its head, so no one knows what its bare face looks like. However, it’s clear that it’s always crying." },
  ["嘎啦嘎啦"] = {   id=105, en="Marowak", zh="嘎啦嘎啦", type="Ground", species="Bone Keeper Pokémon", desc="They thump their bones rhythmically to communicate among themselves. There are nearly 50 different rhythmic patterns." },
  ["marowak"] = {   id=105, en="Marowak", zh="嘎啦嘎啦", type="Ground", species="Bone Keeper Pokémon", desc="They thump their bones rhythmically to communicate among themselves. There are nearly 50 different rhythmic patterns." },
  ["飞腿郎"] = {   id=106, en="Hitmonlee", zh="飞腿郎", type="Fighting", species="Kicking Pokémon", desc="Hitmonlee’s legs freely contract and stretch. Using these springlike legs, it bowls over foes with devastating kicks. After battle, it rubs down its legs and loosens the muscles to overcome fatigue." },
  ["hitmonlee"] = {   id=106, en="Hitmonlee", zh="飞腿郎", type="Fighting", species="Kicking Pokémon", desc="Hitmonlee’s legs freely contract and stretch. Using these springlike legs, it bowls over foes with devastating kicks. After battle, it rubs down its legs and loosens the muscles to overcome fatigue." },
  ["快拳郎"] = {   id=107, en="Hitmonchan", zh="快拳郎", type="Fighting", species="Punching Pokémon", desc="Hitmonchan is said to possess the spirit of a boxer who had been working toward a world championship. This Pokémon has an indomitable spirit and will never give up in the face of adversity." },
  ["hitmonchan"] = {   id=107, en="Hitmonchan", zh="快拳郎", type="Fighting", species="Punching Pokémon", desc="Hitmonchan is said to possess the spirit of a boxer who had been working toward a world championship. This Pokémon has an indomitable spirit and will never give up in the face of adversity." },
  ["大舌头"] = {   id=108, en="Lickitung", zh="大舌头", type="Normal", species="Licking Pokémon", desc="It licks filth clean with its tongue. Whatever it licks always stinks afterward, so whether it’s really clean is...questionable." },
  ["lickitung"] = {   id=108, en="Lickitung", zh="大舌头", type="Normal", species="Licking Pokémon", desc="It licks filth clean with its tongue. Whatever it licks always stinks afterward, so whether it’s really clean is...questionable." },
  ["瓦斯弹"] = {   id=109, en="Koffing", zh="瓦斯弹", type="Poison", species="Poison Gas Pokémon", desc="Koffing embodies toxic substances. It mixes the toxins with raw garbage to set off a chemical reaction that results in a terribly powerful poison gas. The higher the temperature, the more gas is concocted by this Pokémon." },
  ["koffing"] = {   id=109, en="Koffing", zh="瓦斯弹", type="Poison", species="Poison Gas Pokémon", desc="Koffing embodies toxic substances. It mixes the toxins with raw garbage to set off a chemical reaction that results in a terribly powerful poison gas. The higher the temperature, the more gas is concocted by this Pokémon." },
  ["双弹瓦斯"] = {   id=110, en="Weezing", zh="双弹瓦斯", type="Poison", species="Poison Gas Pokémon", desc="Weezing alternately shrinks and inflates its twin bodies to mix together toxic gases inside. The more the gases are mixed, the more powerful the toxins become. The Pokémon also becomes more putrid." },
  ["weezing"] = {   id=110, en="Weezing", zh="双弹瓦斯", type="Poison", species="Poison Gas Pokémon", desc="Weezing alternately shrinks and inflates its twin bodies to mix together toxic gases inside. The more the gases are mixed, the more powerful the toxins become. The Pokémon also becomes more putrid." },
  ["独角犀牛"] = {   id=111, en="Rhyhorn", zh="独角犀牛", type="Ground, Rock", species="Spikes Pokémon", desc="Rhyhorn’s brain is very small. It is so dense, while on a run it forgets why it started running in the first place. It apparently remembers sometimes if it demolishes something." },
  ["rhyhorn"] = {   id=111, en="Rhyhorn", zh="独角犀牛", type="Ground, Rock", species="Spikes Pokémon", desc="Rhyhorn’s brain is very small. It is so dense, while on a run it forgets why it started running in the first place. It apparently remembers sometimes if it demolishes something." },
  ["钻角犀兽"] = {   id=112, en="Rhydon", zh="钻角犀兽", type="Ground, Rock", species="Drill Pokémon", desc="Rhydon has a horn that serves as a drill. It is used for destroying rocks and boulders. This Pokémon occasionally rams into streams of magma, but the armor-like hide prevents it from feeling the heat." },
  ["rhydon"] = {   id=112, en="Rhydon", zh="钻角犀兽", type="Ground, Rock", species="Drill Pokémon", desc="Rhydon has a horn that serves as a drill. It is used for destroying rocks and boulders. This Pokémon occasionally rams into streams of magma, but the armor-like hide prevents it from feeling the heat." },
  ["吉利蛋"] = {   id=113, en="Chansey", zh="吉利蛋", type="Normal", species="Egg Pokémon", desc="Because the eggs on their bellies have been overharvested by people in the past, the Chansey population remains very small." },
  ["chansey"] = {   id=113, en="Chansey", zh="吉利蛋", type="Normal", species="Egg Pokémon", desc="Because the eggs on their bellies have been overharvested by people in the past, the Chansey population remains very small." },
  ["蔓藤怪"] = {   id=114, en="Tangela", zh="蔓藤怪", type="Grass", species="Vine Pokémon", desc="Tangela’s vines snap off easily if they are grabbed. This happens without pain, allowing it to make a quick getaway. The lost vines are replaced by newly grown vines the very next day." },
  ["tangela"] = {   id=114, en="Tangela", zh="蔓藤怪", type="Grass", species="Vine Pokémon", desc="Tangela’s vines snap off easily if they are grabbed. This happens without pain, allowing it to make a quick getaway. The lost vines are replaced by newly grown vines the very next day." },
  ["袋兽"] = {   id=115, en="Kangaskhan", zh="袋兽", type="Normal", species="Parent Pokémon", desc="You shouldn’t get close to the child when it’s playing outside its mother’s pouch. Its mother is always nearby watching over it." },
  ["kangaskhan"] = {   id=115, en="Kangaskhan", zh="袋兽", type="Normal", species="Parent Pokémon", desc="You shouldn’t get close to the child when it’s playing outside its mother’s pouch. Its mother is always nearby watching over it." },
  ["墨海马"] = {   id=116, en="Horsea", zh="墨海马", type="Water", species="Dragon Pokémon", desc="If Horsea senses danger, it will reflexively spray a dense black ink from its mouth and try to escape. This Pokémon swims by cleverly flapping the fin on its back." },
  ["horsea"] = {   id=116, en="Horsea", zh="墨海马", type="Water", species="Dragon Pokémon", desc="If Horsea senses danger, it will reflexively spray a dense black ink from its mouth and try to escape. This Pokémon swims by cleverly flapping the fin on its back." },
  ["海刺龙"] = {   id=117, en="Seadra", zh="海刺龙", type="Water", species="Dragon Pokémon", desc="Seadra generates whirlpools by spinning its body. The whirlpools are strong enough to swallow even fishing boats. This Pokémon weakens prey with these currents, then swallows it whole." },
  ["seadra"] = {   id=117, en="Seadra", zh="海刺龙", type="Water", species="Dragon Pokémon", desc="Seadra generates whirlpools by spinning its body. The whirlpools are strong enough to swallow even fishing boats. This Pokémon weakens prey with these currents, then swallows it whole." },
  ["角金鱼"] = {   id=118, en="Goldeen", zh="角金鱼", type="Water", species="Goldfish Pokémon", desc="The way it swims along fluttering its dress-like fins has earned it the name “princess of the water.”" },
  ["goldeen"] = {   id=118, en="Goldeen", zh="角金鱼", type="Water", species="Goldfish Pokémon", desc="The way it swims along fluttering its dress-like fins has earned it the name “princess of the water.”" },
  ["金鱼王"] = {   id=119, en="Seaking", zh="金鱼王", type="Water", species="Goldfish Pokémon", desc="To attract females, males dance on the river’s floor. The females gather around the male that dances most gracefully." },
  ["seaking"] = {   id=119, en="Seaking", zh="金鱼王", type="Water", species="Goldfish Pokémon", desc="To attract females, males dance on the river’s floor. The females gather around the male that dances most gracefully." },
  ["海星星"] = {   id=120, en="Staryu", zh="海星星", type="Water", species="Star Shape Pokémon", desc="No number of injuries can bother Staryu. Its amazing regenerative powers return it to its previous state in half a day!" },
  ["staryu"] = {   id=120, en="Staryu", zh="海星星", type="Water", species="Star Shape Pokémon", desc="No number of injuries can bother Staryu. Its amazing regenerative powers return it to its previous state in half a day!" },
  ["宝石海星"] = {   id=121, en="Starmie", zh="宝石海星", type="Water, Psychic", species="Mysterious Pokémon", desc="It rotates its geometrically shaped body to swim through the water. It always seems to be sending out mysterious radio waves." },
  ["starmie"] = {   id=121, en="Starmie", zh="宝石海星", type="Water, Psychic", species="Mysterious Pokémon", desc="It rotates its geometrically shaped body to swim through the water. It always seems to be sending out mysterious radio waves." },
  ["魔墙人偶"] = {   id=122, en="Mr. Mime", zh="魔墙人偶", type="Psychic, Fairy", species="Barrier Pokémon", desc="It creates invisible walls with its pantomiming. If you don’t act impressed, it will attack you with a double slap!" },
  ["mr. mime"] = {   id=122, en="Mr. Mime", zh="魔墙人偶", type="Psychic, Fairy", species="Barrier Pokémon", desc="It creates invisible walls with its pantomiming. If you don’t act impressed, it will attack you with a double slap!" },
  ["飞天螳螂"] = {   id=123, en="Scyther", zh="飞天螳螂", type="Bug, Flying", species="Mantis Pokémon", desc="Some call it a ninja. Its movements— imperceptibly quick—are sufficient to cleave the air in two. It’s very popular in Alola." },
  ["scyther"] = {   id=123, en="Scyther", zh="飞天螳螂", type="Bug, Flying", species="Mantis Pokémon", desc="Some call it a ninja. Its movements— imperceptibly quick—are sufficient to cleave the air in two. It’s very popular in Alola." },
  ["迷唇姐"] = {   id=124, en="Jynx", zh="迷唇姐", type="Ice, Psychic", species="Human Shape Pokémon", desc="Its strange cries sound like human language. There are some musicians who compose songs for Jynx to sing." },
  ["jynx"] = {   id=124, en="Jynx", zh="迷唇姐", type="Ice, Psychic", species="Human Shape Pokémon", desc="Its strange cries sound like human language. There are some musicians who compose songs for Jynx to sing." },
  ["电击兽"] = {   id=125, en="Electabuzz", zh="电击兽", type="Electric", species="Electric Pokémon", desc="While it’s often blamed for power outages, the truth is the cause of outages is more often an error on the part of the electric company." },
  ["electabuzz"] = {   id=125, en="Electabuzz", zh="电击兽", type="Electric", species="Electric Pokémon", desc="While it’s often blamed for power outages, the truth is the cause of outages is more often an error on the part of the electric company." },
  ["鸭嘴火兽"] = {   id=126, en="Magmar", zh="鸭嘴火兽", type="Fire", species="Spitfire Pokémon", desc="The hotter the place, the better they feel. Magmar in Alola are said to be hardier than those in other areas." },
  ["magmar"] = {   id=126, en="Magmar", zh="鸭嘴火兽", type="Fire", species="Spitfire Pokémon", desc="The hotter the place, the better they feel. Magmar in Alola are said to be hardier than those in other areas." },
  ["凯罗斯"] = {   id=127, en="Pinsir", zh="凯罗斯", type="Bug", species="Stag Beetle Pokémon", desc="Although it’s tough, it can’t handle cold well. When night falls, it buries itself in leafage and sleeps." },
  ["pinsir"] = {   id=127, en="Pinsir", zh="凯罗斯", type="Bug", species="Stag Beetle Pokémon", desc="Although it’s tough, it can’t handle cold well. When night falls, it buries itself in leafage and sleeps." },
  ["肯泰罗"] = {   id=128, en="Tauros", zh="肯泰罗", type="Normal", species="Wild Bull Pokémon", desc="The climate seems to be related to the reason Tauros in Alola are a little calmer than those in other regions." },
  ["tauros"] = {   id=128, en="Tauros", zh="肯泰罗", type="Normal", species="Wild Bull Pokémon", desc="The climate seems to be related to the reason Tauros in Alola are a little calmer than those in other regions." },
  ["鲤鱼王"] = {   id=129, en="Magikarp", zh="鲤鱼王", type="Water", species="Fish Pokémon", desc="Thanks to their strong hold on life, dirty water doesn’t bother them at all. They live in waters all over the world!" },
  ["magikarp"] = {   id=129, en="Magikarp", zh="鲤鱼王", type="Water", species="Fish Pokémon", desc="Thanks to their strong hold on life, dirty water doesn’t bother them at all. They live in waters all over the world!" },
  ["暴鲤龙"] = {   id=130, en="Gyarados", zh="暴鲤龙", type="Water, Flying", species="Atrocious Pokémon", desc="The energy from evolution stimulated its brain cells strongly, causing it to become very ferocious." },
  ["gyarados"] = {   id=130, en="Gyarados", zh="暴鲤龙", type="Water, Flying", species="Atrocious Pokémon", desc="The energy from evolution stimulated its brain cells strongly, causing it to become very ferocious." },
  ["拉普拉斯"] = {   id=131, en="Lapras", zh="拉普拉斯", type="Water, Ice", species="Transport Pokémon", desc="They’ve been so cherished that there’s now an overabundance. The fish Pokémon population has declined in waters with too many Lapras." },
  ["lapras"] = {   id=131, en="Lapras", zh="拉普拉斯", type="Water, Ice", species="Transport Pokémon", desc="They’ve been so cherished that there’s now an overabundance. The fish Pokémon population has declined in waters with too many Lapras." },
  ["百变怪"] = {   id=132, en="Ditto", zh="百变怪", type="Normal", species="Transform Pokémon", desc="It transforms into whatever it sees. If the thing it’s transforming into isn’t right in front of it, Ditto relies on its memory—so sometimes it fails." },
  ["ditto"] = {   id=132, en="Ditto", zh="百变怪", type="Normal", species="Transform Pokémon", desc="It transforms into whatever it sees. If the thing it’s transforming into isn’t right in front of it, Ditto relies on its memory—so sometimes it fails." },
  ["伊布"] = {   id=133, en="Eevee", zh="伊布", type="Normal", species="Evolution Pokémon", desc="Its genes are easily influenced by its surroundings. Even its face starts to look like that of its Trainer." },
  ["eevee"] = {   id=133, en="Eevee", zh="伊布", type="Normal", species="Evolution Pokémon", desc="Its genes are easily influenced by its surroundings. Even its face starts to look like that of its Trainer." },
  ["水伊布"] = {   id=134, en="Vaporeon", zh="水伊布", type="Water", species="Bubble Jet Pokémon", desc="It detects nearby moisture with its fin. When its fin begins trembling rapidly, that means rain will fall in a few hours." },
  ["vaporeon"] = {   id=134, en="Vaporeon", zh="水伊布", type="Water", species="Bubble Jet Pokémon", desc="It detects nearby moisture with its fin. When its fin begins trembling rapidly, that means rain will fall in a few hours." },
  ["雷伊布"] = {   id=135, en="Jolteon", zh="雷伊布", type="Electric", species="Lightning Pokémon", desc="Its fur stands on end, becoming like needles it fires at enemies. Once they’re weakened, it finishes them off with a 10,000 volt shock." },
  ["jolteon"] = {   id=135, en="Jolteon", zh="雷伊布", type="Electric", species="Lightning Pokémon", desc="Its fur stands on end, becoming like needles it fires at enemies. Once they’re weakened, it finishes them off with a 10,000 volt shock." },
  ["火伊布"] = {   id=136, en="Flareon", zh="火伊布", type="Fire", species="Flame Pokémon", desc="The flame chamber inside its body ignites when Flareon gets agitated, reaching temperatures of up to 1,650 degrees Fahrenheit." },
  ["flareon"] = {   id=136, en="Flareon", zh="火伊布", type="Fire", species="Flame Pokémon", desc="The flame chamber inside its body ignites when Flareon gets agitated, reaching temperatures of up to 1,650 degrees Fahrenheit." },
  ["多边兽"] = {   id=137, en="Porygon", zh="多边兽", type="Normal", species="Virtual Pokémon", desc="It was built 20 years ago by scientists who dreamed of exploring space. Their dreams have yet to come true." },
  ["porygon"] = {   id=137, en="Porygon", zh="多边兽", type="Normal", species="Virtual Pokémon", desc="It was built 20 years ago by scientists who dreamed of exploring space. Their dreams have yet to come true." },
  ["菊石兽"] = {   id=138, en="Omanyte", zh="菊石兽", type="Rock, Water", species="Spiral Pokémon", desc="It was restored from an ancient fossil. Those Helix Fossils are excavated from areas that were once oceans long, long ago." },
  ["omanyte"] = {   id=138, en="Omanyte", zh="菊石兽", type="Rock, Water", species="Spiral Pokémon", desc="It was restored from an ancient fossil. Those Helix Fossils are excavated from areas that were once oceans long, long ago." },
  ["多刺菊石兽"] = {   id=139, en="Omastar", zh="多刺菊石兽", type="Rock, Water", species="Spiral Pokémon", desc="It wraps its prey in its tentacles to immobilize them and then finishes them off with its sharp fangs." },
  ["omastar"] = {   id=139, en="Omastar", zh="多刺菊石兽", type="Rock, Water", species="Spiral Pokémon", desc="It wraps its prey in its tentacles to immobilize them and then finishes them off with its sharp fangs." },
  ["化石盔"] = {   id=140, en="Kabuto", zh="化石盔", type="Rock, Water", species="Shellfish Pokémon", desc="This Pokémon became extinct everywhere, except in a few areas. It protects itself with its hard shell." },
  ["kabuto"] = {   id=140, en="Kabuto", zh="化石盔", type="Rock, Water", species="Shellfish Pokémon", desc="This Pokémon became extinct everywhere, except in a few areas. It protects itself with its hard shell." },
  ["镰刀盔"] = {   id=141, en="Kabutops", zh="镰刀盔", type="Rock, Water", species="Shellfish Pokémon", desc="It swims at speeds of roughly 29 knots, quickly closing in on its prey and slashing into them with its scythes to finish them off." },
  ["kabutops"] = {   id=141, en="Kabutops", zh="镰刀盔", type="Rock, Water", species="Shellfish Pokémon", desc="It swims at speeds of roughly 29 knots, quickly closing in on its prey and slashing into them with its scythes to finish them off." },
  ["化石翼龙"] = {   id=142, en="Aerodactyl", zh="化石翼龙", type="Rock, Flying", species="Fossil Pokémon", desc="It flew through the open skies over the ancient continent as if they were its own. When it touched ground, its walk was weak and slow." },
  ["aerodactyl"] = {   id=142, en="Aerodactyl", zh="化石翼龙", type="Rock, Flying", species="Fossil Pokémon", desc="It flew through the open skies over the ancient continent as if they were its own. When it touched ground, its walk was weak and slow." },
  ["卡比兽"] = {   id=143, en="Snorlax", zh="卡比兽", type="Normal", species="Sleeping Pokémon", desc="It has no interest in anything other than eating. Even if you climb up on its stomach while it’s napping, it doesn’t seem to mind at all!" },
  ["snorlax"] = {   id=143, en="Snorlax", zh="卡比兽", type="Normal", species="Sleeping Pokémon", desc="It has no interest in anything other than eating. Even if you climb up on its stomach while it’s napping, it doesn’t seem to mind at all!" },
  ["急冻鸟"] = {   id=144, en="Articuno", zh="急冻鸟", type="Ice, Flying", species="Freeze Pokémon", desc="Articuno is a legendary bird Pokémon that can control ice. The flapping of its wings chills the air. As a result, it is said that when this Pokémon flies, snow will fall." },
  ["articuno"] = {   id=144, en="Articuno", zh="急冻鸟", type="Ice, Flying", species="Freeze Pokémon", desc="Articuno is a legendary bird Pokémon that can control ice. The flapping of its wings chills the air. As a result, it is said that when this Pokémon flies, snow will fall." },
  ["闪电鸟"] = {   id=145, en="Zapdos", zh="闪电鸟", type="Electric, Flying", species="Electric Pokémon", desc="Zapdos is a legendary bird Pokémon that has the ability to control electricity. It usually lives in thunderclouds. The Pokémon gains power if it is stricken by lightning bolts." },
  ["zapdos"] = {   id=145, en="Zapdos", zh="闪电鸟", type="Electric, Flying", species="Electric Pokémon", desc="Zapdos is a legendary bird Pokémon that has the ability to control electricity. It usually lives in thunderclouds. The Pokémon gains power if it is stricken by lightning bolts." },
  ["火焰鸟"] = {   id=146, en="Moltres", zh="火焰鸟", type="Fire, Flying", species="Flame Pokémon", desc="Moltres is a legendary bird Pokémon that has the ability to control fire. If this Pokémon is injured, it is said to dip its body in the molten magma of a volcano to burn and heal itself." },
  ["moltres"] = {   id=146, en="Moltres", zh="火焰鸟", type="Fire, Flying", species="Flame Pokémon", desc="Moltres is a legendary bird Pokémon that has the ability to control fire. If this Pokémon is injured, it is said to dip its body in the molten magma of a volcano to burn and heal itself." },
  ["迷你龙"] = {   id=147, en="Dratini", zh="迷你龙", type="Dragon", species="Dragon Pokémon", desc="It sheds its skin—almost on a daily basis—and grows larger. Its skin is soft just after it’s been shed." },
  ["dratini"] = {   id=147, en="Dratini", zh="迷你龙", type="Dragon", species="Dragon Pokémon", desc="It sheds its skin—almost on a daily basis—and grows larger. Its skin is soft just after it’s been shed." },
  ["哈克龙"] = {   id=148, en="Dragonair", zh="哈克龙", type="Dragon", species="Dragon Pokémon", desc="Some say that if you see it at the start of the year, flying through the sky and twisting its body, you’ll be healthy all year long." },
  ["dragonair"] = {   id=148, en="Dragonair", zh="哈克龙", type="Dragon", species="Dragon Pokémon", desc="Some say that if you see it at the start of the year, flying through the sky and twisting its body, you’ll be healthy all year long." },
  ["快龙"] = {   id=149, en="Dragonite", zh="快龙", type="Dragon, Flying", species="Dragon Pokémon", desc="You’ll often hear tales of this kindhearted Pokémon rescuing people or Pokémon that are drowning." },
  ["dragonite"] = {   id=149, en="Dragonite", zh="快龙", type="Dragon, Flying", species="Dragon Pokémon", desc="You’ll often hear tales of this kindhearted Pokémon rescuing people or Pokémon that are drowning." },
  ["超梦"] = {   id=150, en="Mewtwo", zh="超梦", type="Psychic", species="Genetic Pokémon", desc="Mewtwo is a Pokémon that was created by genetic manipulation. However, even though the scientific power of humans created this Pokémon’s body, they failed to endow Mewtwo with a compassionate heart." },
  ["mewtwo"] = {   id=150, en="Mewtwo", zh="超梦", type="Psychic", species="Genetic Pokémon", desc="Mewtwo is a Pokémon that was created by genetic manipulation. However, even though the scientific power of humans created this Pokémon’s body, they failed to endow Mewtwo with a compassionate heart." },
  ["梦幻"] = {   id=151, en="Mew", zh="梦幻", type="Psychic", species="New Species Pokémon", desc="Mew is said to possess the genetic composition of all Pokémon. It is capable of making itself invisible at will, so it entirely avoids notice even if it approaches people." },
  ["mew"] = {   id=151, en="Mew", zh="梦幻", type="Psychic", species="New Species Pokémon", desc="Mew is said to possess the genetic composition of all Pokémon. It is capable of making itself invisible at will, so it entirely avoids notice even if it approaches people." },
  ["菊草叶"] = {   id=152, en="Chikorita", zh="菊草叶", type="Grass", species="Leaf Pokémon", desc="In battle, Chikorita waves its leaf around to keep the foe at bay. However, a sweet fragrance also wafts from the leaf, becalming the battling Pokémon and creating a cozy, friendly atmosphere all around." },
  ["chikorita"] = {   id=152, en="Chikorita", zh="菊草叶", type="Grass", species="Leaf Pokémon", desc="In battle, Chikorita waves its leaf around to keep the foe at bay. However, a sweet fragrance also wafts from the leaf, becalming the battling Pokémon and creating a cozy, friendly atmosphere all around." },
  ["月桂叶"] = {   id=153, en="Bayleef", zh="月桂叶", type="Grass", species="Leaf Pokémon", desc="Bayleef’s neck is ringed by curled-up leaves. Inside each tubular leaf is a small shoot of a tree. The fragrance of this shoot makes people peppy." },
  ["bayleef"] = {   id=153, en="Bayleef", zh="月桂叶", type="Grass", species="Leaf Pokémon", desc="Bayleef’s neck is ringed by curled-up leaves. Inside each tubular leaf is a small shoot of a tree. The fragrance of this shoot makes people peppy." },
  ["大竺葵"] = {   id=154, en="Meganium", zh="大竺葵", type="Grass", species="Herb Pokémon", desc="The fragrance of Meganium’s flower soothes and calms emotions. In battle, this Pokémon gives off more of its becalming scent to blunt the foe’s fighting spirit." },
  ["meganium"] = {   id=154, en="Meganium", zh="大竺葵", type="Grass", species="Herb Pokémon", desc="The fragrance of Meganium’s flower soothes and calms emotions. In battle, this Pokémon gives off more of its becalming scent to blunt the foe’s fighting spirit." },
  ["火球鼠"] = {   id=155, en="Cyndaquil", zh="火球鼠", type="Fire", species="Fire Mouse Pokémon", desc="Cyndaquil protects itself by flaring up the flames on its back. The flames are vigorous if the Pokémon is angry. However, if it is tired, the flames splutter fitfully with incomplete combustion." },
  ["cyndaquil"] = {   id=155, en="Cyndaquil", zh="火球鼠", type="Fire", species="Fire Mouse Pokémon", desc="Cyndaquil protects itself by flaring up the flames on its back. The flames are vigorous if the Pokémon is angry. However, if it is tired, the flames splutter fitfully with incomplete combustion." },
  ["火岩鼠"] = {   id=156, en="Quilava", zh="火岩鼠", type="Fire", species="Volcano Pokémon", desc="Quilava keeps its foes at bay with the intensity of its flames and gusts of superheated air. This Pokémon applies its outstanding nimbleness to dodge attacks even while scorching the foe with flames." },
  ["quilava"] = {   id=156, en="Quilava", zh="火岩鼠", type="Fire", species="Volcano Pokémon", desc="Quilava keeps its foes at bay with the intensity of its flames and gusts of superheated air. This Pokémon applies its outstanding nimbleness to dodge attacks even while scorching the foe with flames." },
  ["火暴兽"] = {   id=157, en="Typhlosion", zh="火暴兽", type="Fire", species="Volcano Pokémon", desc="Typhlosion obscures itself behind a shimmering heat haze that it creates using its intensely hot flames. This Pokémon creates blazing explosive blasts that burn everything to cinders." },
  ["typhlosion"] = {   id=157, en="Typhlosion", zh="火暴兽", type="Fire", species="Volcano Pokémon", desc="Typhlosion obscures itself behind a shimmering heat haze that it creates using its intensely hot flames. This Pokémon creates blazing explosive blasts that burn everything to cinders." },
  ["小锯鳄"] = {   id=158, en="Totodile", zh="小锯鳄", type="Water", species="Big Jaw Pokémon", desc="Despite the smallness of its body, Totodile’s jaws are very powerful. While the Pokémon may think it is just playfully nipping, its bite has enough power to cause serious injury." },
  ["totodile"] = {   id=158, en="Totodile", zh="小锯鳄", type="Water", species="Big Jaw Pokémon", desc="Despite the smallness of its body, Totodile’s jaws are very powerful. While the Pokémon may think it is just playfully nipping, its bite has enough power to cause serious injury." },
  ["蓝鳄"] = {   id=159, en="Croconaw", zh="蓝鳄", type="Water", species="Big Jaw Pokémon", desc="Once Croconaw has clamped its jaws on its foe, it will absolutely not let go. Because the tips of its fangs are forked back like barbed fishhooks, they become impossible to remove when they have sunk in." },
  ["croconaw"] = {   id=159, en="Croconaw", zh="蓝鳄", type="Water", species="Big Jaw Pokémon", desc="Once Croconaw has clamped its jaws on its foe, it will absolutely not let go. Because the tips of its fangs are forked back like barbed fishhooks, they become impossible to remove when they have sunk in." },
  ["大力鳄"] = {   id=160, en="Feraligatr", zh="大力鳄", type="Water", species="Big Jaw Pokémon", desc="Feraligatr intimidates its foes by opening its huge mouth. In battle, it will kick the ground hard with its thick and powerful hind legs to charge at the foe at an incredible speed." },
  ["feraligatr"] = {   id=160, en="Feraligatr", zh="大力鳄", type="Water", species="Big Jaw Pokémon", desc="Feraligatr intimidates its foes by opening its huge mouth. In battle, it will kick the ground hard with its thick and powerful hind legs to charge at the foe at an incredible speed." },
  ["尾立"] = {   id=161, en="Sentret", zh="尾立", type="Normal", species="Scout Pokémon", desc="When Sentret sleeps, it does so while another stands guard. The sentry wakes the others at the first sign of danger. When this Pokémon becomes separated from its pack, it becomes incapable of sleep due to fear." },
  ["sentret"] = {   id=161, en="Sentret", zh="尾立", type="Normal", species="Scout Pokémon", desc="When Sentret sleeps, it does so while another stands guard. The sentry wakes the others at the first sign of danger. When this Pokémon becomes separated from its pack, it becomes incapable of sleep due to fear." },
  ["大尾立"] = {   id=162, en="Furret", zh="大尾立", type="Normal", species="Long Body Pokémon", desc="Furret has a very slim build. When under attack, it can slickly squirm through narrow spaces and get away. In spite of its short limbs, this Pokémon is very nimble and fleet." },
  ["furret"] = {   id=162, en="Furret", zh="大尾立", type="Normal", species="Long Body Pokémon", desc="Furret has a very slim build. When under attack, it can slickly squirm through narrow spaces and get away. In spite of its short limbs, this Pokémon is very nimble and fleet." },
  ["咕咕"] = {   id=163, en="Hoothoot", zh="咕咕", type="Normal, Flying", species="Owl Pokémon", desc="It cries out at the same time every day. A long time ago, people cherished it and considered it a divine messenger sent to tell the time." },
  ["hoothoot"] = {   id=163, en="Hoothoot", zh="咕咕", type="Normal, Flying", species="Owl Pokémon", desc="It cries out at the same time every day. A long time ago, people cherished it and considered it a divine messenger sent to tell the time." },
  ["猫头夜鹰"] = {   id=164, en="Noctowl", zh="猫头夜鹰", type="Normal, Flying", species="Owl Pokémon", desc="When it turns its head entirely upside down, you know it’s troubled by something. If you don’t leave it be, it will peck you." },
  ["noctowl"] = {   id=164, en="Noctowl", zh="猫头夜鹰", type="Normal, Flying", species="Owl Pokémon", desc="When it turns its head entirely upside down, you know it’s troubled by something. If you don’t leave it be, it will peck you." },
  ["芭瓢虫"] = {   id=165, en="Ledyba", zh="芭瓢虫", type="Bug, Flying", species="Five Star Pokémon", desc="These very cowardly Pokémon join together and use Reflect to protect their nest." },
  ["ledyba"] = {   id=165, en="Ledyba", zh="芭瓢虫", type="Bug, Flying", species="Five Star Pokémon", desc="These very cowardly Pokémon join together and use Reflect to protect their nest." },
  ["安瓢虫"] = {   id=166, en="Ledian", zh="安瓢虫", type="Bug, Flying", species="Five Star Pokémon", desc="It flies through the night sky, sprinkling sparkly dust. According to some, if that dust sticks to you, good things will happen to you." },
  ["ledian"] = {   id=166, en="Ledian", zh="安瓢虫", type="Bug, Flying", species="Five Star Pokémon", desc="It flies through the night sky, sprinkling sparkly dust. According to some, if that dust sticks to you, good things will happen to you." },
  ["圆丝蛛"] = {   id=167, en="Spinarak", zh="圆丝蛛", type="Bug, Poison", species="String Spit Pokémon", desc="Although the poison from its fangs isn’t that strong, it’s potent enough to weaken prey that gets caught in its web." },
  ["spinarak"] = {   id=167, en="Spinarak", zh="圆丝蛛", type="Bug, Poison", species="String Spit Pokémon", desc="Although the poison from its fangs isn’t that strong, it’s potent enough to weaken prey that gets caught in its web." },
  ["阿利多斯"] = {   id=168, en="Ariados", zh="阿利多斯", type="Bug, Poison", species="Long Leg Pokémon", desc="It spews threads from its mouth to catch its prey. When night falls, it leaves its web to go hunt aggressively." },
  ["ariados"] = {   id=168, en="Ariados", zh="阿利多斯", type="Bug, Poison", species="Long Leg Pokémon", desc="It spews threads from its mouth to catch its prey. When night falls, it leaves its web to go hunt aggressively." },
  ["叉字蝠"] = {   id=169, en="Crobat", zh="叉字蝠", type="Poison, Flying", species="Bat Pokémon", desc="It feeds on the blood of living people and Pokémon. If it can’t drink any blood for even a short while, it becomes weak and unable to fly." },
  ["crobat"] = {   id=169, en="Crobat", zh="叉字蝠", type="Poison, Flying", species="Bat Pokémon", desc="It feeds on the blood of living people and Pokémon. If it can’t drink any blood for even a short while, it becomes weak and unable to fly." },
  ["灯笼鱼"] = {   id=170, en="Chinchou", zh="灯笼鱼", type="Water, Electric", species="Angler Pokémon", desc="Chinchou blink their shining antennae at one another to claim their respective turf." },
  ["chinchou"] = {   id=170, en="Chinchou", zh="灯笼鱼", type="Water, Electric", species="Angler Pokémon", desc="Chinchou blink their shining antennae at one another to claim their respective turf." },
  ["电灯怪"] = {   id=171, en="Lanturn", zh="电灯怪", type="Water, Electric", species="Light Pokémon", desc="It lives far down in the depths of the ocean. It blinds its prey with light, using the moment they’re dazzled to swallow them whole." },
  ["lanturn"] = {   id=171, en="Lanturn", zh="电灯怪", type="Water, Electric", species="Light Pokémon", desc="It lives far down in the depths of the ocean. It blinds its prey with light, using the moment they’re dazzled to swallow them whole." },
  ["皮丘"] = {   id=172, en="Pichu", zh="皮丘", type="Electric", species="Tiny Mouse Pokémon", desc="It has electric sacs in its cheeks. When they’re fully charged, Pichu plays very energetically." },
  ["pichu"] = {   id=172, en="Pichu", zh="皮丘", type="Electric", species="Tiny Mouse Pokémon", desc="It has electric sacs in its cheeks. When they’re fully charged, Pichu plays very energetically." },
  ["皮宝宝"] = {   id=173, en="Cleffa", zh="皮宝宝", type="Fairy", species="Star Shape Pokémon", desc="Said to have ridden here on a shooting star, Cleffa seem to appear in places where meteorites have struck in the past." },
  ["cleffa"] = {   id=173, en="Cleffa", zh="皮宝宝", type="Fairy", species="Star Shape Pokémon", desc="Said to have ridden here on a shooting star, Cleffa seem to appear in places where meteorites have struck in the past." },
  ["宝宝丁"] = {   id=174, en="Igglybuff", zh="宝宝丁", type="Normal, Fairy", species="Balloon Pokémon", desc="Left to its own devices, it will constantly practice singing. You should make it take a break so it doesn’t hurt its throat." },
  ["igglybuff"] = {   id=174, en="Igglybuff", zh="宝宝丁", type="Normal, Fairy", species="Balloon Pokémon", desc="Left to its own devices, it will constantly practice singing. You should make it take a break so it doesn’t hurt its throat." },
  ["波克比"] = {   id=175, en="Togepi", zh="波克比", type="Fairy", species="Spike Ball Pokémon", desc="As its energy, Togepi uses the positive emotions of compassion and pleasure exuded by people and Pokémon. This Pokémon stores up feelings of happiness inside its shell, then shares them with others." },
  ["togepi"] = {   id=175, en="Togepi", zh="波克比", type="Fairy", species="Spike Ball Pokémon", desc="As its energy, Togepi uses the positive emotions of compassion and pleasure exuded by people and Pokémon. This Pokémon stores up feelings of happiness inside its shell, then shares them with others." },
  ["波克基古"] = {   id=176, en="Togetic", zh="波克基古", type="Fairy, Flying", species="Happiness Pokémon", desc="Togetic is said to be a Pokémon that brings good fortune. When the Pokémon spots someone who is pure of heart, it is said to appear and share its happiness with that person." },
  ["togetic"] = {   id=176, en="Togetic", zh="波克基古", type="Fairy, Flying", species="Happiness Pokémon", desc="Togetic is said to be a Pokémon that brings good fortune. When the Pokémon spots someone who is pure of heart, it is said to appear and share its happiness with that person." },
  ["天然雀"] = {   id=177, en="Natu", zh="天然雀", type="Psychic, Flying", species="Tiny Bird Pokémon", desc="The look in its eyes gives the impression that it’s carefully observing you. If you approach it, Natu will hop away." },
  ["natu"] = {   id=177, en="Natu", zh="天然雀", type="Psychic, Flying", species="Tiny Bird Pokémon", desc="The look in its eyes gives the impression that it’s carefully observing you. If you approach it, Natu will hop away." },
  ["天然鸟"] = {   id=178, en="Xatu", zh="天然鸟", type="Psychic, Flying", species="Mystic Pokémon", desc="While it can see the future, it has no desire to change it, which is probably why it remains motionless at all times." },
  ["xatu"] = {   id=178, en="Xatu", zh="天然鸟", type="Psychic, Flying", species="Mystic Pokémon", desc="While it can see the future, it has no desire to change it, which is probably why it remains motionless at all times." },
  ["咩利羊"] = {   id=179, en="Mareep", zh="咩利羊", type="Electric", species="Wool Pokémon", desc="Rubbing its fleece generates electricity. You’ll want to pet it because it’s cute, but if you use your bare hand, you’ll get a painful shock." },
  ["mareep"] = {   id=179, en="Mareep", zh="咩利羊", type="Electric", species="Wool Pokémon", desc="Rubbing its fleece generates electricity. You’ll want to pet it because it’s cute, but if you use your bare hand, you’ll get a painful shock." },
  ["茸茸羊"] = {   id=180, en="Flaaffy", zh="茸茸羊", type="Electric", species="Wool Pokémon", desc="It stores electricity in its fluffy fleece. If it stores up too much, it will start to go bald in those patches." },
  ["flaaffy"] = {   id=180, en="Flaaffy", zh="茸茸羊", type="Electric", species="Wool Pokémon", desc="It stores electricity in its fluffy fleece. If it stores up too much, it will start to go bald in those patches." },
  ["电龙"] = {   id=181, en="Ampharos", zh="电龙", type="Electric", species="Light Pokémon", desc="Its tail shines bright and strong. It has been prized since long ago as a beacon for sailors." },
  ["ampharos"] = {   id=181, en="Ampharos", zh="电龙", type="Electric", species="Light Pokémon", desc="Its tail shines bright and strong. It has been prized since long ago as a beacon for sailors." },
  ["美丽花"] = {   id=182, en="Bellossom", zh="美丽花", type="Grass", species="Flower Pokémon", desc="A Bellossom grows flowers more beautifully if it has evolved from a smelly Gloom—the more stinky the better. At night, this Pokémon closes its petals and goes to sleep." },
  ["bellossom"] = {   id=182, en="Bellossom", zh="美丽花", type="Grass", species="Flower Pokémon", desc="A Bellossom grows flowers more beautifully if it has evolved from a smelly Gloom—the more stinky the better. At night, this Pokémon closes its petals and goes to sleep." },
  ["玛力露"] = {   id=183, en="Marill", zh="玛力露", type="Water, Fairy", species="Aqua Mouse Pokémon", desc="When fishing for food at the edge of a fast-running stream, Marill wraps its tail around the trunk of a tree. This Pokémon’s tail is flexible and configured to stretch." },
  ["marill"] = {   id=183, en="Marill", zh="玛力露", type="Water, Fairy", species="Aqua Mouse Pokémon", desc="When fishing for food at the edge of a fast-running stream, Marill wraps its tail around the trunk of a tree. This Pokémon’s tail is flexible and configured to stretch." },
  ["玛力露丽"] = {   id=184, en="Azumarill", zh="玛力露丽", type="Water, Fairy", species="Aqua Rabbit Pokémon", desc="Azumarill can make balloons out of air. It makes these air balloons if it spots a drowning Pokémon. The air balloons enable the Pokémon in trouble to breathe." },
  ["azumarill"] = {   id=184, en="Azumarill", zh="玛力露丽", type="Water, Fairy", species="Aqua Rabbit Pokémon", desc="Azumarill can make balloons out of air. It makes these air balloons if it spots a drowning Pokémon. The air balloons enable the Pokémon in trouble to breathe." },
  ["树才怪‎"] = {   id=185, en="Sudowoodo", zh="树才怪‎", type="Rock", species="Imitation Pokémon", desc="The result of its holding the same pose all the time is arms that have become supple yet strong." },
  ["sudowoodo"] = {   id=185, en="Sudowoodo", zh="树才怪‎", type="Rock", species="Imitation Pokémon", desc="The result of its holding the same pose all the time is arms that have become supple yet strong." },
  ["蚊香蛙皇"] = {   id=186, en="Politoed", zh="蚊香蛙皇", type="Water", species="Frog Pokémon", desc="The longer and more luxurious the curled hair on its head, the greater the number of Poliwag and Poliwhirl that will obey it." },
  ["politoed"] = {   id=186, en="Politoed", zh="蚊香蛙皇", type="Water", species="Frog Pokémon", desc="The longer and more luxurious the curled hair on its head, the greater the number of Poliwag and Poliwhirl that will obey it." },
  ["毽子草"] = {   id=187, en="Hoppip", zh="毽子草", type="Grass, Flying", species="Cottonweed Pokémon", desc="This Pokémon drifts and floats with the wind. If it senses the approach of strong winds, Hoppip links its leaves with other Hoppip to prepare against being blown away." },
  ["hoppip"] = {   id=187, en="Hoppip", zh="毽子草", type="Grass, Flying", species="Cottonweed Pokémon", desc="This Pokémon drifts and floats with the wind. If it senses the approach of strong winds, Hoppip links its leaves with other Hoppip to prepare against being blown away." },
  ["毽子花"] = {   id=188, en="Skiploom", zh="毽子花", type="Grass, Flying", species="Cottonweed Pokémon", desc="Skiploom’s flower blossoms when the temperature rises above 64 degrees Fahrenheit. How much the flower opens depends on the temperature. For that reason, this Pokémon is sometimes used as a thermometer." },
  ["skiploom"] = {   id=188, en="Skiploom", zh="毽子花", type="Grass, Flying", species="Cottonweed Pokémon", desc="Skiploom’s flower blossoms when the temperature rises above 64 degrees Fahrenheit. How much the flower opens depends on the temperature. For that reason, this Pokémon is sometimes used as a thermometer." },
  ["毽子棉"] = {   id=189, en="Jumpluff", zh="毽子棉", type="Grass, Flying", species="Cottonweed Pokémon", desc="Jumpluff rides warm southern winds to cross the sea and fly to foreign lands. The Pokémon descends to the ground when it encounters cold air while it is floating." },
  ["jumpluff"] = {   id=189, en="Jumpluff", zh="毽子棉", type="Grass, Flying", species="Cottonweed Pokémon", desc="Jumpluff rides warm southern winds to cross the sea and fly to foreign lands. The Pokémon descends to the ground when it encounters cold air while it is floating." },
  ["长尾怪手"] = {   id=190, en="Aipom", zh="长尾怪手", type="Normal", species="Long Tail Pokémon", desc="It searches for prey from the tops of trees. When it spots its favorite food, Bounsweet, Aipom gets excited and pounces." },
  ["aipom"] = {   id=190, en="Aipom", zh="长尾怪手", type="Normal", species="Long Tail Pokémon", desc="It searches for prey from the tops of trees. When it spots its favorite food, Bounsweet, Aipom gets excited and pounces." },
  ["向日种子"] = {   id=191, en="Sunkern", zh="向日种子", type="Grass", species="Seed Pokémon", desc="Sunkern tries to move as little as it possibly can. It does so because it tries to conserve all the nutrients it has stored in its body for its evolution. It will not eat a thing, subsisting only on morning dew." },
  ["sunkern"] = {   id=191, en="Sunkern", zh="向日种子", type="Grass", species="Seed Pokémon", desc="Sunkern tries to move as little as it possibly can. It does so because it tries to conserve all the nutrients it has stored in its body for its evolution. It will not eat a thing, subsisting only on morning dew." },
  ["向日花怪"] = {   id=192, en="Sunflora", zh="向日花怪", type="Grass", species="Sun Pokémon", desc="Sunflora converts solar energy into nutrition. It moves around actively in the daytime when it is warm. It stops moving as soon as the sun goes down for the night." },
  ["sunflora"] = {   id=192, en="Sunflora", zh="向日花怪", type="Grass", species="Sun Pokémon", desc="Sunflora converts solar energy into nutrition. It moves around actively in the daytime when it is warm. It stops moving as soon as the sun goes down for the night." },
  ["蜻蜻蜓"] = {   id=193, en="Yanma", zh="蜻蜻蜓", type="Bug, Flying", species="Clear Wing Pokémon", desc="Yanma is capable of seeing 360 degrees without having to move its eyes. It is a great flier that is adept at making sudden stops and turning midair. This Pokémon uses its flying ability to quickly chase down targeted prey." },
  ["yanma"] = {   id=193, en="Yanma", zh="蜻蜻蜓", type="Bug, Flying", species="Clear Wing Pokémon", desc="Yanma is capable of seeing 360 degrees without having to move its eyes. It is a great flier that is adept at making sudden stops and turning midair. This Pokémon uses its flying ability to quickly chase down targeted prey." },
  ["乌波"] = {   id=194, en="Wooper", zh="乌波", type="Water, Ground", species="Water Fish Pokémon", desc="Wooper usually lives in water. However, it occasionally comes out onto land in search of food. On land, it coats its body with a gooey, toxic film." },
  ["wooper"] = {   id=194, en="Wooper", zh="乌波", type="Water, Ground", species="Water Fish Pokémon", desc="Wooper usually lives in water. However, it occasionally comes out onto land in search of food. On land, it coats its body with a gooey, toxic film." },
  ["沼王"] = {   id=195, en="Quagsire", zh="沼王", type="Water, Ground", species="Water Fish Pokémon", desc="Quagsire hunts for food by leaving its mouth wide open in water and waiting for its prey to blunder in unaware. Because the Pokémon does not move, it does not get very hungry." },
  ["quagsire"] = {   id=195, en="Quagsire", zh="沼王", type="Water, Ground", species="Water Fish Pokémon", desc="Quagsire hunts for food by leaving its mouth wide open in water and waiting for its prey to blunder in unaware. Because the Pokémon does not move, it does not get very hungry." },
  ["太阳伊布"] = {   id=196, en="Espeon", zh="太阳伊布", type="Psychic", species="Sun Pokémon", desc="Psychic power builds up in the orb on its forehead as it bathes in the sunshine. Espeon is not good at battling at night." },
  ["espeon"] = {   id=196, en="Espeon", zh="太阳伊布", type="Psychic", species="Sun Pokémon", desc="Psychic power builds up in the orb on its forehead as it bathes in the sunshine. Espeon is not good at battling at night." },
  ["月亮伊布"] = {   id=197, en="Umbreon", zh="月亮伊布", type="Dark", species="Moonlight Pokémon", desc="It lurks in the dark of night looking for prey. At the moment it pounces, the rings on its body glow dimly but ominously." },
  ["umbreon"] = {   id=197, en="Umbreon", zh="月亮伊布", type="Dark", species="Moonlight Pokémon", desc="It lurks in the dark of night looking for prey. At the moment it pounces, the rings on its body glow dimly but ominously." },
  ["黑暗鸦"] = {   id=198, en="Murkrow", zh="黑暗鸦", type="Dark, Flying", species="Darkness Pokémon", desc="It searches for shiny things for its boss. Murkrow’s presence is said to be unlucky, so many people detest it." },
  ["murkrow"] = {   id=198, en="Murkrow", zh="黑暗鸦", type="Dark, Flying", species="Darkness Pokémon", desc="It searches for shiny things for its boss. Murkrow’s presence is said to be unlucky, so many people detest it." },
  ["呆呆王"] = {   id=199, en="Slowking", zh="呆呆王", type="Water, Psychic", species="Royal Pokémon", desc="It’s called “the sage of the sea.” It engages in battles of wits with Oranguru, but the result is usually a draw." },
  ["slowking"] = {   id=199, en="Slowking", zh="呆呆王", type="Water, Psychic", species="Royal Pokémon", desc="It’s called “the sage of the sea.” It engages in battles of wits with Oranguru, but the result is usually a draw." },
  ["梦妖"] = {   id=200, en="Misdreavus", zh="梦妖", type="Ghost", species="Screech Pokémon", desc="What makes it happy is imitating the voices of weeping people and scaring everyone. It doesn’t deal well with folks who aren’t easily frightened." },
  ["misdreavus"] = {   id=200, en="Misdreavus", zh="梦妖", type="Ghost", species="Screech Pokémon", desc="What makes it happy is imitating the voices of weeping people and scaring everyone. It doesn’t deal well with folks who aren’t easily frightened." },
  ["未知图腾"] = {   id=201, en="Unown", zh="未知图腾", type="Psychic", species="Symbol Pokémon", desc="This Pokémon is shaped like ancient writing. It is a mystery as to which came first, the ancient writings or the various Unown. Research into this topic is ongoing but nothing is known." },
  ["unown"] = {   id=201, en="Unown", zh="未知图腾", type="Psychic", species="Symbol Pokémon", desc="This Pokémon is shaped like ancient writing. It is a mystery as to which came first, the ancient writings or the various Unown. Research into this topic is ongoing but nothing is known." },
  ["果然翁"] = {   id=202, en="Wobbuffet", zh="果然翁", type="Psychic", species="Patient Pokémon", desc="Wobbuffet does nothing but endure attacks—it won’t attack on its own. However, it won’t endure an attack on its tail. When that happens, the Pokémon will try to take the foe with it using Destiny Bond." },
  ["wobbuffet"] = {   id=202, en="Wobbuffet", zh="果然翁", type="Psychic", species="Patient Pokémon", desc="Wobbuffet does nothing but endure attacks—it won’t attack on its own. However, it won’t endure an attack on its tail. When that happens, the Pokémon will try to take the foe with it using Destiny Bond." },
  ["麒麟奇"] = {   id=203, en="Girafarig", zh="麒麟奇", type="Normal, Psychic", species="Long Neck Pokémon", desc="Girafarig’s rear head contains a tiny brain that is too small for thinking. However, the rear head doesn’t need to sleep, so it can keep watch over its surroundings 24 hours a day." },
  ["girafarig"] = {   id=203, en="Girafarig", zh="麒麟奇", type="Normal, Psychic", species="Long Neck Pokémon", desc="Girafarig’s rear head contains a tiny brain that is too small for thinking. However, the rear head doesn’t need to sleep, so it can keep watch over its surroundings 24 hours a day." },
  ["榛果球"] = {   id=204, en="Pineco", zh="榛果球", type="Bug", species="Bagworm Pokémon", desc="It sticks tree bark to itself with its saliva, making itself thicker and larger. Elderly Pineco are ridiculously huge." },
  ["pineco"] = {   id=204, en="Pineco", zh="榛果球", type="Bug", species="Bagworm Pokémon", desc="It sticks tree bark to itself with its saliva, making itself thicker and larger. Elderly Pineco are ridiculously huge." },
  ["佛烈托斯"] = {   id=205, en="Forretress", zh="佛烈托斯", type="Bug, Steel", species="Bagworm Pokémon", desc="In the moment that it gulps down its prey, the inside of its shell is exposed, but to this day, no one has ever seen that sight." },
  ["forretress"] = {   id=205, en="Forretress", zh="佛烈托斯", type="Bug, Steel", species="Bagworm Pokémon", desc="In the moment that it gulps down its prey, the inside of its shell is exposed, but to this day, no one has ever seen that sight." },
  ["土龙弟弟"] = {   id=206, en="Dunsparce", zh="土龙弟弟", type="Normal", species="Land Snake Pokémon", desc="When it sees a person, it digs a hole with its tail to make its escape. If you happen to find one, consider yourself lucky." },
  ["dunsparce"] = {   id=206, en="Dunsparce", zh="土龙弟弟", type="Normal", species="Land Snake Pokémon", desc="When it sees a person, it digs a hole with its tail to make its escape. If you happen to find one, consider yourself lucky." },
  ["天蝎"] = {   id=207, en="Gligar", zh="天蝎", type="Ground, Flying", species="Fly Scorpion Pokémon", desc="Gligar glides through the air without a sound as if it were sliding. This Pokémon hangs on to the face of its foe using its clawed hind legs and the large pincers on its forelegs, then injects the prey with its poison barb." },
  ["gligar"] = {   id=207, en="Gligar", zh="天蝎", type="Ground, Flying", species="Fly Scorpion Pokémon", desc="Gligar glides through the air without a sound as if it were sliding. This Pokémon hangs on to the face of its foe using its clawed hind legs and the large pincers on its forelegs, then injects the prey with its poison barb." },
  ["大钢蛇"] = {   id=208, en="Steelix", zh="大钢蛇", type="Steel, Ground", species="Iron Snake Pokémon", desc="Steelix lives even further underground than Onix. This Pokémon is known to dig toward the earth’s core. There are records of this Pokémon reaching a depth of over six-tenths of a mile underground." },
  ["steelix"] = {   id=208, en="Steelix", zh="大钢蛇", type="Steel, Ground", species="Iron Snake Pokémon", desc="Steelix lives even further underground than Onix. This Pokémon is known to dig toward the earth’s core. There are records of this Pokémon reaching a depth of over six-tenths of a mile underground." },
  ["布鲁"] = {   id=209, en="Snubbull", zh="布鲁", type="Fairy", species="Fairy Pokémon", desc="In contrast to its appearance, it’s quite timid. When playing with other puppy Pokémon, it sometimes gets bullied." },
  ["snubbull"] = {   id=209, en="Snubbull", zh="布鲁", type="Fairy", species="Fairy Pokémon", desc="In contrast to its appearance, it’s quite timid. When playing with other puppy Pokémon, it sometimes gets bullied." },
  ["布鲁皇"] = {   id=210, en="Granbull", zh="布鲁皇", type="Fairy", species="Fairy Pokémon", desc="Although it’s popular with young people, Granbull is timid and sensitive, so it’s totally incompetent as a watchdog." },
  ["granbull"] = {   id=210, en="Granbull", zh="布鲁皇", type="Fairy", species="Fairy Pokémon", desc="Although it’s popular with young people, Granbull is timid and sensitive, so it’s totally incompetent as a watchdog." },
  ["千针鱼"] = {   id=211, en="Qwilfish", zh="千针鱼", type="Water, Poison", species="Balloon Pokémon", desc="Qwilfish sucks in water, inflating itself. This Pokémon uses the pressure of the water it swallowed to shoot toxic quills all at once from all over its body. It finds swimming somewhat challenging." },
  ["qwilfish"] = {   id=211, en="Qwilfish", zh="千针鱼", type="Water, Poison", species="Balloon Pokémon", desc="Qwilfish sucks in water, inflating itself. This Pokémon uses the pressure of the water it swallowed to shoot toxic quills all at once from all over its body. It finds swimming somewhat challenging." },
  ["巨钳螳螂"] = {   id=212, en="Scizor", zh="巨钳螳螂", type="Bug, Steel", species="Pincer Pokémon", desc="Once it has identified something as an enemy, it will continue beating them with its steel-hard pincers until there’s nothing left but scraps." },
  ["scizor"] = {   id=212, en="Scizor", zh="巨钳螳螂", type="Bug, Steel", species="Pincer Pokémon", desc="Once it has identified something as an enemy, it will continue beating them with its steel-hard pincers until there’s nothing left but scraps." },
  ["壶壶"] = {   id=213, en="Shuckle", zh="壶壶", type="Bug, Rock", species="Mold Pokémon", desc="Shuckle quietly hides itself under rocks, keeping its body concealed inside its hard shell while eating berries it has stored away. The berries mix with its body fluids to become a juice." },
  ["shuckle"] = {   id=213, en="Shuckle", zh="壶壶", type="Bug, Rock", species="Mold Pokémon", desc="Shuckle quietly hides itself under rocks, keeping its body concealed inside its hard shell while eating berries it has stored away. The berries mix with its body fluids to become a juice." },
  ["赫拉克罗斯"] = {   id=214, en="Heracross", zh="赫拉克罗斯", type="Bug, Fighting", species="Single Horn Pokémon", desc="It roams through forests searching for sweet nectar. Although it boasts fantastic physical strength, it’s not that good at flying." },
  ["heracross"] = {   id=214, en="Heracross", zh="赫拉克罗斯", type="Bug, Fighting", species="Single Horn Pokémon", desc="It roams through forests searching for sweet nectar. Although it boasts fantastic physical strength, it’s not that good at flying." },
  ["狃拉"] = {   id=215, en="Sneasel", zh="狃拉", type="Dark, Ice", species="Sharp Claw Pokémon", desc="It blends into the dark of night to ambush its prey. Sneasel will attack Sandshrew, but its hard skin can cause Sneasel’s claws to snap off." },
  ["sneasel"] = {   id=215, en="Sneasel", zh="狃拉", type="Dark, Ice", species="Sharp Claw Pokémon", desc="It blends into the dark of night to ambush its prey. Sneasel will attack Sandshrew, but its hard skin can cause Sneasel’s claws to snap off." },
  ["熊宝宝"] = {   id=216, en="Teddiursa", zh="熊宝宝", type="Normal", species="Little Bear Pokémon", desc="This Pokémon likes to lick its palms that are sweetened by being soaked in honey. Teddiursa concocts its own honey by blending fruits and pollen collected by Beedrill." },
  ["teddiursa"] = {   id=216, en="Teddiursa", zh="熊宝宝", type="Normal", species="Little Bear Pokémon", desc="This Pokémon likes to lick its palms that are sweetened by being soaked in honey. Teddiursa concocts its own honey by blending fruits and pollen collected by Beedrill." },
  ["圈圈熊"] = {   id=217, en="Ursaring", zh="圈圈熊", type="Normal", species="Hibernator Pokémon", desc="In the forests inhabited by Ursaring, it is said that there are many streams and towering trees where they gather food. This Pokémon walks through its forest gathering food every day." },
  ["ursaring"] = {   id=217, en="Ursaring", zh="圈圈熊", type="Normal", species="Hibernator Pokémon", desc="In the forests inhabited by Ursaring, it is said that there are many streams and towering trees where they gather food. This Pokémon walks through its forest gathering food every day." },
  ["熔岩虫"] = {   id=218, en="Slugma", zh="熔岩虫", type="Fire", species="Lava Pokémon", desc="Slugma does not have any blood in its body. Instead, intensely hot magma circulates throughout this Pokémon’s body, carrying essential nutrients and oxygen to its organs." },
  ["slugma"] = {   id=218, en="Slugma", zh="熔岩虫", type="Fire", species="Lava Pokémon", desc="Slugma does not have any blood in its body. Instead, intensely hot magma circulates throughout this Pokémon’s body, carrying essential nutrients and oxygen to its organs." },
  ["熔岩蜗牛"] = {   id=219, en="Magcargo", zh="熔岩蜗牛", type="Fire, Rock", species="Lava Pokémon", desc="Magcargo’s body temperature is approximately 18,000 degrees Fahrenheit. Water is vaporized on contact. If this Pokémon is caught in the rain, the raindrops instantly turn into steam, cloaking the area in a thick fog." },
  ["magcargo"] = {   id=219, en="Magcargo", zh="熔岩蜗牛", type="Fire, Rock", species="Lava Pokémon", desc="Magcargo’s body temperature is approximately 18,000 degrees Fahrenheit. Water is vaporized on contact. If this Pokémon is caught in the rain, the raindrops instantly turn into steam, cloaking the area in a thick fog." },
  ["小山猪"] = {   id=220, en="Swinub", zh="小山猪", type="Ice, Ground", species="Pig Pokémon", desc="Swinub roots for food by rubbing its snout against the ground. Its favorite food is a mushroom that grows under the cover of dead grass. This Pokémon occasionally roots out hot springs." },
  ["swinub"] = {   id=220, en="Swinub", zh="小山猪", type="Ice, Ground", species="Pig Pokémon", desc="Swinub roots for food by rubbing its snout against the ground. Its favorite food is a mushroom that grows under the cover of dead grass. This Pokémon occasionally roots out hot springs." },
  ["长毛猪"] = {   id=221, en="Piloswine", zh="长毛猪", type="Ice, Ground", species="Swine Pokémon", desc="Piloswine is covered by a thick coat of long hair that enables it to endure the freezing cold. This Pokémon uses its tusks to dig up food that has been buried under ice." },
  ["piloswine"] = {   id=221, en="Piloswine", zh="长毛猪", type="Ice, Ground", species="Swine Pokémon", desc="Piloswine is covered by a thick coat of long hair that enables it to endure the freezing cold. This Pokémon uses its tusks to dig up food that has been buried under ice." },
  ["太阳珊瑚"] = {   id=222, en="Corsola", zh="太阳珊瑚", type="Water, Rock", species="Coral Pokémon", desc="In Alola, where their natural enemies Mareanie are plentiful, many Corsola have stubby branches on their heads." },
  ["corsola"] = {   id=222, en="Corsola", zh="太阳珊瑚", type="Water, Rock", species="Coral Pokémon", desc="In Alola, where their natural enemies Mareanie are plentiful, many Corsola have stubby branches on their heads." },
  ["铁炮鱼"] = {   id=223, en="Remoraid", zh="铁炮鱼", type="Water", species="Jet Pokémon", desc="Also known as the “sniper of the seas,” its water gun can hit prey without fail from over 300 feet away." },
  ["remoraid"] = {   id=223, en="Remoraid", zh="铁炮鱼", type="Water", species="Jet Pokémon", desc="Also known as the “sniper of the seas,” its water gun can hit prey without fail from over 300 feet away." },
  ["章鱼桶"] = {   id=224, en="Octillery", zh="章鱼桶", type="Water", species="Jet Pokémon", desc="It usually sleeps in caves. The pitch-black ink that Octillery spits is also used for cooking." },
  ["octillery"] = {   id=224, en="Octillery", zh="章鱼桶", type="Water", species="Jet Pokémon", desc="It usually sleeps in caves. The pitch-black ink that Octillery spits is also used for cooking." },
  ["信使鸟"] = {   id=225, en="Delibird", zh="信使鸟", type="Ice, Flying", species="Delivery Pokémon", desc="It wraps food in its tail to carry it around. The Delibird with the biggest tail is the boss of the flock!" },
  ["delibird"] = {   id=225, en="Delibird", zh="信使鸟", type="Ice, Flying", species="Delivery Pokémon", desc="It wraps food in its tail to carry it around. The Delibird with the biggest tail is the boss of the flock!" },
  ["巨翅飞鱼"] = {   id=226, en="Mantine", zh="巨翅飞鱼", type="Water, Flying", species="Kite Pokémon", desc="Many people have taken up surfing because they admire how magnificently Mantine swims." },
