  ["盔甲鸟"] = {   id=227, en="Skarmory", zh="盔甲鸟", type="Steel, Flying", species="Armor Bird Pokémon", desc="Its body is draped in steel armor. It looks heavy, but it can fly at speeds of up to 185 miles an hour!" },
  ["skarmory"] = {   id=227, en="Skarmory", zh="盔甲鸟", type="Steel, Flying", species="Armor Bird Pokémon", desc="Its body is draped in steel armor. It looks heavy, but it can fly at speeds of up to 185 miles an hour!" },
  ["戴鲁比"] = {   id=228, en="Houndour", zh="戴鲁比", type="Dark, Fire", species="Dark Pokémon", desc="They make repeated eerie howls before dawn to call attention to their pack." },
  ["houndour"] = {   id=228, en="Houndour", zh="戴鲁比", type="Dark, Fire", species="Dark Pokémon", desc="They make repeated eerie howls before dawn to call attention to their pack." },
  ["黑鲁加"] = {   id=229, en="Houndoom", zh="黑鲁加", type="Dark, Fire", species="Dark Pokémon", desc="Identifiable by its eerie howls, people a long time ago thought it was the grim reaper and feared it." },
  ["houndoom"] = {   id=229, en="Houndoom", zh="黑鲁加", type="Dark, Fire", species="Dark Pokémon", desc="Identifiable by its eerie howls, people a long time ago thought it was the grim reaper and feared it." },
  ["刺龙王"] = {   id=230, en="Kingdra", zh="刺龙王", type="Water, Dragon", species="Dragon Pokémon", desc="Kingdra sleeps on the seafloor where it is otherwise devoid of life. When a storm arrives, the Pokémon is said to awaken and wander about in search of prey." },
  ["kingdra"] = {   id=230, en="Kingdra", zh="刺龙王", type="Water, Dragon", species="Dragon Pokémon", desc="Kingdra sleeps on the seafloor where it is otherwise devoid of life. When a storm arrives, the Pokémon is said to awaken and wander about in search of prey." },
  ["小小象"] = {   id=231, en="Phanpy", zh="小小象", type="Ground", species="Long Nose Pokémon", desc="Phanpy uses its long nose to shower itself. When others gather around, they thoroughly douse each other with water. These Pokémon can be seen drying their soaking-wet bodies at the edge of water." },
  ["phanpy"] = {   id=231, en="Phanpy", zh="小小象", type="Ground", species="Long Nose Pokémon", desc="Phanpy uses its long nose to shower itself. When others gather around, they thoroughly douse each other with water. These Pokémon can be seen drying their soaking-wet bodies at the edge of water." },
  ["顿甲"] = {   id=232, en="Donphan", zh="顿甲", type="Ground", species="Armor Pokémon", desc="If Donphan were to tackle with its hard body, even a house could be destroyed. Using its massive strength, the Pokémon helps clear rock and mud slides that block mountain trails." },
  ["donphan"] = {   id=232, en="Donphan", zh="顿甲", type="Ground", species="Armor Pokémon", desc="If Donphan were to tackle with its hard body, even a house could be destroyed. Using its massive strength, the Pokémon helps clear rock and mud slides that block mountain trails." },
  ["多边兽ⅱ"] = {   id=233, en="Porygon2", zh="多边兽Ⅱ", type="Normal", species="Virtual Pokémon", desc="Even though it doesn’t die in the vacuum of space, it can’t move around very well in zero gravity." },
