  ["惊角鹿"] = {   id=234, en="Stantler", zh="惊角鹿", type="Normal", species="Big Horn Pokémon", desc="Stantler’s magnificent antlers were traded at high prices as works of art. As a result, this Pokémon was hunted close to extinction by those who were after the priceless antlers." },
