  ["图图犬"] = {   id=235, en="Smeargle", zh="图图犬", type="Normal", species="Painter Pokémon", desc="It draws symbols with the fluid that oozes from the tip of its tail. Depending on the symbol, Smeargle fanatics will pay big money for them." },
