  ["无畏小子"] = {   id=236, en="Tyrogue", zh="无畏小子", type="Fighting", species="Scuffle Pokémon", desc="Tyrogue becomes stressed out if it does not get to train every day. When raising this Pokémon, the Trainer must establish and uphold various training methods." },
  ["tyrogue"] = {   id=236, en="Tyrogue", zh="无畏小子", type="Fighting", species="Scuffle Pokémon", desc="Tyrogue becomes stressed out if it does not get to train every day. When raising this Pokémon, the Trainer must establish and uphold various training methods." },
  ["战舞郎"] = {   id=237, en="Hitmontop", zh="战舞郎", type="Fighting", species="Handstand Pokémon", desc="Hitmontop spins on its head at high speed, all the while delivering kicks. This technique is a remarkable mix of both offense and defense at the same time. The Pokémon travels faster spinning than it does walking." },
  ["hitmontop"] = {   id=237, en="Hitmontop", zh="战舞郎", type="Fighting", species="Handstand Pokémon", desc="Hitmontop spins on its head at high speed, all the while delivering kicks. This technique is a remarkable mix of both offense and defense at the same time. The Pokémon travels faster spinning than it does walking." },
  ["迷唇娃"] = {   id=238, en="Smoochum", zh="迷唇娃", type="Ice, Psychic", species="Kiss Pokémon", desc="Highly perceptive sensors, Smoochum’s lips are kept moist by its daily application of tree sap." },
  ["smoochum"] = {   id=238, en="Smoochum", zh="迷唇娃", type="Ice, Psychic", species="Kiss Pokémon", desc="Highly perceptive sensors, Smoochum’s lips are kept moist by its daily application of tree sap." },
  ["电击怪"] = {   id=239, en="Elekid", zh="电击怪", type="Electric", species="Electric Pokémon", desc="When its horns shine a bluish white, that’s the sign it’s fully charged. You’ll get a shocking jolt if you touch it!" },
  ["elekid"] = {   id=239, en="Elekid", zh="电击怪", type="Electric", species="Electric Pokémon", desc="When its horns shine a bluish white, that’s the sign it’s fully charged. You’ll get a shocking jolt if you touch it!" },
  ["鸭嘴宝宝"] = {   id=240, en="Magby", zh="鸭嘴宝宝", type="Fire", species="Live Coal Pokémon", desc="Its body temperature is always around 1,100 degrees Fahrenheit. If Magby falls into a small- enough pond, the whole thing will dry up." },
  ["magby"] = {   id=240, en="Magby", zh="鸭嘴宝宝", type="Fire", species="Live Coal Pokémon", desc="Its body temperature is always around 1,100 degrees Fahrenheit. If Magby falls into a small- enough pond, the whole thing will dry up." },
  ["大奶罐"] = {   id=241, en="Miltank", zh="大奶罐", type="Normal", species="Milk Cow Pokémon", desc="Its milk is delicious and chock-full of nutrients. However, if you drink too much, it could make your stomach hurt, so be careful." },
  ["miltank"] = {   id=241, en="Miltank", zh="大奶罐", type="Normal", species="Milk Cow Pokémon", desc="Its milk is delicious and chock-full of nutrients. However, if you drink too much, it could make your stomach hurt, so be careful." },
  ["幸福蛋"] = {   id=242, en="Blissey", zh="幸福蛋", type="Normal", species="Happiness Pokémon", desc="This Pokémon is overflowing with love. Only Chansey that share a strong bond with their Trainer can evolve, so people say." },
  ["blissey"] = {   id=242, en="Blissey", zh="幸福蛋", type="Normal", species="Happiness Pokémon", desc="This Pokémon is overflowing with love. Only Chansey that share a strong bond with their Trainer can evolve, so people say." },
  ["雷公"] = {   id=243, en="Raikou", zh="雷公", type="Electric", species="Thunder Pokémon", desc="Raikou embodies the speed of lightning. The roars of this Pokémon send shock waves shuddering through the air and shake the ground as if lightning bolts had come crashing down." },
  ["raikou"] = {   id=243, en="Raikou", zh="雷公", type="Electric", species="Thunder Pokémon", desc="Raikou embodies the speed of lightning. The roars of this Pokémon send shock waves shuddering through the air and shake the ground as if lightning bolts had come crashing down." },
  ["炎帝"] = {   id=244, en="Entei", zh="炎帝", type="Fire", species="Volcano Pokémon", desc="Entei embodies the passion of magma. This Pokémon is thought to have been born in the eruption of a volcano. It sends up massive bursts of fire that utterly consume all that they touch." },
  ["entei"] = {   id=244, en="Entei", zh="炎帝", type="Fire", species="Volcano Pokémon", desc="Entei embodies the passion of magma. This Pokémon is thought to have been born in the eruption of a volcano. It sends up massive bursts of fire that utterly consume all that they touch." },
  ["水君"] = {   id=245, en="Suicune", zh="水君", type="Water", species="Aurora Pokémon", desc="Suicune embodies the compassion of a pure spring of water. It runs across the land with gracefulness. This Pokémon has the power to purify dirty water." },
  ["suicune"] = {   id=245, en="Suicune", zh="水君", type="Water", species="Aurora Pokémon", desc="Suicune embodies the compassion of a pure spring of water. It runs across the land with gracefulness. This Pokémon has the power to purify dirty water." },
  ["幼基拉斯"] = {   id=246, en="Larvitar", zh="幼基拉斯", type="Rock, Ground", species="Rock Skin Pokémon", desc="Raised on nutrients it finds in the dirt, it eats roughly a mountain’s worth of dirt before it becomes a pupa." },
