  ["沙基拉斯"] = {   id=247, en="Pupitar", zh="沙基拉斯", type="Rock, Ground", species="Hard Shell Pokémon", desc="This dangerous pupa thrashes about. Its shell is as hard as bedrock, containing its gradually forming new body within." },
