  ["班基拉斯"] = {   id=248, en="Tyranitar", zh="班基拉斯", type="Rock, Dark", species="Armor Pokémon", desc="This Pokémon is a mobile disaster, leaving mountains crumbled and houses destroyed in its wake." },
  ["tyranitar"] = {   id=248, en="Tyranitar", zh="班基拉斯", type="Rock, Dark", species="Armor Pokémon", desc="This Pokémon is a mobile disaster, leaving mountains crumbled and houses destroyed in its wake." },
  ["洛奇亚"] = {   id=249, en="Lugia", zh="洛奇亚", type="Psychic, Flying", species="Diving Pokémon", desc="Lugia’s wings pack devastating power—a light fluttering of its wings can blow apart regular houses. As a result, this Pokémon chooses to live out of sight deep under the sea." },
  ["lugia"] = {   id=249, en="Lugia", zh="洛奇亚", type="Psychic, Flying", species="Diving Pokémon", desc="Lugia’s wings pack devastating power—a light fluttering of its wings can blow apart regular houses. As a result, this Pokémon chooses to live out of sight deep under the sea." },
  ["凤王"] = {   id=250, en="Ho-Oh", zh="凤王", type="Fire, Flying", species="Rainbow Pokémon", desc="Ho-Oh’s feathers glow in seven colors depending on the angle at which they are struck by light. These feathers are said to bring happiness to the bearers. This Pokémon is said to live at the foot of a rainbow." },
  ["ho-oh"] = {   id=250, en="Ho-Oh", zh="凤王", type="Fire, Flying", species="Rainbow Pokémon", desc="Ho-Oh’s feathers glow in seven colors depending on the angle at which they are struck by light. These feathers are said to bring happiness to the bearers. This Pokémon is said to live at the foot of a rainbow." },
  ["时拉比"] = {   id=251, en="Celebi", zh="时拉比", type="Psychic, Grass", species="Time Travel Pokémon", desc="This Pokémon came from the future by crossing over time. It is thought that so long as Celebi appears, a bright and shining future awaits us." },
  ["celebi"] = {   id=251, en="Celebi", zh="时拉比", type="Psychic, Grass", species="Time Travel Pokémon", desc="This Pokémon came from the future by crossing over time. It is thought that so long as Celebi appears, a bright and shining future awaits us." },
  ["木守宫"] = {   id=252, en="Treecko", zh="木守宫", type="Grass", species="Wood Gecko Pokémon", desc="Treecko is cool, calm, and collected—it never panics under any situation. If a bigger foe were to glare at this Pokémon, it would glare right back without conceding an inch of ground." },
  ["treecko"] = {   id=252, en="Treecko", zh="木守宫", type="Grass", species="Wood Gecko Pokémon", desc="Treecko is cool, calm, and collected—it never panics under any situation. If a bigger foe were to glare at this Pokémon, it would glare right back without conceding an inch of ground." },
  ["森林蜥蜴"] = {   id=253, en="Grovyle", zh="森林蜥蜴", type="Grass", species="Wood Gecko Pokémon", desc="This Pokémon adeptly flies from branch to branch in trees. In a forest, no Pokémon can ever hope to catch a fleeing Grovyle however fast they may be." },
  ["grovyle"] = {   id=253, en="Grovyle", zh="森林蜥蜴", type="Grass", species="Wood Gecko Pokémon", desc="This Pokémon adeptly flies from branch to branch in trees. In a forest, no Pokémon can ever hope to catch a fleeing Grovyle however fast they may be." },
  ["蜥蜴王"] = {   id=254, en="Sceptile", zh="蜥蜴王", type="Grass", species="Forest Pokémon", desc="Sceptile has seeds growing on its back. They are said to be bursting with nutrients that revitalize trees. This Pokémon raises the trees in a forest with loving care." },
  ["sceptile"] = {   id=254, en="Sceptile", zh="蜥蜴王", type="Grass", species="Forest Pokémon", desc="Sceptile has seeds growing on its back. They are said to be bursting with nutrients that revitalize trees. This Pokémon raises the trees in a forest with loving care." },
  ["火稚鸡"] = {   id=255, en="Torchic", zh="火稚鸡", type="Fire", species="Chick Pokémon", desc="Torchic has a place inside its body where it keeps its flame. Give it a hug—it will be glowing with warmth. This Pokémon is covered all over by a fluffy coat of down." },
  ["torchic"] = {   id=255, en="Torchic", zh="火稚鸡", type="Fire", species="Chick Pokémon", desc="Torchic has a place inside its body where it keeps its flame. Give it a hug—it will be glowing with warmth. This Pokémon is covered all over by a fluffy coat of down." },
  ["力壮鸡"] = {   id=256, en="Combusken", zh="力壮鸡", type="Fire, Fighting", species="Young Fowl Pokémon", desc="Combusken battles with the intensely hot flames it spews from its beak and with outstandingly destructive kicks. This Pokémon’s cry is very loud and distracting." },
  ["combusken"] = {   id=256, en="Combusken", zh="力壮鸡", type="Fire, Fighting", species="Young Fowl Pokémon", desc="Combusken battles with the intensely hot flames it spews from its beak and with outstandingly destructive kicks. This Pokémon’s cry is very loud and distracting." },
  ["火焰鸡"] = {   id=257, en="Blaziken", zh="火焰鸡", type="Fire, Fighting", species="Blaze Pokémon", desc="Blaziken has incredibly strong legs—it can easily clear a 30-story building in one leap. This Pokémon’s blazing punches leave its foes scorched and blackened." },
  ["blaziken"] = {   id=257, en="Blaziken", zh="火焰鸡", type="Fire, Fighting", species="Blaze Pokémon", desc="Blaziken has incredibly strong legs—it can easily clear a 30-story building in one leap. This Pokémon’s blazing punches leave its foes scorched and blackened." },
  ["水跃鱼"] = {   id=258, en="Mudkip", zh="水跃鱼", type="Water", species="Mud Fish Pokémon", desc="In water, Mudkip breathes using the gills on its cheeks. If it is faced with a tight situation in battle, this Pokémon will unleash its amazing power—it can crush rocks bigger than itself." },
  ["mudkip"] = {   id=258, en="Mudkip", zh="水跃鱼", type="Water", species="Mud Fish Pokémon", desc="In water, Mudkip breathes using the gills on its cheeks. If it is faced with a tight situation in battle, this Pokémon will unleash its amazing power—it can crush rocks bigger than itself." },
  ["沼跃鱼"] = {   id=259, en="Marshtomp", zh="沼跃鱼", type="Water, Ground", species="Mud Fish Pokémon", desc="Marshtomp is much faster at traveling through mud than it is at swimming. This Pokémon’s hindquarters exhibit obvious development, giving it the ability to walk on just its hind legs." },
  ["marshtomp"] = {   id=259, en="Marshtomp", zh="沼跃鱼", type="Water, Ground", species="Mud Fish Pokémon", desc="Marshtomp is much faster at traveling through mud than it is at swimming. This Pokémon’s hindquarters exhibit obvious development, giving it the ability to walk on just its hind legs." },
  ["巨沼怪"] = {   id=260, en="Swampert", zh="巨沼怪", type="Water, Ground", species="Mud Fish Pokémon", desc="Swampert predicts storms by sensing subtle differences in the sounds of waves and tidal winds with its fins. If a storm is approaching, it piles up boulders to protect itself." },
  ["swampert"] = {   id=260, en="Swampert", zh="巨沼怪", type="Water, Ground", species="Mud Fish Pokémon", desc="Swampert predicts storms by sensing subtle differences in the sounds of waves and tidal winds with its fins. If a storm is approaching, it piles up boulders to protect itself." },
  ["土狼犬"] = {   id=261, en="Poochyena", zh="土狼犬", type="Dark", species="Bite Pokémon", desc="Poochyena is an omnivore—it will eat anything. A distinguishing feature is how large its fangs are compared to its body. This Pokémon tries to intimidate its foes by making the hair on its tail bristle out." },
  ["poochyena"] = {   id=261, en="Poochyena", zh="土狼犬", type="Dark", species="Bite Pokémon", desc="Poochyena is an omnivore—it will eat anything. A distinguishing feature is how large its fangs are compared to its body. This Pokémon tries to intimidate its foes by making the hair on its tail bristle out." },
  ["大狼犬"] = {   id=262, en="Mightyena", zh="大狼犬", type="Dark", species="Bite Pokémon", desc="Mightyena travel and act as a pack in the wild. The memory of its life in the wild compels the Pokémon to obey only those Trainers that it recognizes to possess superior skill." },
  ["mightyena"] = {   id=262, en="Mightyena", zh="大狼犬", type="Dark", species="Bite Pokémon", desc="Mightyena travel and act as a pack in the wild. The memory of its life in the wild compels the Pokémon to obey only those Trainers that it recognizes to possess superior skill." },
  ["蛇纹熊"] = {   id=263, en="Zigzagoon", zh="蛇纹熊", type="Normal", species="Tiny Raccoon Pokémon", desc="The hair on Zigzagoon’s back is bristly. It rubs the hard back hair against trees to leave its territorial markings. This Pokémon may play dead to fool foes in battle." },
  ["zigzagoon"] = {   id=263, en="Zigzagoon", zh="蛇纹熊", type="Normal", species="Tiny Raccoon Pokémon", desc="The hair on Zigzagoon’s back is bristly. It rubs the hard back hair against trees to leave its territorial markings. This Pokémon may play dead to fool foes in battle." },
  ["直冲熊"] = {   id=264, en="Linoone", zh="直冲熊", type="Normal", species="Rushing Pokémon", desc="When hunting, Linoone will make a beeline straight for the prey at a full run. While this Pokémon is capable of topping 60 mph, it has to come to a screeching halt before it can turn." },
  ["linoone"] = {   id=264, en="Linoone", zh="直冲熊", type="Normal", species="Rushing Pokémon", desc="When hunting, Linoone will make a beeline straight for the prey at a full run. While this Pokémon is capable of topping 60 mph, it has to come to a screeching halt before it can turn." },
  ["刺尾虫"] = {   id=265, en="Wurmple", zh="刺尾虫", type="Bug", species="Worm Pokémon", desc="Wurmple is targeted by Swellow as prey. This Pokémon will try to resist by pointing the spikes on its rear at the attacking predator. It will weaken the foe by leaking poison from the spikes." },
  ["wurmple"] = {   id=265, en="Wurmple", zh="刺尾虫", type="Bug", species="Worm Pokémon", desc="Wurmple is targeted by Swellow as prey. This Pokémon will try to resist by pointing the spikes on its rear at the attacking predator. It will weaken the foe by leaking poison from the spikes." },
  ["甲壳茧"] = {   id=266, en="Silcoon", zh="甲壳茧", type="Bug", species="Cocoon Pokémon", desc="Silcoon was thought to endure hunger and not consume anything before its evolution. However, it is now thought that this Pokémon slakes its thirst by drinking rainwater that collects on its silk." },
  ["silcoon"] = {   id=266, en="Silcoon", zh="甲壳茧", type="Bug", species="Cocoon Pokémon", desc="Silcoon was thought to endure hunger and not consume anything before its evolution. However, it is now thought that this Pokémon slakes its thirst by drinking rainwater that collects on its silk." },
  ["狩猎凤蝶"] = {   id=267, en="Beautifly", zh="狩猎凤蝶", type="Bug, Flying", species="Butterfly Pokémon", desc="Beautifly has a long mouth like a coiled needle, which is very convenient for collecting pollen from flowers. This Pokémon rides the spring winds as it flits around gathering pollen." },
  ["beautifly"] = {   id=267, en="Beautifly", zh="狩猎凤蝶", type="Bug, Flying", species="Butterfly Pokémon", desc="Beautifly has a long mouth like a coiled needle, which is very convenient for collecting pollen from flowers. This Pokémon rides the spring winds as it flits around gathering pollen." },
  ["盾甲茧"] = {   id=268, en="Cascoon", zh="盾甲茧", type="Bug", species="Cocoon Pokémon", desc="If it is attacked, Cascoon remains motionless however badly it may be hurt. It does so because if it were to move, its body would be weak upon evolution. This Pokémon will also not forget the pain it endured." },
  ["cascoon"] = {   id=268, en="Cascoon", zh="盾甲茧", type="Bug", species="Cocoon Pokémon", desc="If it is attacked, Cascoon remains motionless however badly it may be hurt. It does so because if it were to move, its body would be weak upon evolution. This Pokémon will also not forget the pain it endured." },
  ["毒粉蛾"] = {   id=269, en="Dustox", zh="毒粉蛾", type="Bug, Poison", species="Poison Moth Pokémon", desc="When Dustox flaps its wings, a fine dust is scattered all over. This dust is actually a powerful poison that will even make a pro wrestler sick. This Pokémon searches for food using its antennae like radar." },
  ["dustox"] = {   id=269, en="Dustox", zh="毒粉蛾", type="Bug, Poison", species="Poison Moth Pokémon", desc="When Dustox flaps its wings, a fine dust is scattered all over. This dust is actually a powerful poison that will even make a pro wrestler sick. This Pokémon searches for food using its antennae like radar." },
  ["莲叶童子"] = {   id=270, en="Lotad", zh="莲叶童子", type="Water, Grass", species="Water Weed Pokémon", desc="Lotad is said to have dwelled on land before. However, this Pokémon is thought to have returned to water because the leaf on its head grew large and heavy. It now lives by floating atop the water." },
  ["lotad"] = {   id=270, en="Lotad", zh="莲叶童子", type="Water, Grass", species="Water Weed Pokémon", desc="Lotad is said to have dwelled on land before. However, this Pokémon is thought to have returned to water because the leaf on its head grew large and heavy. It now lives by floating atop the water." },
  ["莲帽小童"] = {   id=271, en="Lombre", zh="莲帽小童", type="Water, Grass", species="Jolly Pokémon", desc="Lombre’s entire body is covered by a slippery, slimy film. It feels horribly unpleasant to be touched by this Pokémon’s hands. Lombre is often mistaken for a human child." },
  ["lombre"] = {   id=271, en="Lombre", zh="莲帽小童", type="Water, Grass", species="Jolly Pokémon", desc="Lombre’s entire body is covered by a slippery, slimy film. It feels horribly unpleasant to be touched by this Pokémon’s hands. Lombre is often mistaken for a human child." },
  ["乐天河童"] = {   id=272, en="Ludicolo", zh="乐天河童", type="Water, Grass", species="Carefree Pokémon", desc="Upon hearing an upbeat and cheerful rhythm, the cells in Ludicolo’s body become very energetic and active. Even in battle, this Pokémon will exhibit an amazing amount of power." },
  ["ludicolo"] = {   id=272, en="Ludicolo", zh="乐天河童", type="Water, Grass", species="Carefree Pokémon", desc="Upon hearing an upbeat and cheerful rhythm, the cells in Ludicolo’s body become very energetic and active. Even in battle, this Pokémon will exhibit an amazing amount of power." },
  ["橡实果"] = {   id=273, en="Seedot", zh="橡实果", type="Grass", species="Acorn Pokémon", desc="Seedot looks exactly like an acorn when it is dangling from a tree branch. It startles other Pokémon by suddenly moving. This Pokémon polishes its body once a day using leaves." },
  ["seedot"] = {   id=273, en="Seedot", zh="橡实果", type="Grass", species="Acorn Pokémon", desc="Seedot looks exactly like an acorn when it is dangling from a tree branch. It startles other Pokémon by suddenly moving. This Pokémon polishes its body once a day using leaves." },
  ["长鼻叶"] = {   id=274, en="Nuzleaf", zh="长鼻叶", type="Grass, Dark", species="Wily Pokémon", desc="This Pokémon pulls out the leaf on its head and makes a flute with it. The sound of Nuzleaf’s flute strikes fear and uncertainty in the hearts of people lost in a forest." },
  ["nuzleaf"] = {   id=274, en="Nuzleaf", zh="长鼻叶", type="Grass, Dark", species="Wily Pokémon", desc="This Pokémon pulls out the leaf on its head and makes a flute with it. The sound of Nuzleaf’s flute strikes fear and uncertainty in the hearts of people lost in a forest." },
  ["狡猾天狗"] = {   id=275, en="Shiftry", zh="狡猾天狗", type="Grass, Dark", species="Wicked Pokémon", desc="Shiftry’s large fans generate awesome gusts of wind at a speed close to 100 feet per second. The whipped-up wind blows anything away. This Pokémon chooses to live quietly deep in forests." },
  ["shiftry"] = {   id=275, en="Shiftry", zh="狡猾天狗", type="Grass, Dark", species="Wicked Pokémon", desc="Shiftry’s large fans generate awesome gusts of wind at a speed close to 100 feet per second. The whipped-up wind blows anything away. This Pokémon chooses to live quietly deep in forests." },
  ["傲骨燕"] = {   id=276, en="Taillow", zh="傲骨燕", type="Normal, Flying", species="Tiny Swallow Pokémon", desc="Taillow is young—it has only just left its nest. As a result, it sometimes becomes lonesome and cries at night. This Pokémon feeds on Wurmple that live in forests." },
  ["taillow"] = {   id=276, en="Taillow", zh="傲骨燕", type="Normal, Flying", species="Tiny Swallow Pokémon", desc="Taillow is young—it has only just left its nest. As a result, it sometimes becomes lonesome and cries at night. This Pokémon feeds on Wurmple that live in forests." },
  ["大王燕"] = {   id=277, en="Swellow", zh="大王燕", type="Normal, Flying", species="Swallow Pokémon", desc="Swellow is very conscientious about the upkeep of its glossy wings. Once two Swellow are gathered, they diligently take care of cleaning each other’s wings." },
  ["swellow"] = {   id=277, en="Swellow", zh="大王燕", type="Normal, Flying", species="Swallow Pokémon", desc="Swellow is very conscientious about the upkeep of its glossy wings. Once two Swellow are gathered, they diligently take care of cleaning each other’s wings." },
  ["长翅鸥"] = {   id=278, en="Wingull", zh="长翅鸥", type="Water, Flying", species="Seagull Pokémon", desc="It builds nests in cliffs by the sea. It circles the skies above the ocean looking for its favorite food—Wishiwashi." },
  ["wingull"] = {   id=278, en="Wingull", zh="长翅鸥", type="Water, Flying", species="Seagull Pokémon", desc="It builds nests in cliffs by the sea. It circles the skies above the ocean looking for its favorite food—Wishiwashi." },
  ["大嘴鸥"] = {   id=279, en="Pelipper", zh="大嘴鸥", type="Water, Flying", species="Water Bird Pokémon", desc="It scoops up Wishiwashi in its huge beak and swallows them whole. It can devour more than 30 at one go!" },
  ["pelipper"] = {   id=279, en="Pelipper", zh="大嘴鸥", type="Water, Flying", species="Water Bird Pokémon", desc="It scoops up Wishiwashi in its huge beak and swallows them whole. It can devour more than 30 at one go!" },
  ["拉鲁拉丝"] = {   id=280, en="Ralts", zh="拉鲁拉丝", type="Psychic, Fairy", species="Feeling Pokémon", desc="Ralts has the ability to sense the emotions of people. If its Trainer is in a cheerful mood, this Pokémon grows cheerful and joyous in the same way." },
  ["ralts"] = {   id=280, en="Ralts", zh="拉鲁拉丝", type="Psychic, Fairy", species="Feeling Pokémon", desc="Ralts has the ability to sense the emotions of people. If its Trainer is in a cheerful mood, this Pokémon grows cheerful and joyous in the same way." },
  ["奇鲁莉安"] = {   id=281, en="Kirlia", zh="奇鲁莉安", type="Psychic, Fairy", species="Emotion Pokémon", desc="Kirlia uses the horns on its head to amplify its psychokinetic power. When the Pokémon uses its power, the air around it becomes distorted, creating mirages of nonexistent scenery." },
  ["kirlia"] = {   id=281, en="Kirlia", zh="奇鲁莉安", type="Psychic, Fairy", species="Emotion Pokémon", desc="Kirlia uses the horns on its head to amplify its psychokinetic power. When the Pokémon uses its power, the air around it becomes distorted, creating mirages of nonexistent scenery." },
  ["沙奈朵"] = {   id=282, en="Gardevoir", zh="沙奈朵", type="Psychic, Fairy", species="Embrace Pokémon", desc="Gardevoir has the psychokinetic power to distort the dimensions and create a small black hole. This Pokémon will try to protect its Trainer even at the risk of its own life." },
  ["gardevoir"] = {   id=282, en="Gardevoir", zh="沙奈朵", type="Psychic, Fairy", species="Embrace Pokémon", desc="Gardevoir has the psychokinetic power to distort the dimensions and create a small black hole. This Pokémon will try to protect its Trainer even at the risk of its own life." },
  ["溜溜糖球"] = {   id=283, en="Surskit", zh="溜溜糖球", type="Bug, Water", species="Pond Skater Pokémon", desc="It lives in ponds and marshes that feature lots of plant life. It often fights with Dewpider, whose habitat and diet are similar." },
  ["surskit"] = {   id=283, en="Surskit", zh="溜溜糖球", type="Bug, Water", species="Pond Skater Pokémon", desc="It lives in ponds and marshes that feature lots of plant life. It often fights with Dewpider, whose habitat and diet are similar." },
  ["雨翅蛾"] = {   id=284, en="Masquerain", zh="雨翅蛾", type="Bug, Flying", species="Eyeball Pokémon", desc="Its thin, winglike antennae are highly absorbent. It waits out rainy days in tree hollows." },
  ["masquerain"] = {   id=284, en="Masquerain", zh="雨翅蛾", type="Bug, Flying", species="Eyeball Pokémon", desc="Its thin, winglike antennae are highly absorbent. It waits out rainy days in tree hollows." },
  ["蘑蘑菇"] = {   id=285, en="Shroomish", zh="蘑蘑菇", type="Grass", species="Mushroom Pokémon", desc="If Shroomish senses danger, it shakes its body and scatters spores from the top of its head. This Pokémon’s spores are so toxic, they make trees and weeds wilt." },
  ["shroomish"] = {   id=285, en="Shroomish", zh="蘑蘑菇", type="Grass", species="Mushroom Pokémon", desc="If Shroomish senses danger, it shakes its body and scatters spores from the top of its head. This Pokémon’s spores are so toxic, they make trees and weeds wilt." },
  ["斗笠菇"] = {   id=286, en="Breloom", zh="斗笠菇", type="Grass, Fighting", species="Mushroom Pokémon", desc="The seeds ringing Breloom’s tail are made of hardened toxic spores. It is horrible to eat the seeds. Just taking a bite of this Pokémon’s seed will cause your stomach to rumble." },
  ["breloom"] = {   id=286, en="Breloom", zh="斗笠菇", type="Grass, Fighting", species="Mushroom Pokémon", desc="The seeds ringing Breloom’s tail are made of hardened toxic spores. It is horrible to eat the seeds. Just taking a bite of this Pokémon’s seed will cause your stomach to rumble." },
  ["懒人獭"] = {   id=287, en="Slakoth", zh="懒人獭", type="Normal", species="Slacker Pokémon", desc="Slakoth’s heart beats just once a minute. Whatever happens, it is content to loaf around motionless. It is rare to see this Pokémon in motion." },
  ["slakoth"] = {   id=287, en="Slakoth", zh="懒人獭", type="Normal", species="Slacker Pokémon", desc="Slakoth’s heart beats just once a minute. Whatever happens, it is content to loaf around motionless. It is rare to see this Pokémon in motion." },
  ["过动猿"] = {   id=288, en="Vigoroth", zh="过动猿", type="Normal", species="Wild Monkey Pokémon", desc="Vigoroth is simply incapable of remaining still. Even when it tries to sleep, the blood in its veins grows agitated, compelling this Pokémon to run wild throughout the jungle before it can settle down." },
  ["vigoroth"] = {   id=288, en="Vigoroth", zh="过动猿", type="Normal", species="Wild Monkey Pokémon", desc="Vigoroth is simply incapable of remaining still. Even when it tries to sleep, the blood in its veins grows agitated, compelling this Pokémon to run wild throughout the jungle before it can settle down." },
  ["请假王"] = {   id=289, en="Slaking", zh="请假王", type="Normal", species="Lazy Pokémon", desc="Wherever Slaking live, rings of over a yard in diameter appear in grassy fields. They are made by the Pokémon as it eats all the grass within reach while lying prone on the ground." },
  ["slaking"] = {   id=289, en="Slaking", zh="请假王", type="Normal", species="Lazy Pokémon", desc="Wherever Slaking live, rings of over a yard in diameter appear in grassy fields. They are made by the Pokémon as it eats all the grass within reach while lying prone on the ground." },
  ["土居忍士"] = {   id=290, en="Nincada", zh="土居忍士", type="Bug, Ground", species="Trainee Pokémon", desc="Nincada lives underground. It uses its sharp claws to carve the roots of trees and absorb moisture and nutrients. This Pokémon can’t withstand bright sunlight so avoids it." },
  ["nincada"] = {   id=290, en="Nincada", zh="土居忍士", type="Bug, Ground", species="Trainee Pokémon", desc="Nincada lives underground. It uses its sharp claws to carve the roots of trees and absorb moisture and nutrients. This Pokémon can’t withstand bright sunlight so avoids it." },
  ["铁面忍者"] = {   id=291, en="Ninjask", zh="铁面忍者", type="Bug, Flying", species="Ninja Pokémon", desc="If Ninjask is not trained properly, it will refuse to obey the Trainer and cry loudly continuously. Because of this quality, this Pokémon is said to be one that puts the Trainer’s abilities to the test." },
  ["ninjask"] = {   id=291, en="Ninjask", zh="铁面忍者", type="Bug, Flying", species="Ninja Pokémon", desc="If Ninjask is not trained properly, it will refuse to obey the Trainer and cry loudly continuously. Because of this quality, this Pokémon is said to be one that puts the Trainer’s abilities to the test." },
  ["脱壳忍者"] = {   id=292, en="Shedinja", zh="脱壳忍者", type="Bug, Ghost", species="Shed Pokémon", desc="Shedinja is a peculiar Pokémon. It seems to appear unsought in a Poké Ball after a Nincada evolves. This bizarre Pokémon is entirely immobile—it doesn’t even breathe." },
  ["shedinja"] = {   id=292, en="Shedinja", zh="脱壳忍者", type="Bug, Ghost", species="Shed Pokémon", desc="Shedinja is a peculiar Pokémon. It seems to appear unsought in a Poké Ball after a Nincada evolves. This bizarre Pokémon is entirely immobile—it doesn’t even breathe." },
  ["咕妞妞"] = {   id=293, en="Whismur", zh="咕妞妞", type="Normal", species="Whisper Pokémon", desc="Whismur is very timid. If it starts to cry loudly, it becomes startled by its own crying and cries even harder. When it finally stops crying, the Pokémon goes to sleep, all tired out." },
  ["whismur"] = {   id=293, en="Whismur", zh="咕妞妞", type="Normal", species="Whisper Pokémon", desc="Whismur is very timid. If it starts to cry loudly, it becomes startled by its own crying and cries even harder. When it finally stops crying, the Pokémon goes to sleep, all tired out." },
  ["吼爆弹"] = {   id=294, en="Loudred", zh="吼爆弹", type="Normal", species="Big Voice Pokémon", desc="Loudred shouts while stamping its feet. After it finishes shouting, this Pokémon becomes incapable of hearing anything for a while. This is considered to be a weak point." },
  ["loudred"] = {   id=294, en="Loudred", zh="吼爆弹", type="Normal", species="Big Voice Pokémon", desc="Loudred shouts while stamping its feet. After it finishes shouting, this Pokémon becomes incapable of hearing anything for a while. This is considered to be a weak point." },
  ["爆音怪"] = {   id=295, en="Exploud", zh="爆音怪", type="Normal", species="Loud Noise Pokémon", desc="Exploud communicates its feelings to the others by emitting whistle-like sounds from the tubes on its body. This Pokémon only raises its voice when it is in battle." },
  ["exploud"] = {   id=295, en="Exploud", zh="爆音怪", type="Normal", species="Loud Noise Pokémon", desc="Exploud communicates its feelings to the others by emitting whistle-like sounds from the tubes on its body. This Pokémon only raises its voice when it is in battle." },
  ["幕下力士"] = {   id=296, en="Makuhita", zh="幕下力士", type="Fighting", species="Guts Pokémon", desc="There’s a rumor of a traditional recipe for stew that Trainers can use to raise strong Makuhita." },
  ["makuhita"] = {   id=296, en="Makuhita", zh="幕下力士", type="Fighting", species="Guts Pokémon", desc="There’s a rumor of a traditional recipe for stew that Trainers can use to raise strong Makuhita." },
  ["铁掌力士"] = {   id=297, en="Hariyama", zh="铁掌力士", type="Fighting", species="Arm Thrust Pokémon", desc="Hariyama that are big and fat aren’t necessarily strong. There are some small ones that move nimbly and use moves skillfully." },
  ["hariyama"] = {   id=297, en="Hariyama", zh="铁掌力士", type="Fighting", species="Arm Thrust Pokémon", desc="Hariyama that are big and fat aren’t necessarily strong. There are some small ones that move nimbly and use moves skillfully." },
  ["露力丽"] = {   id=298, en="Azurill", zh="露力丽", type="Normal, Fairy", species="Polka Dot Pokémon", desc="Azurill’s tail is large and bouncy. It is packed full of the nutrients this Pokémon needs to grow. Azurill can be seen bouncing and playing on its big, rubbery tail." },
  ["azurill"] = {   id=298, en="Azurill", zh="露力丽", type="Normal, Fairy", species="Polka Dot Pokémon", desc="Azurill’s tail is large and bouncy. It is packed full of the nutrients this Pokémon needs to grow. Azurill can be seen bouncing and playing on its big, rubbery tail." },
  ["朝北鼻"] = {   id=299, en="Nosepass", zh="朝北鼻", type="Rock", species="Compass Pokémon", desc="It hunts without twitching a muscle by pulling in its prey with powerful magnetism. But sometimes it pulls natural enemies in close." },
  ["nosepass"] = {   id=299, en="Nosepass", zh="朝北鼻", type="Rock", species="Compass Pokémon", desc="It hunts without twitching a muscle by pulling in its prey with powerful magnetism. But sometimes it pulls natural enemies in close." },
  ["向尾喵"] = {   id=300, en="Skitty", zh="向尾喵", type="Normal", species="Kitten Pokémon", desc="Skitty is known to chase around playfully after its own tail. In the wild, this Pokémon lives in holes in the trees of forests. It is very popular as a pet because of its adorable looks." },
  ["skitty"] = {   id=300, en="Skitty", zh="向尾喵", type="Normal", species="Kitten Pokémon", desc="Skitty is known to chase around playfully after its own tail. In the wild, this Pokémon lives in holes in the trees of forests. It is very popular as a pet because of its adorable looks." },
  ["优雅猫"] = {   id=301, en="Delcatty", zh="优雅猫", type="Normal", species="Prim Pokémon", desc="Delcatty sleeps anywhere it wants without keeping a permanent nest. If other Pokémon approach it as it sleeps, this Pokémon will never fight—it will just move away somewhere else." },
  ["delcatty"] = {   id=301, en="Delcatty", zh="优雅猫", type="Normal", species="Prim Pokémon", desc="Delcatty sleeps anywhere it wants without keeping a permanent nest. If other Pokémon approach it as it sleeps, this Pokémon will never fight—it will just move away somewhere else." },
  ["勾魂眼"] = {   id=302, en="Sableye", zh="勾魂眼", type="Dark, Ghost", species="Darkness Pokémon", desc="Materials from gems it has eaten float to the surface of its body and can form an infinite number of patterns among individuals." },
  ["sableye"] = {   id=302, en="Sableye", zh="勾魂眼", type="Dark, Ghost", species="Darkness Pokémon", desc="Materials from gems it has eaten float to the surface of its body and can form an infinite number of patterns among individuals." },
  ["大嘴娃"] = {   id=303, en="Mawile", zh="大嘴娃", type="Steel, Fairy", species="Deceiver Pokémon", desc="It has two mouths. The big jaws on the back of its head can’t taste anything, so that’s the mouth it uses to eat foods it doesn’t like." },
  ["mawile"] = {   id=303, en="Mawile", zh="大嘴娃", type="Steel, Fairy", species="Deceiver Pokémon", desc="It has two mouths. The big jaws on the back of its head can’t taste anything, so that’s the mouth it uses to eat foods it doesn’t like." },
  ["可可多拉"] = {   id=304, en="Aron", zh="可可多拉", type="Steel, Rock", species="Iron Armor Pokémon", desc="Aron has a body of steel. With one all-out charge, this Pokémon can demolish even a heavy dump truck. The destroyed dump truck then becomes a handy meal for the Pokémon." },
  ["aron"] = {   id=304, en="Aron", zh="可可多拉", type="Steel, Rock", species="Iron Armor Pokémon", desc="Aron has a body of steel. With one all-out charge, this Pokémon can demolish even a heavy dump truck. The destroyed dump truck then becomes a handy meal for the Pokémon." },
  ["可多拉"] = {   id=305, en="Lairon", zh="可多拉", type="Steel, Rock", species="Iron Armor Pokémon", desc="Lairon feeds on iron contained in rocks and water. It makes its nest on mountains where iron ore is buried. As a result, the Pokémon often clashes with humans mining the iron ore." },
  ["lairon"] = {   id=305, en="Lairon", zh="可多拉", type="Steel, Rock", species="Iron Armor Pokémon", desc="Lairon feeds on iron contained in rocks and water. It makes its nest on mountains where iron ore is buried. As a result, the Pokémon often clashes with humans mining the iron ore." },
  ["波士可多拉"] = {   id=306, en="Aggron", zh="波士可多拉", type="Steel, Rock", species="Iron Armor Pokémon", desc="Aggron is protective of its environment. If its mountain is ravaged by a landslide or a fire, this Pokémon will haul topsoil to the area, plant trees, and beautifully restore its own territory." },
  ["aggron"] = {   id=306, en="Aggron", zh="波士可多拉", type="Steel, Rock", species="Iron Armor Pokémon", desc="Aggron is protective of its environment. If its mountain is ravaged by a landslide or a fire, this Pokémon will haul topsoil to the area, plant trees, and beautifully restore its own territory." },
  ["玛沙那"] = {   id=307, en="Meditite", zh="玛沙那", type="Fighting, Psychic", species="Meditate Pokémon", desc="Meditite heightens its inner energy through meditation. It survives on just one berry a day. Minimal eating is another aspect of this Pokémon’s training." },
  ["meditite"] = {   id=307, en="Meditite", zh="玛沙那", type="Fighting, Psychic", species="Meditate Pokémon", desc="Meditite heightens its inner energy through meditation. It survives on just one berry a day. Minimal eating is another aspect of this Pokémon’s training." },
  ["恰雷姆"] = {   id=308, en="Medicham", zh="恰雷姆", type="Fighting, Psychic", species="Meditate Pokémon", desc="Through the power of meditation, Medicham developed its sixth sense. It gained the ability to use psychokinetic powers. This Pokémon is known to meditate for a whole month without eating." },
  ["medicham"] = {   id=308, en="Medicham", zh="恰雷姆", type="Fighting, Psychic", species="Meditate Pokémon", desc="Through the power of meditation, Medicham developed its sixth sense. It gained the ability to use psychokinetic powers. This Pokémon is known to meditate for a whole month without eating." },
  ["落雷兽"] = {   id=309, en="Electrike", zh="落雷兽", type="Electric", species="Lightning Pokémon", desc="Static electricity builds up all over its body as strands of its long fur rub together. This Pokémon boasts incredible speed." },
  ["electrike"] = {   id=309, en="Electrike", zh="落雷兽", type="Electric", species="Lightning Pokémon", desc="Static electricity builds up all over its body as strands of its long fur rub together. This Pokémon boasts incredible speed." },
  ["雷电兽"] = {   id=310, en="Manectric", zh="雷电兽", type="Electric", species="Discharge Pokémon", desc="It stimulates its own muscles with electricity, so it can move quickly. It eases its soreness with electricity, too, so it can recover quickly as well." },
  ["manectric"] = {   id=310, en="Manectric", zh="雷电兽", type="Electric", species="Discharge Pokémon", desc="It stimulates its own muscles with electricity, so it can move quickly. It eases its soreness with electricity, too, so it can recover quickly as well." },
  ["正电拍拍"] = {   id=311, en="Plusle", zh="正电拍拍", type="Electric", species="Cheering Pokémon", desc="When Plusle is cheering on its partner, it flashes with electric sparks from all over its body. If its partner loses, this Pokémon cries loudly." },
  ["plusle"] = {   id=311, en="Plusle", zh="正电拍拍", type="Electric", species="Cheering Pokémon", desc="When Plusle is cheering on its partner, it flashes with electric sparks from all over its body. If its partner loses, this Pokémon cries loudly." },
  ["负电拍拍"] = {   id=312, en="Minun", zh="负电拍拍", type="Electric", species="Cheering Pokémon", desc="Minun loves to cheer on its partner in battle. It gives off sparks from its body while it is doing so. If its partner is in trouble, this Pokémon gives off increasing amounts of sparks." },
  ["minun"] = {   id=312, en="Minun", zh="负电拍拍", type="Electric", species="Cheering Pokémon", desc="Minun loves to cheer on its partner in battle. It gives off sparks from its body while it is doing so. If its partner is in trouble, this Pokémon gives off increasing amounts of sparks." },
  ["电萤虫"] = {   id=313, en="Volbeat", zh="电萤虫", type="Bug", species="Firefly Pokémon", desc="Volbeat’s tail glows like a lightbulb. With other Volbeat, it uses its tail to draw geometric shapes in the night sky. This Pokémon loves the sweet aroma given off by Illumise." },
  ["volbeat"] = {   id=313, en="Volbeat", zh="电萤虫", type="Bug", species="Firefly Pokémon", desc="Volbeat’s tail glows like a lightbulb. With other Volbeat, it uses its tail to draw geometric shapes in the night sky. This Pokémon loves the sweet aroma given off by Illumise." },
  ["甜甜萤"] = {   id=314, en="Illumise", zh="甜甜萤", type="Bug", species="Firefly Pokémon", desc="Illumise leads a flight of illuminated Volbeat to draw signs in the night sky. This Pokémon is said to earn greater respect from its peers by composing more complex designs in the sky." },
  ["illumise"] = {   id=314, en="Illumise", zh="甜甜萤", type="Bug", species="Firefly Pokémon", desc="Illumise leads a flight of illuminated Volbeat to draw signs in the night sky. This Pokémon is said to earn greater respect from its peers by composing more complex designs in the sky." },
  ["毒蔷薇"] = {   id=315, en="Roselia", zh="毒蔷薇", type="Grass, Poison", species="Thorn Pokémon", desc="On extremely rare occasions, a Roselia is said to appear with its flowers in unusual colors. The thorns on this Pokémon’s head contain a vicious poison." },
  ["roselia"] = {   id=315, en="Roselia", zh="毒蔷薇", type="Grass, Poison", species="Thorn Pokémon", desc="On extremely rare occasions, a Roselia is said to appear with its flowers in unusual colors. The thorns on this Pokémon’s head contain a vicious poison." },
  ["溶食兽"] = {   id=316, en="Gulpin", zh="溶食兽", type="Poison", species="Stomach Pokémon", desc="Most of Gulpin’s body is made up of its stomach—its heart and brain are very small in comparison. This Pokémon’s stomach contains special enzymes that dissolve anything." },
  ["gulpin"] = {   id=316, en="Gulpin", zh="溶食兽", type="Poison", species="Stomach Pokémon", desc="Most of Gulpin’s body is made up of its stomach—its heart and brain are very small in comparison. This Pokémon’s stomach contains special enzymes that dissolve anything." },
  ["吞食兽"] = {   id=317, en="Swalot", zh="吞食兽", type="Poison", species="Poison Bag Pokémon", desc="Swalot has no teeth, so what it eats, it swallows whole, no matter what. Its cavernous mouth yawns widely. An automobile tire could easily fit inside this Pokémon’s mouth." },
  ["swalot"] = {   id=317, en="Swalot", zh="吞食兽", type="Poison", species="Poison Bag Pokémon", desc="Swalot has no teeth, so what it eats, it swallows whole, no matter what. Its cavernous mouth yawns widely. An automobile tire could easily fit inside this Pokémon’s mouth." },
  ["利牙鱼"] = {   id=318, en="Carvanha", zh="利牙鱼", type="Water, Dark", species="Savage Pokémon", desc="With its sturdy jaws and fangs, it can easily chomp wooden boats to splinters. It fights with Basculin over food." },
  ["carvanha"] = {   id=318, en="Carvanha", zh="利牙鱼", type="Water, Dark", species="Savage Pokémon", desc="With its sturdy jaws and fangs, it can easily chomp wooden boats to splinters. It fights with Basculin over food." },
  ["巨牙鲨"] = {   id=319, en="Sharpedo", zh="巨牙鲨", type="Water, Dark", species="Brutal Pokémon", desc="It drinks in seawater and jets it from its rear to propel itself. It’s very sensitive to the scent of blood." },
  ["sharpedo"] = {   id=319, en="Sharpedo", zh="巨牙鲨", type="Water, Dark", species="Brutal Pokémon", desc="It drinks in seawater and jets it from its rear to propel itself. It’s very sensitive to the scent of blood." },
  ["吼吼鲸"] = {   id=320, en="Wailmer", zh="吼吼鲸", type="Water", species="Ball Whale Pokémon", desc="Due to their memories of when they once lived on land, pods of them will, very rarely, wash up on shore." },
  ["wailmer"] = {   id=320, en="Wailmer", zh="吼吼鲸", type="Water", species="Ball Whale Pokémon", desc="Due to their memories of when they once lived on land, pods of them will, very rarely, wash up on shore." },
  ["吼鲸王"] = {   id=321, en="Wailord", zh="吼鲸王", type="Water", species="Float Whale Pokémon", desc="When a small Wailmer is attacked by Sharpedo or Dhelmise, its whole pod works together to protect it." },
  ["wailord"] = {   id=321, en="Wailord", zh="吼鲸王", type="Water", species="Float Whale Pokémon", desc="When a small Wailmer is attacked by Sharpedo or Dhelmise, its whole pod works together to protect it." },
  ["呆火驼"] = {   id=322, en="Numel", zh="呆火驼", type="Fire, Ground", species="Numb Pokémon", desc="Numel stores magma of almost 2,200 degrees Fahrenheit within its body. If it gets wet, the magma cools and hardens. In that event, the Pokémon’s body grows heavy and its movements become sluggish." },
  ["numel"] = {   id=322, en="Numel", zh="呆火驼", type="Fire, Ground", species="Numb Pokémon", desc="Numel stores magma of almost 2,200 degrees Fahrenheit within its body. If it gets wet, the magma cools and hardens. In that event, the Pokémon’s body grows heavy and its movements become sluggish." },
  ["喷火驼"] = {   id=323, en="Camerupt", zh="喷火驼", type="Fire, Ground", species="Eruption Pokémon", desc="The humps on Camerupt’s back are formed by a transformation of its bones. They sometimes blast out molten magma. This Pokémon apparently erupts often when it is enraged." },
  ["camerupt"] = {   id=323, en="Camerupt", zh="喷火驼", type="Fire, Ground", species="Eruption Pokémon", desc="The humps on Camerupt’s back are formed by a transformation of its bones. They sometimes blast out molten magma. This Pokémon apparently erupts often when it is enraged." },
  ["煤炭龟"] = {   id=324, en="Torkoal", zh="煤炭龟", type="Fire", species="Coal Pokémon", desc="It burns coal to produce energy. When it has burned through all of its coal, it becomes unable to move." },
  ["torkoal"] = {   id=324, en="Torkoal", zh="煤炭龟", type="Fire", species="Coal Pokémon", desc="It burns coal to produce energy. When it has burned through all of its coal, it becomes unable to move." },
  ["跳跳猪"] = {   id=325, en="Spoink", zh="跳跳猪", type="Psychic", species="Bounce Pokémon", desc="Spoink keeps a pearl on top of its head. The pearl functions to amplify this Pokémon’s psychokinetic powers. It is therefore on a constant search for a bigger pearl." },
  ["spoink"] = {   id=325, en="Spoink", zh="跳跳猪", type="Psychic", species="Bounce Pokémon", desc="Spoink keeps a pearl on top of its head. The pearl functions to amplify this Pokémon’s psychokinetic powers. It is therefore on a constant search for a bigger pearl." },
  ["噗噗猪"] = {   id=326, en="Grumpig", zh="噗噗猪", type="Psychic", species="Manipulate Pokémon", desc="Grumpig uses the black pearls on its body to wield its fantastic powers. When it is doing so, it dances bizarrely. This Pokémon’s black pearls are valuable as works of art." },
  ["grumpig"] = {   id=326, en="Grumpig", zh="噗噗猪", type="Psychic", species="Manipulate Pokémon", desc="Grumpig uses the black pearls on its body to wield its fantastic powers. When it is doing so, it dances bizarrely. This Pokémon’s black pearls are valuable as works of art." },
  ["晃晃斑"] = {   id=327, en="Spinda", zh="晃晃斑", type="Normal", species="Spot Panda Pokémon", desc="Each Spinda’s spot pattern is different. With its stumbling movements, it evades opponents’ attacks brilliantly!" },
  ["spinda"] = {   id=327, en="Spinda", zh="晃晃斑", type="Normal", species="Spot Panda Pokémon", desc="Each Spinda’s spot pattern is different. With its stumbling movements, it evades opponents’ attacks brilliantly!" },
  ["大颚蚁"] = {   id=328, en="Trapinch", zh="大颚蚁", type="Ground", species="Ant Pit Pokémon", desc="It builds nests that double as traps, lying in wait for its prey to get caught. When night falls, it digs itself a spot beneath the sand to sleep." },
  ["trapinch"] = {   id=328, en="Trapinch", zh="大颚蚁", type="Ground", species="Ant Pit Pokémon", desc="It builds nests that double as traps, lying in wait for its prey to get caught. When night falls, it digs itself a spot beneath the sand to sleep." },
  ["超音波幼虫"] = {   id=329, en="Vibrava", zh="超音波幼虫", type="Ground, Dragon", species="Vibration Pokémon", desc="It vibrates its wings to send out odd sound waves. Trainers who are with it need earplugs." },
  ["vibrava"] = {   id=329, en="Vibrava", zh="超音波幼虫", type="Ground, Dragon", species="Vibration Pokémon", desc="It vibrates its wings to send out odd sound waves. Trainers who are with it need earplugs." },
  ["沙漠蜻蜓"] = {   id=330, en="Flygon", zh="沙漠蜻蜓", type="Ground, Dragon", species="Mystic Pokémon", desc="People continue to have their hearts stolen by its enchanting songs and find themselves stranded in the desert." },
  ["flygon"] = {   id=330, en="Flygon", zh="沙漠蜻蜓", type="Ground, Dragon", species="Mystic Pokémon", desc="People continue to have their hearts stolen by its enchanting songs and find themselves stranded in the desert." },
  ["刺球仙人掌"] = {   id=331, en="Cacnea", zh="刺球仙人掌", type="Grass", species="Cactus Pokémon", desc="The more arid and harsh the environment, the more pretty and fragrant a flower Cacnea grows. This Pokémon battles by wildly swinging its thorny arms." },
  ["cacnea"] = {   id=331, en="Cacnea", zh="刺球仙人掌", type="Grass", species="Cactus Pokémon", desc="The more arid and harsh the environment, the more pretty and fragrant a flower Cacnea grows. This Pokémon battles by wildly swinging its thorny arms." },
  ["梦歌仙人掌"] = {   id=332, en="Cacturne", zh="梦歌仙人掌", type="Grass, Dark", species="Scarecrow Pokémon", desc="If a traveler is going through a desert in the thick of night, Cacturne will follow in a ragtag group. The Pokémon are biding their time, waiting for the traveler to tire and become incapable of moving." },
  ["cacturne"] = {   id=332, en="Cacturne", zh="梦歌仙人掌", type="Grass, Dark", species="Scarecrow Pokémon", desc="If a traveler is going through a desert in the thick of night, Cacturne will follow in a ragtag group. The Pokémon are biding their time, waiting for the traveler to tire and become incapable of moving." },
  ["青绵鸟"] = {   id=333, en="Swablu", zh="青绵鸟", type="Normal, Flying", species="Cotton Bird Pokémon", desc="Swablu loves to make things clean. If it spots something dirty, it will wipe and polish it with its cottony wings. If its wings become dirty, this Pokémon finds a stream and showers itself." },
  ["swablu"] = {   id=333, en="Swablu", zh="青绵鸟", type="Normal, Flying", species="Cotton Bird Pokémon", desc="Swablu loves to make things clean. If it spots something dirty, it will wipe and polish it with its cottony wings. If its wings become dirty, this Pokémon finds a stream and showers itself." },
  ["七夕青鸟"] = {   id=334, en="Altaria", zh="七夕青鸟", type="Dragon, Flying", species="Humming Pokémon", desc="Altaria sings in a gorgeous soprano. Its wings are like cotton clouds. This Pokémon catches updrafts with its buoyant wings and soars way up into the wild blue yonder." },
  ["altaria"] = {   id=334, en="Altaria", zh="七夕青鸟", type="Dragon, Flying", species="Humming Pokémon", desc="Altaria sings in a gorgeous soprano. Its wings are like cotton clouds. This Pokémon catches updrafts with its buoyant wings and soars way up into the wild blue yonder." },
  ["猫鼬斩"] = {   id=335, en="Zangoose", zh="猫鼬斩", type="Normal", species="Cat Ferret Pokémon", desc="Zangoose usually stays on all fours, but when angered, it gets up on its hind legs and extends its claws. This Pokémon shares a bitter rivalry with Seviper that dates back over generations." },
  ["zangoose"] = {   id=335, en="Zangoose", zh="猫鼬斩", type="Normal", species="Cat Ferret Pokémon", desc="Zangoose usually stays on all fours, but when angered, it gets up on its hind legs and extends its claws. This Pokémon shares a bitter rivalry with Seviper that dates back over generations." },
  ["饭匙蛇"] = {   id=336, en="Seviper", zh="饭匙蛇", type="Poison", species="Fang Snake Pokémon", desc="Seviper’s swordlike tail serves two purposes—it slashes foes and douses them with secreted poison. This Pokémon will not give up its long-running blood feud with Zangoose." },
  ["seviper"] = {   id=336, en="Seviper", zh="饭匙蛇", type="Poison", species="Fang Snake Pokémon", desc="Seviper’s swordlike tail serves two purposes—it slashes foes and douses them with secreted poison. This Pokémon will not give up its long-running blood feud with Zangoose." },
  ["月石"] = {   id=337, en="Lunatone", zh="月石", type="Rock, Psychic", species="Meteorite Pokémon", desc="Lunatone becomes active around the time of the full moon. Instead of walking, it moves by floating in midair. The Pokémon’s intimidating red eyes cause all those who see it to become transfixed with fear." },
  ["lunatone"] = {   id=337, en="Lunatone", zh="月石", type="Rock, Psychic", species="Meteorite Pokémon", desc="Lunatone becomes active around the time of the full moon. Instead of walking, it moves by floating in midair. The Pokémon’s intimidating red eyes cause all those who see it to become transfixed with fear." },
  ["太阳岩"] = {   id=338, en="Solrock", zh="太阳岩", type="Rock, Psychic", species="Meteorite Pokémon", desc="Sunlight is the source of Solrock’s power. It is said to possess the ability to read the emotions of others. This Pokémon gives off intense heat while rotating its body." },
  ["solrock"] = {   id=338, en="Solrock", zh="太阳岩", type="Rock, Psychic", species="Meteorite Pokémon", desc="Sunlight is the source of Solrock’s power. It is said to possess the ability to read the emotions of others. This Pokémon gives off intense heat while rotating its body." },
  ["泥泥鳅"] = {   id=339, en="Barboach", zh="泥泥鳅", type="Water, Ground", species="Whiskers Pokémon", desc="Its whiskers are filled with nerves. They can sense smells and flavors just as a person’s nose or tongue would." },
  ["barboach"] = {   id=339, en="Barboach", zh="泥泥鳅", type="Water, Ground", species="Whiskers Pokémon", desc="Its whiskers are filled with nerves. They can sense smells and flavors just as a person’s nose or tongue would." },
  ["鲶鱼王"] = {   id=340, en="Whiscash", zh="鲶鱼王", type="Water, Ground", species="Whiskers Pokémon", desc="Its vision is not that good. It senses vibrations in the water with its whiskers to determine the location of its prey." },
  ["whiscash"] = {   id=340, en="Whiscash", zh="鲶鱼王", type="Water, Ground", species="Whiskers Pokémon", desc="Its vision is not that good. It senses vibrations in the water with its whiskers to determine the location of its prey." },
  ["龙虾小兵"] = {   id=341, en="Corphish", zh="龙虾小兵", type="Water", species="Ruffian Pokémon", desc="It can adapt very well to its environment. Feebas and Corphish are about the only Pokémon to live in stagnant ditches." },
  ["corphish"] = {   id=341, en="Corphish", zh="龙虾小兵", type="Water", species="Ruffian Pokémon", desc="It can adapt very well to its environment. Feebas and Corphish are about the only Pokémon to live in stagnant ditches." },
  ["铁螯龙虾"] = {   id=342, en="Crawdaunt", zh="铁螯龙虾", type="Water, Dark", species="Rogue Pokémon", desc="Its pincers often fall off. Unlike with Crabrawler or Clauncher, the meat in its claws is utterly nasty and stinking." },
  ["crawdaunt"] = {   id=342, en="Crawdaunt", zh="铁螯龙虾", type="Water, Dark", species="Rogue Pokémon", desc="Its pincers often fall off. Unlike with Crabrawler or Clauncher, the meat in its claws is utterly nasty and stinking." },
  ["天秤偶"] = {   id=343, en="Baltoy", zh="天秤偶", type="Ground, Psychic", species="Clay Doll Pokémon", desc="When they find others of their kind, they cry out loudly and gather together. Large numbers of them can be found in old graveyards." },
  ["baltoy"] = {   id=343, en="Baltoy", zh="天秤偶", type="Ground, Psychic", species="Clay Doll Pokémon", desc="When they find others of their kind, they cry out loudly and gather together. Large numbers of them can be found in old graveyards." },
  ["念力土偶"] = {   id=344, en="Claydol", zh="念力土偶", type="Ground, Psychic", species="Clay Doll Pokémon", desc="The ancient people who made it apparently modeled it after something that descended from the sky. It fires beams from both arms." },
  ["claydol"] = {   id=344, en="Claydol", zh="念力土偶", type="Ground, Psychic", species="Clay Doll Pokémon", desc="The ancient people who made it apparently modeled it after something that descended from the sky. It fires beams from both arms." },
  ["触手百合"] = {   id=345, en="Lileep", zh="触手百合", type="Rock, Grass", species="Sea Lily Pokémon", desc="It sticks to rocks with its powerful suckers and can’t be washed away no matter how rough the surf gets." },
  ["lileep"] = {   id=345, en="Lileep", zh="触手百合", type="Rock, Grass", species="Sea Lily Pokémon", desc="It sticks to rocks with its powerful suckers and can’t be washed away no matter how rough the surf gets." },
  ["摇篮百合"] = {   id=346, en="Cradily", zh="摇篮百合", type="Rock, Grass", species="Barnacle Pokémon", desc="This carnivorous Pokémon lived in primordial seas. It catches prey in its eight tentacles and dissolves them with digestive fluid as it eats." },
  ["cradily"] = {   id=346, en="Cradily", zh="摇篮百合", type="Rock, Grass", species="Barnacle Pokémon", desc="This carnivorous Pokémon lived in primordial seas. It catches prey in its eight tentacles and dissolves them with digestive fluid as it eats." },
  ["太古羽虫"] = {   id=347, en="Anorith", zh="太古羽虫", type="Rock, Bug", species="Old Shrimp Pokémon", desc="This is one kind of primeval bug Pokémon. With eight wings, it could apparently swim a lot faster than you’d expect." },
  ["anorith"] = {   id=347, en="Anorith", zh="太古羽虫", type="Rock, Bug", species="Old Shrimp Pokémon", desc="This is one kind of primeval bug Pokémon. With eight wings, it could apparently swim a lot faster than you’d expect." },
  ["太古盔甲"] = {   id=348, en="Armaldo", zh="太古盔甲", type="Rock, Bug", species="Plate Pokémon", desc="Armaldo adapted from living in water to living on land. It has been determined that it is the ancestor of some bug Pokémon." },
  ["armaldo"] = {   id=348, en="Armaldo", zh="太古盔甲", type="Rock, Bug", species="Plate Pokémon", desc="Armaldo adapted from living in water to living on land. It has been determined that it is the ancestor of some bug Pokémon." },
  ["丑丑鱼"] = {   id=349, en="Feebas", zh="丑丑鱼", type="Water", species="Fish Pokémon", desc="Because of its wretched appearance, most people pay it no attention, but there are some who collect Feebas—and Feebas alone!" },
  ["feebas"] = {   id=349, en="Feebas", zh="丑丑鱼", type="Water", species="Fish Pokémon", desc="Because of its wretched appearance, most people pay it no attention, but there are some who collect Feebas—and Feebas alone!" },
  ["美纳斯"] = {   id=350, en="Milotic", zh="美纳斯", type="Water", species="Tender Pokémon", desc="Its dwelling place is the bottom of big lakes. Those who behold its loveliness are said to have their hearts purified." },
  ["milotic"] = {   id=350, en="Milotic", zh="美纳斯", type="Water", species="Tender Pokémon", desc="Its dwelling place is the bottom of big lakes. Those who behold its loveliness are said to have their hearts purified." },
  ["飘浮泡泡"] = {   id=351, en="Castform", zh="飘浮泡泡", type="Normal", species="Weather Pokémon", desc="Its form changes depending on the weather. The rougher conditions get, the rougher Castform’s disposition!" },
  ["castform"] = {   id=351, en="Castform", zh="飘浮泡泡", type="Normal", species="Weather Pokémon", desc="Its form changes depending on the weather. The rougher conditions get, the rougher Castform’s disposition!" },
  ["变隐龙"] = {   id=352, en="Kecleon", zh="变隐龙", type="Normal", species="Color Swap Pokémon", desc="Its color changes for concealment and also when its mood or health changes. The darker the color, the healthier it is." },
  ["kecleon"] = {   id=352, en="Kecleon", zh="变隐龙", type="Normal", species="Color Swap Pokémon", desc="Its color changes for concealment and also when its mood or health changes. The darker the color, the healthier it is." },
  ["怨影娃娃"] = {   id=353, en="Shuppet", zh="怨影娃娃", type="Ghost", species="Puppet Pokémon", desc="There’s a proverb that says, “Shun the house where Shuppet gather in the growing dusk.”" },
  ["shuppet"] = {   id=353, en="Shuppet", zh="怨影娃娃", type="Ghost", species="Puppet Pokémon", desc="There’s a proverb that says, “Shun the house where Shuppet gather in the growing dusk.”" },
  ["诅咒娃娃"] = {   id=354, en="Banette", zh="诅咒娃娃", type="Ghost", species="Marionette Pokémon", desc="Resentment at being cast off made it spring into being. Some say that treating it well will satisfy it, and it will once more become a stuffed toy." },
  ["banette"] = {   id=354, en="Banette", zh="诅咒娃娃", type="Ghost", species="Marionette Pokémon", desc="Resentment at being cast off made it spring into being. Some say that treating it well will satisfy it, and it will once more become a stuffed toy." },
  ["夜巡灵"] = {   id=355, en="Duskull", zh="夜巡灵", type="Ghost", species="Requiem Pokémon", desc="Duskull wanders lost among the deep darkness of midnight. There is an oft-told admonishment given to misbehaving children that this Pokémon will spirit away bad children who earn scoldings from their mothers." },
  ["duskull"] = {   id=355, en="Duskull", zh="夜巡灵", type="Ghost", species="Requiem Pokémon", desc="Duskull wanders lost among the deep darkness of midnight. There is an oft-told admonishment given to misbehaving children that this Pokémon will spirit away bad children who earn scoldings from their mothers." },
  ["彷徨夜灵"] = {   id=356, en="Dusclops", zh="彷徨夜灵", type="Ghost", species="Beckon Pokémon", desc="Dusclops absorbs anything, however large the object may be. This Pokémon hypnotizes its foe by waving its hands in a macabre manner and by bringing its single eye to bear. The hypnotized foe is made to do Dusclops’s bidding." },
  ["dusclops"] = {   id=356, en="Dusclops", zh="彷徨夜灵", type="Ghost", species="Beckon Pokémon", desc="Dusclops absorbs anything, however large the object may be. This Pokémon hypnotizes its foe by waving its hands in a macabre manner and by bringing its single eye to bear. The hypnotized foe is made to do Dusclops’s bidding." },
  ["热带龙"] = {   id=357, en="Tropius", zh="热带龙", type="Grass, Flying", species="Fruit Pokémon", desc="Bunches of delicious fruit grow around its neck. In warm areas, many ranches raise Tropius." },
  ["tropius"] = {   id=357, en="Tropius", zh="热带龙", type="Grass, Flying", species="Fruit Pokémon", desc="Bunches of delicious fruit grow around its neck. In warm areas, many ranches raise Tropius." },
  ["风铃铃"] = {   id=358, en="Chimecho", zh="风铃铃", type="Psychic", species="Wind Chime Pokémon", desc="In high winds, Chimecho cries as it hangs from a tree branch or the eaves of a building using a suction cup on its head. This Pokémon plucks berries with its long tail and eats them." },
  ["chimecho"] = {   id=358, en="Chimecho", zh="风铃铃", type="Psychic", species="Wind Chime Pokémon", desc="In high winds, Chimecho cries as it hangs from a tree branch or the eaves of a building using a suction cup on its head. This Pokémon plucks berries with its long tail and eats them." },
  ["阿勃梭鲁"] = {   id=359, en="Absol", zh="阿勃梭鲁", type="Dark", species="Disaster Pokémon", desc="The elderly call it the disaster Pokémon and detest it, but interest in its power to predict disasters is on the rise." },
  ["absol"] = {   id=359, en="Absol", zh="阿勃梭鲁", type="Dark", species="Disaster Pokémon", desc="The elderly call it the disaster Pokémon and detest it, but interest in its power to predict disasters is on the rise." },
  ["小果然"] = {   id=360, en="Wynaut", zh="小果然", type="Psychic", species="Bright Pokémon", desc="Wynaut gather on moonlit nights to play by squeezing up against each other. By being squeezed, this Pokémon gains endurance and is trained to dole out powerful counterattacks." },
  ["wynaut"] = {   id=360, en="Wynaut", zh="小果然", type="Psychic", species="Bright Pokémon", desc="Wynaut gather on moonlit nights to play by squeezing up against each other. By being squeezed, this Pokémon gains endurance and is trained to dole out powerful counterattacks." },
  ["雪童子"] = {   id=361, en="Snorunt", zh="雪童子", type="Ice", species="Snow Hat Pokémon", desc="Rich people from cold areas all share childhood memories of playing with Snorunt." },
  ["snorunt"] = {   id=361, en="Snorunt", zh="雪童子", type="Ice", species="Snow Hat Pokémon", desc="Rich people from cold areas all share childhood memories of playing with Snorunt." },
  ["冰鬼护"] = {   id=362, en="Glalie", zh="冰鬼护", type="Ice", species="Face Pokémon", desc="Its actual body is a rock that isn’t particularly hard. Glalie absorbs moisture from the air and drapes itself in an armor of ice." },
  ["glalie"] = {   id=362, en="Glalie", zh="冰鬼护", type="Ice", species="Face Pokémon", desc="Its actual body is a rock that isn’t particularly hard. Glalie absorbs moisture from the air and drapes itself in an armor of ice." },
  ["海豹球"] = {   id=363, en="Spheal", zh="海豹球", type="Ice, Water", species="Clap Pokémon", desc="Spheal always travels by rolling around on its ball-like body. When the season for ice floes arrives, this Pokémon can be seen rolling about on ice and crossing the sea." },
  ["spheal"] = {   id=363, en="Spheal", zh="海豹球", type="Ice, Water", species="Clap Pokémon", desc="Spheal always travels by rolling around on its ball-like body. When the season for ice floes arrives, this Pokémon can be seen rolling about on ice and crossing the sea." },
  ["海魔狮"] = {   id=364, en="Sealeo", zh="海魔狮", type="Ice, Water", species="Ball Roll Pokémon", desc="Sealeo often balances and rolls things on the tip of its nose. While the Pokémon is rolling something, it checks the object’s aroma and texture to determine whether it likes the object or not." },
  ["sealeo"] = {   id=364, en="Sealeo", zh="海魔狮", type="Ice, Water", species="Ball Roll Pokémon", desc="Sealeo often balances and rolls things on the tip of its nose. While the Pokémon is rolling something, it checks the object’s aroma and texture to determine whether it likes the object or not." },
  ["帝牙海狮"] = {   id=365, en="Walrein", zh="帝牙海狮", type="Ice, Water", species="Ice Break Pokémon", desc="Walrein swims all over in frigid seawater while crushing icebergs with its grand, imposing tusks. Its thick layer of blubber makes enemy attacks bounce off harmlessly." },
  ["walrein"] = {   id=365, en="Walrein", zh="帝牙海狮", type="Ice, Water", species="Ice Break Pokémon", desc="Walrein swims all over in frigid seawater while crushing icebergs with its grand, imposing tusks. Its thick layer of blubber makes enemy attacks bounce off harmlessly." },
  ["珍珠贝"] = {   id=366, en="Clamperl", zh="珍珠贝", type="Water", species="Bivalve Pokémon", desc="Clamperl’s pearls are exceedingly precious. They can be more than 10 times as costly as Shellder’s pearls." },
  ["clamperl"] = {   id=366, en="Clamperl", zh="珍珠贝", type="Water", species="Bivalve Pokémon", desc="Clamperl’s pearls are exceedingly precious. They can be more than 10 times as costly as Shellder’s pearls." },
  ["猎斑鱼"] = {   id=367, en="Huntail", zh="猎斑鱼", type="Water", species="Deep Sea Pokémon", desc="Deep seas are their habitat. According to tradition, when Huntail wash up onshore, something unfortunate will happen." },
  ["huntail"] = {   id=367, en="Huntail", zh="猎斑鱼", type="Water", species="Deep Sea Pokémon", desc="Deep seas are their habitat. According to tradition, when Huntail wash up onshore, something unfortunate will happen." },
  ["樱花鱼"] = {   id=368, en="Gorebyss", zh="樱花鱼", type="Water", species="South Sea Pokémon", desc="It sucks bodily fluids out of its prey. The leftover meat sinks to the seafloor, where it becomes food for other Pokémon." },
  ["gorebyss"] = {   id=368, en="Gorebyss", zh="樱花鱼", type="Water", species="South Sea Pokémon", desc="It sucks bodily fluids out of its prey. The leftover meat sinks to the seafloor, where it becomes food for other Pokémon." },
  ["古空棘鱼"] = {   id=369, en="Relicanth", zh="古空棘鱼", type="Water, Rock", species="Longevity Pokémon", desc="The reason it hasn’t changed at all in a hundred million years is that it’s apparently already a perfect life-form." },
  ["relicanth"] = {   id=369, en="Relicanth", zh="古空棘鱼", type="Water, Rock", species="Longevity Pokémon", desc="The reason it hasn’t changed at all in a hundred million years is that it’s apparently already a perfect life-form." },
  ["爱心鱼"] = {   id=370, en="Luvdisc", zh="爱心鱼", type="Water", species="Rendezvous Pokémon", desc="Luvdisc makes its home in coral reefs in warm seas. It especially likes sleeping in the space between Corsola’s branches." },
  ["luvdisc"] = {   id=370, en="Luvdisc", zh="爱心鱼", type="Water", species="Rendezvous Pokémon", desc="Luvdisc makes its home in coral reefs in warm seas. It especially likes sleeping in the space between Corsola’s branches." },
  ["宝贝龙"] = {   id=371, en="Bagon", zh="宝贝龙", type="Dragon", species="Rock Head Pokémon", desc="Some theories suggest that its behavior of forcefully bashing its head into things stimulates cells that affect its evolution." },
  ["bagon"] = {   id=371, en="Bagon", zh="宝贝龙", type="Dragon", species="Rock Head Pokémon", desc="Some theories suggest that its behavior of forcefully bashing its head into things stimulates cells that affect its evolution." },
  ["甲壳龙"] = {   id=372, en="Shelgon", zh="甲壳龙", type="Dragon", species="Endurance Pokémon", desc="Shelgon lives deep within caves. It stays shut up in its hard shell, dreaming of the day it will be able to fly." },
  ["shelgon"] = {   id=372, en="Shelgon", zh="甲壳龙", type="Dragon", species="Endurance Pokémon", desc="Shelgon lives deep within caves. It stays shut up in its hard shell, dreaming of the day it will be able to fly." },
  ["暴飞龙"] = {   id=373, en="Salamence", zh="暴飞龙", type="Dragon, Flying", species="Dragon Pokémon", desc="Thanks to its fervent wishes, the cells in its body finally mutated, and at last it has its heart’s desire—wings." },
  ["salamence"] = {   id=373, en="Salamence", zh="暴飞龙", type="Dragon, Flying", species="Dragon Pokémon", desc="Thanks to its fervent wishes, the cells in its body finally mutated, and at last it has its heart’s desire—wings." },
  ["铁哑铃"] = {   id=374, en="Beldum", zh="铁哑铃", type="Steel, Psychic", species="Iron Ball Pokémon", desc="If you anger it, it will do more than rampage. It will also burst out strong magnetism, causing nearby machines to break." },
  ["beldum"] = {   id=374, en="Beldum", zh="铁哑铃", type="Steel, Psychic", species="Iron Ball Pokémon", desc="If you anger it, it will do more than rampage. It will also burst out strong magnetism, causing nearby machines to break." },
  ["金属怪"] = {   id=375, en="Metang", zh="金属怪", type="Steel, Psychic", species="Iron Claw Pokémon", desc="It flies at high speeds around the skies. When it finds its prey, Metang takes a firm grip with its sharp claws and never lets go." },
  ["metang"] = {   id=375, en="Metang", zh="金属怪", type="Steel, Psychic", species="Iron Claw Pokémon", desc="It flies at high speeds around the skies. When it finds its prey, Metang takes a firm grip with its sharp claws and never lets go." },
  ["巨金怪"] = {   id=376, en="Metagross", zh="巨金怪", type="Steel, Psychic", species="Iron Leg Pokémon", desc="It analyzes its opponents with more accuracy than a supercomputer, which enables it to calmly back them into a corner." },
  ["metagross"] = {   id=376, en="Metagross", zh="巨金怪", type="Steel, Psychic", species="Iron Leg Pokémon", desc="It analyzes its opponents with more accuracy than a supercomputer, which enables it to calmly back them into a corner." },
  ["雷吉洛克"] = {   id=377, en="Regirock", zh="雷吉洛克", type="Rock", species="Rock Peak Pokémon", desc="Regirock’s body is composed entirely of rocks. Recently, a study made the startling discovery that the rocks were all unearthed from different locations." },
  ["regirock"] = {   id=377, en="Regirock", zh="雷吉洛克", type="Rock", species="Rock Peak Pokémon", desc="Regirock’s body is composed entirely of rocks. Recently, a study made the startling discovery that the rocks were all unearthed from different locations." },
  ["雷吉艾斯"] = {   id=378, en="Regice", zh="雷吉艾斯", type="Ice", species="Iceberg Pokémon", desc="Regice cloaks itself with frigid air of -328 degrees Fahrenheit. Things will freeze solid just by going near this Pokémon. Its icy body is so cold, it will not melt even if it is immersed in magma." },
  ["regice"] = {   id=378, en="Regice", zh="雷吉艾斯", type="Ice", species="Iceberg Pokémon", desc="Regice cloaks itself with frigid air of -328 degrees Fahrenheit. Things will freeze solid just by going near this Pokémon. Its icy body is so cold, it will not melt even if it is immersed in magma." },
  ["雷吉斯奇鲁"] = {   id=379, en="Registeel", zh="雷吉斯奇鲁", type="Steel", species="Iron Pokémon", desc="Registeel was imprisoned by people in ancient times. The metal composing its body is thought to be a curious substance that is not of this earth." },
  ["registeel"] = {   id=379, en="Registeel", zh="雷吉斯奇鲁", type="Steel", species="Iron Pokémon", desc="Registeel was imprisoned by people in ancient times. The metal composing its body is thought to be a curious substance that is not of this earth." },
  ["拉帝亚斯"] = {   id=380, en="Latias", zh="拉帝亚斯", type="Dragon, Psychic", species="Eon Pokémon", desc="Latias is highly intelligent and capable of understanding human speech. It is covered with a glass-like down. The Pokémon enfolds its body with its down and refracts light to alter its appearance." },
  ["latias"] = {   id=380, en="Latias", zh="拉帝亚斯", type="Dragon, Psychic", species="Eon Pokémon", desc="Latias is highly intelligent and capable of understanding human speech. It is covered with a glass-like down. The Pokémon enfolds its body with its down and refracts light to alter its appearance." },
  ["拉帝欧斯"] = {   id=381, en="Latios", zh="拉帝欧斯", type="Dragon, Psychic", species="Eon Pokémon", desc="Latios will only open its heart to a Trainer with a compassionate spirit. This Pokémon can fly faster than a jet plane by folding its forelegs to minimize air resistance." },
  ["latios"] = {   id=381, en="Latios", zh="拉帝欧斯", type="Dragon, Psychic", species="Eon Pokémon", desc="Latios will only open its heart to a Trainer with a compassionate spirit. This Pokémon can fly faster than a jet plane by folding its forelegs to minimize air resistance." },
  ["盖欧卡"] = {   id=382, en="Kyogre", zh="盖欧卡", type="Water", species="Sea Basin Pokémon", desc="Kyogre is said to be the personification of the sea itself. Legends tell of its many clashes against Groudon, as each sought to gain the power of nature." },
  ["kyogre"] = {   id=382, en="Kyogre", zh="盖欧卡", type="Water", species="Sea Basin Pokémon", desc="Kyogre is said to be the personification of the sea itself. Legends tell of its many clashes against Groudon, as each sought to gain the power of nature." },
  ["固拉多"] = {   id=383, en="Groudon", zh="固拉多", type="Ground", species="Continent Pokémon", desc="Through Primal Reversion and with nature’s full power, it will take back its true form. It can cause magma to erupt and expand the landmass of the world." },
  ["groudon"] = {   id=383, en="Groudon", zh="固拉多", type="Ground", species="Continent Pokémon", desc="Through Primal Reversion and with nature’s full power, it will take back its true form. It can cause magma to erupt and expand the landmass of the world." },
  ["烈空坐"] = {   id=384, en="Rayquaza", zh="烈空坐", type="Dragon, Flying", species="Sky High Pokémon", desc="It flies forever through the ozone layer, consuming meteoroids for sustenance. The many meteoroids in its body provide the energy it needs to Mega Evolve." },
  ["rayquaza"] = {   id=384, en="Rayquaza", zh="烈空坐", type="Dragon, Flying", species="Sky High Pokémon", desc="It flies forever through the ozone layer, consuming meteoroids for sustenance. The many meteoroids in its body provide the energy it needs to Mega Evolve." },
  ["基拉祈"] = {   id=385, en="Jirachi", zh="基拉祈", type="Steel, Psychic", species="Wish Pokémon", desc="Jirachi will awaken from its sleep of a thousand years if you sing to it in a voice of purity. It is said to make true any wish that people desire." },
  ["jirachi"] = {   id=385, en="Jirachi", zh="基拉祈", type="Steel, Psychic", species="Wish Pokémon", desc="Jirachi will awaken from its sleep of a thousand years if you sing to it in a voice of purity. It is said to make true any wish that people desire." },
  ["代欧奇希斯"] = {   id=386, en="Deoxys", zh="代欧奇希斯", type="Psychic", species="DNA Pokémon", desc="Deoxys emerged from a virus that came from space. It is highly intelligent and wields psychokinetic powers. This Pokémon shoots lasers from the crystalline organ on its chest." },
  ["deoxys"] = {   id=386, en="Deoxys", zh="代欧奇希斯", type="Psychic", species="DNA Pokémon", desc="Deoxys emerged from a virus that came from space. It is highly intelligent and wields psychokinetic powers. This Pokémon shoots lasers from the crystalline organ on its chest." },
  ["草苗龟"] = {   id=387, en="Turtwig", zh="草苗龟", type="Grass", species="Tiny Leaf Pokémon", desc="It undertakes photosynthesis with its body, making oxygen. The leaf on its head wilts if it is thirsty." },
  ["turtwig"] = {   id=387, en="Turtwig", zh="草苗龟", type="Grass", species="Tiny Leaf Pokémon", desc="It undertakes photosynthesis with its body, making oxygen. The leaf on its head wilts if it is thirsty." },
  ["树林龟"] = {   id=388, en="Grotle", zh="树林龟", type="Grass", species="Grove Pokémon", desc="It knows where pure water wells up. It carries fellow Pokémon there on its back." },
  ["grotle"] = {   id=388, en="Grotle", zh="树林龟", type="Grass", species="Grove Pokémon", desc="It knows where pure water wells up. It carries fellow Pokémon there on its back." },
  ["土台龟"] = {   id=389, en="Torterra", zh="土台龟", type="Grass, Ground", species="Continent Pokémon", desc="Small Pokémon occasionally gather on its unmoving back to begin building their nests." },
  ["torterra"] = {   id=389, en="Torterra", zh="土台龟", type="Grass, Ground", species="Continent Pokémon", desc="Small Pokémon occasionally gather on its unmoving back to begin building their nests." },
  ["小火焰猴"] = {   id=390, en="Chimchar", zh="小火焰猴", type="Fire", species="Chimp Pokémon", desc="The gas made in its belly burns from its rear end. The fire burns weakly when it feels sick." },
  ["chimchar"] = {   id=390, en="Chimchar", zh="小火焰猴", type="Fire", species="Chimp Pokémon", desc="The gas made in its belly burns from its rear end. The fire burns weakly when it feels sick." },
  ["猛火猴"] = {   id=391, en="Monferno", zh="猛火猴", type="Fire, Fighting", species="Playful Pokémon", desc="It uses ceilings and walls to launch aerial attacks. Its fiery tail is but one weapon." },
  ["monferno"] = {   id=391, en="Monferno", zh="猛火猴", type="Fire, Fighting", species="Playful Pokémon", desc="It uses ceilings and walls to launch aerial attacks. Its fiery tail is but one weapon." },
