  ["斧牙龙"] = {   id=611, en="Fraxure", zh="斧牙龙", type="Dragon", species="Axe Jaw Pokémon", desc="A broken tusk will not grow back, so it diligently sharpens its tusks on river rocks after the end of a battle." },
