  ["双斧战龙"] = {   id=612, en="Haxorus", zh="双斧战龙", type="Dragon", species="Axe Jaw Pokémon", desc="Their sturdy tusks will stay sharp even if used to cut steel beams. These Pokémon are covered in hard armor." },
