  ["几何雪花"] = {   id=615, en="Cryogonal", zh="几何雪花", type="Ice", species="Crystallizing Pokémon", desc="They are composed of ice crystals. They capture prey with chains of ice, freezing the prey at -148 degrees Fahrenheit." },
