  ["敏捷虫"] = {   id=617, en="Accelgor", zh="敏捷虫", type="Bug", species="Shell Out Pokémon", desc="When its body dries out, it weakens. So, to prevent dehydration, it wraps itself in many layers of thin membrane." },
