  ["泥巴鱼"] = {   id=618, en="Stunfisk", zh="泥巴鱼", type="Ground, Electric", species="Trap Pokémon", desc="It conceals itself in the mud of the seashore. Then it waits. When prey touch it, it delivers a jolt of electricity." },
