  ["功夫鼬"] = {   id=619, en="Mienfoo", zh="功夫鼬", type="Fighting", species="Martial Arts Pokémon", desc="They seclude themselves in the mountains and devote themselves to training. The form of their kicks and chops differs from pack to pack." },
