  ["师父鼬"] = {   id=620, en="Mienshao", zh="师父鼬", type="Fighting", species="Martial Arts Pokémon", desc="When Mienshao lets out a bizarre wail, you’re in danger. A flurry of kicks and chops too fast to see is about to be unleashed!" },
