  ["赤面龙"] = {   id=621, en="Druddigon", zh="赤面龙", type="Dragon", species="Cave Pokémon", desc="It infiltrates tunnels that Pokémon like Diglett and Dugtrio have dug and quietly waits for prey to pass through." },
