  ["泥偶巨人"] = {   id=623, en="Golurk", zh="泥偶巨人", type="Ground, Ghost", species="Automaton Pokémon", desc="When the seal on its chest is removed, it rages indiscriminately, turning the whole town around it into a mountain of rubble." },
