  ["驹刀小兵"] = {   id=624, en="Pawniard", zh="驹刀小兵", type="Dark, Steel", species="Sharp Blade Pokémon", desc="It follows Bisharp’s orders to a tee when it attacks enemies. After slashing an opponent, Pawniard clangs both of its blades together." },
