  ["劈斩司令"] = {   id=625, en="Bisharp", zh="劈斩司令", type="Dark, Steel", species="Sword Blade Pokémon", desc="It leads a group of Pawniard. Bisharp doesn’t even change its expression when it deals the finishing blow to an opponent." },
