  ["爆炸头水牛"] = {   id=626, en="Bouffalant", zh="爆炸头水牛", type="Normal", species="Bash Buffalo Pokémon", desc="Their fluffy fur absorbs damage, even if they strike foes with a fierce headbutt." },
