  ["毛头小鹰"] = {   id=627, en="Rufflet", zh="毛头小鹰", type="Normal, Flying", species="Eaglet Pokémon", desc="Known as a natural-born warrior, soon after its hatching, it will challenge its parent to a fight in order to gain their acceptance." },
