  ["勇士雄鹰"] = {   id=628, en="Braviary", zh="勇士雄鹰", type="Normal, Flying", species="Valiant Pokémon", desc="Known as “the hero of the skies,” this Pokémon is so proud and so brave that it will never retreat, even when it’s injured." },
