  ["秃鹰丫头"] = {   id=629, en="Vullaby", zh="秃鹰丫头", type="Dark, Flying", species="Diapered Pokémon", desc="Its healthy appetite leads to visible growth spurts. It often has to replace the bones it wears as its size increases." },
