  ["秃鹰娜"] = {   id=630, en="Mandibuzz", zh="秃鹰娜", type="Dark, Flying", species="Bone Vulture Pokémon", desc="It’s always searching for food for Vullaby. When it finds a weak Pokémon, Mandibuzz swoops it right off to its nest." },
