  ["熔蚁兽"] = {   id=631, en="Heatmor", zh="熔蚁兽", type="Fire", species="Anteater Pokémon", desc="It draws in air through its tail, transforms it into fire, and uses it like a tongue. It melts Durant and eats them." },
