  ["呱呱泡蛙"] = {   id=656, en="Froakie", zh="呱呱泡蛙", type="Water", species="Bubble Frog Pokémon", desc="It protects its skin by covering its body in delicate bubbles. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings." },
