  ["火炎狮"] = {   id=668, en="Pyroar", zh="火炎狮", type="Fire, Normal", species="Royal Pokémon", desc="The temperature of its breath is over 10,000 degrees Fahrenheit, but Pyroar doesn’t use it on its prey. This Pokémon prefers to eat raw meat." },
