  ["花蓓蓓"] = {   id=669, en="Flabébé", zh="花蓓蓓", type="Fairy", species="Single Bloom Pokémon", desc="Flabébé wears a crown made from pollen it’s collected from its flower. The crown has hidden healing properties." },
