  ["花叶蒂"] = {   id=670, en="Floette", zh="花叶蒂", type="Fairy", species="Single Bloom Pokémon", desc="It gives its own power to flowers, pouring its heart into caring for them. Floette never forgives anyone who messes up a flower bed." },
