  ["顽皮熊猫"] = {   id=674, en="Pancham", zh="顽皮熊猫", type="Fighting", species="Playful Pokémon", desc="It’s desperate to intimidate its opponents. Be nice and pretend to be scared if you catch it glaring at you intensely." },
  ["pancham"] = {   id=674, en="Pancham", zh="顽皮熊猫", type="Fighting", species="Playful Pokémon", desc="It’s desperate to intimidate its opponents. Be nice and pretend to be scared if you catch it glaring at you intensely." },
  ["流氓熊猫"] = {   id=675, en="Pangoro", zh="流氓熊猫", type="Fighting, Dark", species="Daunting Pokémon", desc="Pangoro is the type to talk with its fists. It doesn’t say much as it pummels opponents with enough force to send a dump truck flying." },
  ["pangoro"] = {   id=675, en="Pangoro", zh="流氓熊猫", type="Fighting, Dark", species="Daunting Pokémon", desc="Pangoro is the type to talk with its fists. It doesn’t say much as it pummels opponents with enough force to send a dump truck flying." },
  ["多丽米亚"] = {   id=676, en="Furfrou", zh="多丽米亚", type="Normal", species="Poodle Pokémon", desc="Left alone, its fur will grow longer and longer, but it will only allow someone it trusts to cut it." },
  ["furfrou"] = {   id=676, en="Furfrou", zh="多丽米亚", type="Normal", species="Poodle Pokémon", desc="Left alone, its fur will grow longer and longer, but it will only allow someone it trusts to cut it." },
  ["妙喵"] = {   id=677, en="Espurr", zh="妙喵", type="Psychic", species="Restraint Pokémon", desc="It has enough psychic energy to blast everything within 300 feet of itself, but it has no control over its power." },
  ["espurr"] = {   id=677, en="Espurr", zh="妙喵", type="Psychic", species="Restraint Pokémon", desc="It has enough psychic energy to blast everything within 300 feet of itself, but it has no control over its power." },
  ["超能妙喵"] = {   id=678, en="Meowstic", zh="超能妙喵", type="Psychic", species="Constraint Pokémon", desc="The eyeball patterns on the interior of its ears emit psychic energy. It keeps the patterns tightly covered because that power is too immense." },
  ["meowstic"] = {   id=678, en="Meowstic", zh="超能妙喵", type="Psychic", species="Constraint Pokémon", desc="The eyeball patterns on the interior of its ears emit psychic energy. It keeps the patterns tightly covered because that power is too immense." },
  ["独剑鞘"] = {   id=679, en="Honedge", zh="独剑鞘", type="Steel, Ghost", species="Sword Pokémon", desc="If anyone dares to grab its hilt, it wraps a blue cloth around that person’s arm and drains that person’s life energy completely." },
  ["honedge"] = {   id=679, en="Honedge", zh="独剑鞘", type="Steel, Ghost", species="Sword Pokémon", desc="If anyone dares to grab its hilt, it wraps a blue cloth around that person’s arm and drains that person’s life energy completely." },
  ["双剑鞘"] = {   id=680, en="Doublade", zh="双剑鞘", type="Steel, Ghost", species="Sword Pokémon", desc="The complex attack patterns of its two swords are unstoppable, even for an opponent greatly accomplished at swordplay." },
  ["doublade"] = {   id=680, en="Doublade", zh="双剑鞘", type="Steel, Ghost", species="Sword Pokémon", desc="The complex attack patterns of its two swords are unstoppable, even for an opponent greatly accomplished at swordplay." },
  ["坚盾剑怪"] = {   id=681, en="Aegislash", zh="坚盾剑怪", type="Steel, Ghost", species="Royal Sword Pokémon", desc="Apparently, it can detect the innate qualities of leadership. According to legend, whoever it recognizes is destined to become king." },
  ["aegislash"] = {   id=681, en="Aegislash", zh="坚盾剑怪", type="Steel, Ghost", species="Royal Sword Pokémon", desc="Apparently, it can detect the innate qualities of leadership. According to legend, whoever it recognizes is destined to become king." },
  ["粉香香"] = {   id=682, en="Spritzee", zh="粉香香", type="Fairy", species="Perfume Pokémon", desc="In the past, rather than using perfume, royal ladies carried a Spritzee that would waft a fragrance they liked." },
