  ["芳香精"] = {   id=683, en="Aromatisse", zh="芳香精", type="Fairy", species="Fragrance Pokémon", desc="Its scent is so overpowering that, unless a Trainer happens to really enjoy the smell, he or she will have a hard time walking alongside it." },
