  ["胖甜妮"] = {   id=685, en="Slurpuff", zh="胖甜妮", type="Fairy", species="Meringue Pokémon", desc="Its sense of smell is 100 million times better than a human’s, so even the faintest scent tells it about everything in the area. It’s like it can see with its nose!" },
