  ["龟脚脚"] = {   id=688, en="Binacle", zh="龟脚脚", type="Rock, Water", species="Two-Handed Pokémon", desc="They stretch and then contract, yanking their rocks along with them in bold hops. They eat seaweed that washes up on the shoreline." },
