  ["垃垃藻"] = {   id=690, en="Skrelp", zh="垃垃藻", type="Poison, Water", species="Mock Kelp Pokémon", desc="It’s not good at swimming, so it clings to the seaweed. In the Alola region, it’s often found near Dhelmise." },
