  ["铁臂枪虾"] = {   id=692, en="Clauncher", zh="铁臂枪虾", type="Water", species="Water Gun Pokémon", desc="It moves around by jetting water from its right pincer. It has a poor sense of balance, so it’s terrible at swimming straight." },
