  ["小碎钻"] = {   id=703, en="Carbink", zh="小碎钻", type="Rock, Fairy", species="Jewel Pokémon", desc="To keep the jewels on their bodies free of tarnish, packs of Carbink use their soft manes to polish one another’s jewels." },
