  ["黏黏宝"] = {   id=704, en="Goomy", zh="黏黏宝", type="Dragon", species="Soft Tissue Pokémon", desc="Its body is mostly water. If it dries out, it will die, so it’s always sitting with perfect stillness in the shade." },
