  ["黏美儿"] = {   id=705, en="Sliggoo", zh="黏美儿", type="Dragon", species="Soft Tissue Pokémon", desc="Its entire body is covered with gooey mucus that can dissolve anything. Be sure to put gloves on if you’re going to touch it." },
