  ["胆小虫"] = {   id=767, en="Wimpod", zh="胆小虫", type="Bug, Water", species="Turn Tail Pokémon", desc="An astonishingly cowardly Pokémon, Wimpod will whir its legs at high speeds to run away if anything comes near it." },
  ["wimpod"] = {   id=767, en="Wimpod", zh="胆小虫", type="Bug, Water", species="Turn Tail Pokémon", desc="An astonishingly cowardly Pokémon, Wimpod will whir its legs at high speeds to run away if anything comes near it." },
  ["具甲武者"] = {   id=768, en="Golisopod", zh="具甲武者", type="Bug, Water", species="Hard Scale Pokémon", desc="Its claws, which it can extend and retract at will, are its greatest weapons. Golisopod is sometimes accompanied by Wimpod." },
  ["golisopod"] = {   id=768, en="Golisopod", zh="具甲武者", type="Bug, Water", species="Hard Scale Pokémon", desc="Its claws, which it can extend and retract at will, are its greatest weapons. Golisopod is sometimes accompanied by Wimpod." },
  ["沙丘娃"] = {   id=769, en="Sandygast", zh="沙丘娃", type="Ghost, Ground", species="Sand Heap Pokémon", desc="If you build sand mounds when you’re playing, destroy them before you go home, or they may get possessed and become Sandygast." },
  ["sandygast"] = {   id=769, en="Sandygast", zh="沙丘娃", type="Ghost, Ground", species="Sand Heap Pokémon", desc="If you build sand mounds when you’re playing, destroy them before you go home, or they may get possessed and become Sandygast." },
  ["噬沙堡爷"] = {   id=770, en="Palossand", zh="噬沙堡爷", type="Ghost, Ground", species="Sand Castle Pokémon", desc="Once it has whipped up a sandstorm to halt its opponents in their tracks, this terrifying Pokémon snatches away their vitality." },
  ["palossand"] = {   id=770, en="Palossand", zh="噬沙堡爷", type="Ghost, Ground", species="Sand Castle Pokémon", desc="Once it has whipped up a sandstorm to halt its opponents in their tracks, this terrifying Pokémon snatches away their vitality." },
  ["拳海参"] = {   id=771, en="Pyukumuku", zh="拳海参", type="Water", species="Sea Cucumber Pokémon", desc="Its entire body is covered in its own slime. If you accidentally step on one, you’ll slip, and it will get mad and smack you!" },
  ["pyukumuku"] = {   id=771, en="Pyukumuku", zh="拳海参", type="Water", species="Sea Cucumber Pokémon", desc="Its entire body is covered in its own slime. If you accidentally step on one, you’ll slip, and it will get mad and smack you!" },
  ["属性：空"] = {   id=772, en="Type: Null", zh="属性：空", type="Normal", species="Synthetic Pokémon", desc="There’s danger of its going on a rampage, so its true power is sealed away beneath its control mask." },
  ["type: null"] = {   id=772, en="Type: Null", zh="属性：空", type="Normal", species="Synthetic Pokémon", desc="There’s danger of its going on a rampage, so its true power is sealed away beneath its control mask." },
  ["银伴战兽"] = {   id=773, en="Silvally", zh="银伴战兽", type="Normal", species="Synthetic Pokémon", desc="Through the bond it formed with its Trainer, its will was strengthened, and it was able to destroy its control mask." },
  ["silvally"] = {   id=773, en="Silvally", zh="银伴战兽", type="Normal", species="Synthetic Pokémon", desc="Through the bond it formed with its Trainer, its will was strengthened, and it was able to destroy its control mask." },
  ["小陨星"] = {   id=774, en="Minior", zh="小陨星", type="Rock, Flying", species="Meteor Pokémon", desc="Although its outer shell is uncommonly durable, the shock of falling to the ground smashes the shell to smithereens." },
  ["minior"] = {   id=774, en="Minior", zh="小陨星", type="Rock, Flying", species="Meteor Pokémon", desc="Although its outer shell is uncommonly durable, the shock of falling to the ground smashes the shell to smithereens." },
  ["树枕尾熊"] = {   id=775, en="Komala", zh="树枕尾熊", type="Normal", species="Drowsing Pokémon", desc="It remains asleep from birth to death as a result of the sedative properties of the leaves that form its diet." },
  ["komala"] = {   id=775, en="Komala", zh="树枕尾熊", type="Normal", species="Drowsing Pokémon", desc="It remains asleep from birth to death as a result of the sedative properties of the leaves that form its diet." },
  ["爆焰龟兽"] = {   id=776, en="Turtonator", zh="爆焰龟兽", type="Fire, Dragon", species="Blast Turtle Pokémon", desc="Its exploding shell poses a real danger but is sensitive to moisture. On rainy days, Turtonator takes silent refuge in caves." },
  ["turtonator"] = {   id=776, en="Turtonator", zh="爆焰龟兽", type="Fire, Dragon", species="Blast Turtle Pokémon", desc="Its exploding shell poses a real danger but is sensitive to moisture. On rainy days, Turtonator takes silent refuge in caves." },
  ["托戈德玛尔"] = {   id=777, en="Togedemaru", zh="托戈德玛尔", type="Electric, Steel", species="Roly-Poly Pokémon", desc="Its capacity to produce electricity is somewhat limited, so it gets charged up by letting lightning strike it!" },
  ["togedemaru"] = {   id=777, en="Togedemaru", zh="托戈德玛尔", type="Electric, Steel", species="Roly-Poly Pokémon", desc="Its capacity to produce electricity is somewhat limited, so it gets charged up by letting lightning strike it!" },
  ["谜拟ｑ"] = {   id=778, en="Mimikyu", zh="谜拟Ｑ", type="Ghost, Fairy", species="Disguise Pokémon", desc="A gust of wind revealed what hides under this Pokémon’s rag to a passing Trainer, who went home and died painfully that very night." },
  ["mimikyu"] = {   id=778, en="Mimikyu", zh="谜拟Ｑ", type="Ghost, Fairy", species="Disguise Pokémon", desc="A gust of wind revealed what hides under this Pokémon’s rag to a passing Trainer, who went home and died painfully that very night." },
  ["磨牙彩皮鱼"] = {   id=779, en="Bruxish", zh="磨牙彩皮鱼", type="Water, Psychic", species="Gnash Teeth Pokémon", desc="Its skin is thick enough to fend off Mareanie’s spikes. With its robust teeth, Bruxish crunches up the spikes and eats them." },
  ["bruxish"] = {   id=779, en="Bruxish", zh="磨牙彩皮鱼", type="Water, Psychic", species="Gnash Teeth Pokémon", desc="Its skin is thick enough to fend off Mareanie’s spikes. With its robust teeth, Bruxish crunches up the spikes and eats them." },
  ["老翁龙"] = {   id=780, en="Drampa", zh="老翁龙", type="Normal, Dragon", species="Placid Pokémon", desc="It appears in towns and plays with the children. Drampa will protect kids when they’re in danger, so their moms don’t have to worry." },
  ["drampa"] = {   id=780, en="Drampa", zh="老翁龙", type="Normal, Dragon", species="Placid Pokémon", desc="It appears in towns and plays with the children. Drampa will protect kids when they’re in danger, so their moms don’t have to worry." },
  ["破破舵轮"] = {   id=781, en="Dhelmise", zh="破破舵轮", type="Ghost, Grass", species="Sea Creeper Pokémon", desc="Its chain-like green seaweed can stretch outward for hundreds of yards. For some reason, it gets along well with Skrelp." },
  ["dhelmise"] = {   id=781, en="Dhelmise", zh="破破舵轮", type="Ghost, Grass", species="Sea Creeper Pokémon", desc="Its chain-like green seaweed can stretch outward for hundreds of yards. For some reason, it gets along well with Skrelp." },
  ["心鳞宝"] = {   id=782, en="Jangmo-o", zh="心鳞宝", type="Dragon", species="Scaly Pokémon", desc="It will never show an enemy its back in battle. Ancient warriors liked Jangmo-o for its valiant disposition and made it one of their own." },
  ["jangmo-o"] = {   id=782, en="Jangmo-o", zh="心鳞宝", type="Dragon", species="Scaly Pokémon", desc="It will never show an enemy its back in battle. Ancient warriors liked Jangmo-o for its valiant disposition and made it one of their own." },
  ["鳞甲龙"] = {   id=783, en="Hakamo-o", zh="鳞甲龙", type="Dragon, Fighting", species="Scaly Pokémon", desc="The scales it sheds can be molded and processed to make pots and pans. They conduct heat well, so they’re a popular item." },
  ["hakamo-o"] = {   id=783, en="Hakamo-o", zh="鳞甲龙", type="Dragon, Fighting", species="Scaly Pokémon", desc="The scales it sheds can be molded and processed to make pots and pans. They conduct heat well, so they’re a popular item." },
  ["杖尾鳞甲龙"] = {   id=784, en="Kommo-o", zh="杖尾鳞甲龙", type="Dragon, Fighting", species="Scaly Pokémon", desc="It battles valiantly with its fists, which are armored in steel scales. Kommo-o specializes in uppercuts." },
  ["kommo-o"] = {   id=784, en="Kommo-o", zh="杖尾鳞甲龙", type="Dragon, Fighting", species="Scaly Pokémon", desc="It battles valiantly with its fists, which are armored in steel scales. Kommo-o specializes in uppercuts." },
  ["卡璞・鸣鸣"] = {   id=785, en="Tapu Koko", zh="卡璞・鸣鸣", type="Electric, Fairy", species="Land Spirit Pokémon", desc="The lightning-wielding guardian deity of Melemele, Tapu Koko is brimming with curiosity and appears before people from time to time." },
  ["tapu koko"] = {   id=785, en="Tapu Koko", zh="卡璞・鸣鸣", type="Electric, Fairy", species="Land Spirit Pokémon", desc="The lightning-wielding guardian deity of Melemele, Tapu Koko is brimming with curiosity and appears before people from time to time." },
  ["卡璞・蝶蝶"] = {   id=786, en="Tapu Lele", zh="卡璞・蝶蝶", type="Psychic, Fairy", species="Land Spirit Pokémon", desc="Although called a guardian deity, Tapu Lele is devoid of guilt about its cruel disposition and can be described as nature incarnate." },
  ["tapu lele"] = {   id=786, en="Tapu Lele", zh="卡璞・蝶蝶", type="Psychic, Fairy", species="Land Spirit Pokémon", desc="Although called a guardian deity, Tapu Lele is devoid of guilt about its cruel disposition and can be described as nature incarnate." },
  ["卡璞・哞哞"] = {   id=787, en="Tapu Bulu", zh="卡璞・哞哞", type="Grass, Fairy", species="Land Spirit Pokémon", desc="It makes ringing sounds with its tail to let others know where it is, avoiding unneeded conflicts. This guardian deity of Ula’ula controls plants." },
  ["tapu bulu"] = {   id=787, en="Tapu Bulu", zh="卡璞・哞哞", type="Grass, Fairy", species="Land Spirit Pokémon", desc="It makes ringing sounds with its tail to let others know where it is, avoiding unneeded conflicts. This guardian deity of Ula’ula controls plants." },
  ["卡璞・鳍鳍"] = {   id=788, en="Tapu Fini", zh="卡璞・鳍鳍", type="Water, Fairy", species="Land Spirit Pokémon", desc="Although it’s called a guardian deity, terrible calamities sometimes befall those who recklessly approach Tapu Fini." },
  ["tapu fini"] = {   id=788, en="Tapu Fini", zh="卡璞・鳍鳍", type="Water, Fairy", species="Land Spirit Pokémon", desc="Although it’s called a guardian deity, terrible calamities sometimes befall those who recklessly approach Tapu Fini." },
  ["科斯莫古"] = {   id=789, en="Cosmog", zh="科斯莫古", type="Psychic", species="Nebula Pokémon", desc="Whether or not it’s a Pokémon from this world is a mystery. When it’s in a jam, it warps away to a safe place to hide." },
  ["cosmog"] = {   id=789, en="Cosmog", zh="科斯莫古", type="Psychic", species="Nebula Pokémon", desc="Whether or not it’s a Pokémon from this world is a mystery. When it’s in a jam, it warps away to a safe place to hide." },
  ["科斯莫姆"] = {   id=790, en="Cosmoem", zh="科斯莫姆", type="Psychic", species="Protostar Pokémon", desc="As it absorbs light, Cosmoem continues to grow. Its golden shell is surprisingly solid." },
  ["cosmoem"] = {   id=790, en="Cosmoem", zh="科斯莫姆", type="Psychic", species="Protostar Pokémon", desc="As it absorbs light, Cosmoem continues to grow. Its golden shell is surprisingly solid." },
  ["索尔迦雷欧"] = {   id=791, en="Solgaleo", zh="索尔迦雷欧", type="Psychic, Steel", species="Sunne Pokémon", desc="In writings from the distant past, it’s called by the name “the beast that devours the sun.”" },
  ["solgaleo"] = {   id=791, en="Solgaleo", zh="索尔迦雷欧", type="Psychic, Steel", species="Sunne Pokémon", desc="In writings from the distant past, it’s called by the name “the beast that devours the sun.”" },
  ["露奈雅拉"] = {   id=792, en="Lunala", zh="露奈雅拉", type="Psychic, Ghost", species="Moone Pokémon", desc="It sometimes summons unknown powers and life-forms here to this world from holes that lead to other worlds." },
  ["lunala"] = {   id=792, en="Lunala", zh="露奈雅拉", type="Psychic, Ghost", species="Moone Pokémon", desc="It sometimes summons unknown powers and life-forms here to this world from holes that lead to other worlds." },
  ["虚吾伊德"] = {   id=793, en="Nihilego", zh="虚吾伊德", type="Rock, Poison", species="Parasite Pokémon", desc="It appeared in this world from an Ultra Wormhole. Nihilego appears to be a parasite that lives by feeding on people and Pokémon." },
  ["nihilego"] = {   id=793, en="Nihilego", zh="虚吾伊德", type="Rock, Poison", species="Parasite Pokémon", desc="It appeared in this world from an Ultra Wormhole. Nihilego appears to be a parasite that lives by feeding on people and Pokémon." },
  ["爆肌蚊"] = {   id=794, en="Buzzwole", zh="爆肌蚊", type="Bug, Fighting", species="Swollen Pokémon", desc="Buzzwole goes around showing off its abnormally swollen muscles. It is one kind of Ultra Beast." },
  ["buzzwole"] = {   id=794, en="Buzzwole", zh="爆肌蚊", type="Bug, Fighting", species="Swollen Pokémon", desc="Buzzwole goes around showing off its abnormally swollen muscles. It is one kind of Ultra Beast." },
  ["费洛美螂"] = {   id=795, en="Pheromosa", zh="费洛美螂", type="Bug, Fighting", species="Lissome Pokémon", desc="Although it’s alien to this world and a danger here, it’s apparently a common organism in the world where it normally lives." },
  ["pheromosa"] = {   id=795, en="Pheromosa", zh="费洛美螂", type="Bug, Fighting", species="Lissome Pokémon", desc="Although it’s alien to this world and a danger here, it’s apparently a common organism in the world where it normally lives." },
  ["电束木"] = {   id=796, en="Xurkitree", zh="电束木", type="Electric", species="Glowing Pokémon", desc="They’ve been dubbed Ultra Beasts. Some of them stand unmoving, like trees, with their arms and legs stuck into the ground." },
  ["xurkitree"] = {   id=796, en="Xurkitree", zh="电束木", type="Electric", species="Glowing Pokémon", desc="They’ve been dubbed Ultra Beasts. Some of them stand unmoving, like trees, with their arms and legs stuck into the ground." },
  ["铁火辉夜"] = {   id=797, en="Celesteela", zh="铁火辉夜", type="Steel, Flying", species="Launch Pokémon", desc="Although it’s alien to this world and a danger here, it’s apparently a common organism in the world where it normally lives." },
  ["celesteela"] = {   id=797, en="Celesteela", zh="铁火辉夜", type="Steel, Flying", species="Launch Pokémon", desc="Although it’s alien to this world and a danger here, it’s apparently a common organism in the world where it normally lives." },
  ["纸御剑"] = {   id=798, en="Kartana", zh="纸御剑", type="Grass, Steel", species="Drawn Sword Pokémon", desc="Although it’s alien to this world and a danger here, it’s apparently a common organism in the world where it normally lives." },
  ["kartana"] = {   id=798, en="Kartana", zh="纸御剑", type="Grass, Steel", species="Drawn Sword Pokémon", desc="Although it’s alien to this world and a danger here, it’s apparently a common organism in the world where it normally lives." },
  ["恶食大王"] = {   id=799, en="Guzzlord", zh="恶食大王", type="Dark, Dragon", species="Junkivore Pokémon", desc="An unknown life-form called a UB. It may be constantly hungry—it is certainly always devouring something." },
  ["guzzlord"] = {   id=799, en="Guzzlord", zh="恶食大王", type="Dark, Dragon", species="Junkivore Pokémon", desc="An unknown life-form called a UB. It may be constantly hungry—it is certainly always devouring something." },
  ["奈克洛兹玛"] = {   id=800, en="Necrozma", zh="奈克洛兹玛", type="Psychic", species="Prism Pokémon", desc="Light is the source of its energy. If it isn’t devouring light, impurities build up in it and on it, and Necrozma darkens and stops moving." },
  ["necrozma"] = {   id=800, en="Necrozma", zh="奈克洛兹玛", type="Psychic", species="Prism Pokémon", desc="Light is the source of its energy. If it isn’t devouring light, impurities build up in it and on it, and Necrozma darkens and stops moving." },
  ["玛机雅娜"] = {   id=801, en="Magearna", zh="玛机雅娜", type="Steel, Fairy", species="Artificial Pokémon", desc="Built roughly 500 years ago by a scientist, the part called the Soul-Heart is the actual life-form." },
  ["magearna"] = {   id=801, en="Magearna", zh="玛机雅娜", type="Steel, Fairy", species="Artificial Pokémon", desc="Built roughly 500 years ago by a scientist, the part called the Soul-Heart is the actual life-form." },
  ["玛夏多"] = {   id=802, en="Marshadow", zh="玛夏多", type="Fighting, Ghost", species="Gloomdweller Pokémon", desc="It sinks into the shadows of people and Pokémon, where it can understand their feelings and copy their capabilities." },
  ["marshadow"] = {   id=802, en="Marshadow", zh="玛夏多", type="Fighting, Ghost", species="Gloomdweller Pokémon", desc="It sinks into the shadows of people and Pokémon, where it can understand their feelings and copy their capabilities." },
  ["毒贝比"] = {   id=803, en="Poipole", zh="毒贝比", type="Poison", species="Poison Pin Pokémon", desc="An Ultra Beast that lives in a different world, it cackles wildly as it sprays its opponents with poison from the needles on its head." },
  ["poipole"] = {   id=803, en="Poipole", zh="毒贝比", type="Poison", species="Poison Pin Pokémon", desc="An Ultra Beast that lives in a different world, it cackles wildly as it sprays its opponents with poison from the needles on its head." },
  ["四颚针龙"] = {   id=804, en="Naganadel", zh="四颚针龙", type="Poison, Dragon", species="Poison Pin Pokémon", desc="One kind of Ultra Beast, it fires a glowing, venomous liquid from its needles. This liquid is also immensely adhesive." },
  ["naganadel"] = {   id=804, en="Naganadel", zh="四颚针龙", type="Poison, Dragon", species="Poison Pin Pokémon", desc="One kind of Ultra Beast, it fires a glowing, venomous liquid from its needles. This liquid is also immensely adhesive." },
  ["垒磊石"] = {   id=805, en="Stakataka", zh="垒磊石", type="Rock, Steel", species="Rampart Pokémon", desc="When stone walls started moving and attacking, the brute’s true identity was this mysterious life-form, which brings to mind an Ultra Beast." },
  ["stakataka"] = {   id=805, en="Stakataka", zh="垒磊石", type="Rock, Steel", species="Rampart Pokémon", desc="When stone walls started moving and attacking, the brute’s true identity was this mysterious life-form, which brings to mind an Ultra Beast." },
  ["砰头小丑"] = {   id=806, en="Blacephalon", zh="砰头小丑", type="Fire, Ghost", species="Fireworks Pokémon", desc="A UB that appeared from an Ultra Wormhole, it causes explosions, then takes advantage of opponents’ surprise to rob them of their vitality." },
  ["blacephalon"] = {   id=806, en="Blacephalon", zh="砰头小丑", type="Fire, Ghost", species="Fireworks Pokémon", desc="A UB that appeared from an Ultra Wormhole, it causes explosions, then takes advantage of opponents’ surprise to rob them of their vitality." },
  ["捷拉奥拉"] = {   id=807, en="Zeraora", zh="捷拉奥拉", type="Electric", species="Thunderclap Pokémon", desc="It approaches its enemies at the speed of lightning, then tears them limb from limb with its sharp claws." },
  ["zeraora"] = {   id=807, en="Zeraora", zh="捷拉奥拉", type="Electric", species="Thunderclap Pokémon", desc="It approaches its enemies at the speed of lightning, then tears them limb from limb with its sharp claws." },
  ["美录坦"] = {   id=808, en="Meltan", zh="美录坦", type="Steel", species="Hex Nut Pokémon", desc="They live as a group, but when the time comes, one strong Meltan will absorb all the others and evolve." },
  ["meltan"] = {   id=808, en="Meltan", zh="美录坦", type="Steel", species="Hex Nut Pokémon", desc="They live as a group, but when the time comes, one strong Meltan will absorb all the others and evolve." },
  ["美录梅塔"] = {   id=809, en="Melmetal", zh="美录梅塔", type="Steel", species="Hex Nut Pokémon", desc="Centrifugal force is behind the punches of Melmetal's heavy hex-nut arms. Melmetal is said to deliver the strongest punches of all Pokémon." },
  ["melmetal"] = {   id=809, en="Melmetal", zh="美录梅塔", type="Steel", species="Hex Nut Pokémon", desc="Centrifugal force is behind the punches of Melmetal's heavy hex-nut arms. Melmetal is said to deliver the strongest punches of all Pokémon." },
  ["敲音猴"] = {   id=810, en="Grookey", zh="敲音猴", type="Grass", species="Chimp Pokémon", desc="It attacks with rapid beats of its stick. As it strikes with amazing speed, it gets more and more pumped." },
  ["grookey"] = {   id=810, en="Grookey", zh="敲音猴", type="Grass", species="Chimp Pokémon", desc="It attacks with rapid beats of its stick. As it strikes with amazing speed, it gets more and more pumped." },
  ["啪咚猴"] = {   id=811, en="Thwackey", zh="啪咚猴", type="Grass", species="Beat Pokémon", desc="When it’s drumming out rapid beats in battle, it gets so caught up in the rhythm that it won’t even notice that it’s already knocked out its opponent." },
  ["thwackey"] = {   id=811, en="Thwackey", zh="啪咚猴", type="Grass", species="Beat Pokémon", desc="When it’s drumming out rapid beats in battle, it gets so caught up in the rhythm that it won’t even notice that it’s already knocked out its opponent." },
  ["轰擂金刚猩"] = {   id=812, en="Rillaboom", zh="轰擂金刚猩", type="Grass", species="Drummer Pokémon", desc="The one with the best drumming techniques becomes the boss of the troop. It has a gentle disposition and values harmony among its group." },
  ["rillaboom"] = {   id=812, en="Rillaboom", zh="轰擂金刚猩", type="Grass", species="Drummer Pokémon", desc="The one with the best drumming techniques becomes the boss of the troop. It has a gentle disposition and values harmony among its group." },
  ["炎兔儿"] = {   id=813, en="Scorbunny", zh="炎兔儿", type="Fire", species="Rabbit Pokémon", desc="It has special pads on the backs of its feet, and one on its nose. Once it’s raring to fight, these pads radiate tremendous heat." },
  ["scorbunny"] = {   id=813, en="Scorbunny", zh="炎兔儿", type="Fire", species="Rabbit Pokémon", desc="It has special pads on the backs of its feet, and one on its nose. Once it’s raring to fight, these pads radiate tremendous heat." },
  ["腾蹴小将"] = {   id=814, en="Raboot", zh="腾蹴小将", type="Fire", species="Rabbit Pokémon", desc="It kicks berries right off the branches of trees and then juggles them with its feet, practicing its footwork." },
  ["raboot"] = {   id=814, en="Raboot", zh="腾蹴小将", type="Fire", species="Rabbit Pokémon", desc="It kicks berries right off the branches of trees and then juggles them with its feet, practicing its footwork." },
  ["闪焰王牌"] = {   id=815, en="Cinderace", zh="闪焰王牌", type="Fire", species="Striker Pokémon", desc="It’s skilled at both offense and defense, and it gets pumped up when cheered on. But if it starts showboating, it could put itself in a tough spot." },
  ["cinderace"] = {   id=815, en="Cinderace", zh="闪焰王牌", type="Fire", species="Striker Pokémon", desc="It’s skilled at both offense and defense, and it gets pumped up when cheered on. But if it starts showboating, it could put itself in a tough spot." },
  ["泪眼蜥"] = {   id=816, en="Sobble", zh="泪眼蜥", type="Water", species="Water Lizard Pokémon", desc="When it gets wet, its skin changes color, and this Pokémon becomes invisible as if it were camouflaged." },
  ["sobble"] = {   id=816, en="Sobble", zh="泪眼蜥", type="Water", species="Water Lizard Pokémon", desc="When it gets wet, its skin changes color, and this Pokémon becomes invisible as if it were camouflaged." },
  ["变涩蜥"] = {   id=817, en="Drizzile", zh="变涩蜥", type="Water", species="Water lizard Pokémon", desc="Highly intelligent but also very lazy, it keeps enemies out of its territory by laying traps everywhere." },
  ["drizzile"] = {   id=817, en="Drizzile", zh="变涩蜥", type="Water", species="Water lizard Pokémon", desc="Highly intelligent but also very lazy, it keeps enemies out of its territory by laying traps everywhere." },
  ["千面避役"] = {   id=818, en="Inteleon", zh="千面避役", type="Water", species="Secret Agent Pokémon", desc="Its nictitating membranes let it pick out foes’ weak points so it can precisely blast them with water that shoots from its fingertips at Mach 3." },
  ["inteleon"] = {   id=818, en="Inteleon", zh="千面避役", type="Water", species="Secret Agent Pokémon", desc="Its nictitating membranes let it pick out foes’ weak points so it can precisely blast them with water that shoots from its fingertips at Mach 3." },
  ["贪心栗鼠"] = {   id=819, en="Skwovet", zh="贪心栗鼠", type="Normal", species="Cheeky Pokémon", desc="It eats berries nonstop—a habit that has made it more resilient than it looks. It’ll show up on farms, searching for yet more berries." },
  ["skwovet"] = {   id=819, en="Skwovet", zh="贪心栗鼠", type="Normal", species="Cheeky Pokémon", desc="It eats berries nonstop—a habit that has made it more resilient than it looks. It’ll show up on farms, searching for yet more berries." },
  ["藏饱栗鼠"] = {   id=820, en="Greedent", zh="藏饱栗鼠", type="Normal", species="Greedy Pokémon", desc="Common throughout the Galar region, this Pokémon has strong teeth and can chew through the toughest of berry shells." },
