  ["稚山雀"] = {   id=821, en="Rookidee", zh="稚山雀", type="Flying", species="Tiny Bird Pokémon", desc="Jumping nimbly about, this small-bodied Pokémon takes advantage of even the slightest opportunity to disorient larger opponents." },
