  ["蓝鸦"] = {   id=822, en="Corvisquire", zh="蓝鸦", type="Flying", species="Raven Pokémon", desc="The lessons of many harsh battles have taught it how to accurately judge an opponent’s strength." },
  ["corvisquire"] = {   id=822, en="Corvisquire", zh="蓝鸦", type="Flying", species="Raven Pokémon", desc="The lessons of many harsh battles have taught it how to accurately judge an opponent’s strength." },
  ["钢铠鸦"] = {   id=823, en="Corviknight", zh="钢铠鸦", type="Flying, Steel", species="Raven Pokémon", desc="With their great intellect and flying skills, these Pokémon very successfully act as the Galar region’s airborne taxi service." },
  ["corviknight"] = {   id=823, en="Corviknight", zh="钢铠鸦", type="Flying, Steel", species="Raven Pokémon", desc="With their great intellect and flying skills, these Pokémon very successfully act as the Galar region’s airborne taxi service." },
  ["索侦虫"] = {   id=824, en="Blipbug", zh="索侦虫", type="Bug", species="Larva Pokémon", desc="Often found in gardens, this Pokémon has hairs on its body that it uses to assess its surroundings." },
