  ["以欧路普"] = {   id=826, en="Orbeetle", zh="以欧路普", type="Bug, Psychic", species="Seven Spot Pokémon", desc="It emits psychic energy to observe and study what’s around it—and what’s around it can include things over six miles away." },
  ["orbeetle"] = {   id=826, en="Orbeetle", zh="以欧路普", type="Bug, Psychic", species="Seven Spot Pokémon", desc="It emits psychic energy to observe and study what’s around it—and what’s around it can include things over six miles away." },
  ["偷儿狐"] = {   id=827, en="Nickit", zh="偷儿狐", type="Dark", species="Fox Pokémon", desc="Cunning and cautious, this Pokémon survives by stealing food from others. It erases its tracks with swipes of its tail as it makes off with its plunder." },
  ["nickit"] = {   id=827, en="Nickit", zh="偷儿狐", type="Dark", species="Fox Pokémon", desc="Cunning and cautious, this Pokémon survives by stealing food from others. It erases its tracks with swipes of its tail as it makes off with its plunder." },
  ["狐大盗"] = {   id=828, en="Thievul", zh="狐大盗", type="Dark", species="Fox Pokémon", desc="With a lithe body and sharp claws, it goes around stealing food and eggs. Boltund is its natural enemy." },
  ["thievul"] = {   id=828, en="Thievul", zh="狐大盗", type="Dark", species="Fox Pokémon", desc="With a lithe body and sharp claws, it goes around stealing food and eggs. Boltund is its natural enemy." },
  ["幼棉棉"] = {   id=829, en="Gossifleur", zh="幼棉棉", type="Grass", species="Flowering Pokémon", desc="It whirls around in the wind while singing a joyous song. This delightful display has charmed many into raising this Pokémon." },
  ["gossifleur"] = {   id=829, en="Gossifleur", zh="幼棉棉", type="Grass", species="Flowering Pokémon", desc="It whirls around in the wind while singing a joyous song. This delightful display has charmed many into raising this Pokémon." },
  ["白蓬蓬"] = {   id=830, en="Eldegoss", zh="白蓬蓬", type="Grass", species="Cotton Bloom Pokémon", desc="The cotton on the head of this Pokémon can be spun into a glossy, gorgeous yarn—a Galar regional specialty." },
  ["eldegoss"] = {   id=830, en="Eldegoss", zh="白蓬蓬", type="Grass", species="Cotton Bloom Pokémon", desc="The cotton on the head of this Pokémon can be spun into a glossy, gorgeous yarn—a Galar regional specialty." },
  ["毛辫羊"] = {   id=831, en="Wooloo", zh="毛辫羊", type="Normal", species="Sheep Pokémon", desc="If its fleece grows too long, Wooloo won’t be able to move. Cloth made with the wool of this Pokémon is surprisingly strong." },
  ["wooloo"] = {   id=831, en="Wooloo", zh="毛辫羊", type="Normal", species="Sheep Pokémon", desc="If its fleece grows too long, Wooloo won’t be able to move. Cloth made with the wool of this Pokémon is surprisingly strong." },
  ["毛毛角羊"] = {   id=832, en="Dubwool", zh="毛毛角羊", type="Normal", species="Sheep Pokémon", desc="Its majestic horns are meant only to impress the opposite gender. They never see use in battle." },
  ["dubwool"] = {   id=832, en="Dubwool", zh="毛毛角羊", type="Normal", species="Sheep Pokémon", desc="Its majestic horns are meant only to impress the opposite gender. They never see use in battle." },
  ["咬咬龟 "] = {   id=833, en="Chewtle", zh="咬咬龟 ", type="Water", species="Snapping Pokémon", desc="It starts off battles by attacking with its rock-hard horn, but as soon as the opponent flinches, this Pokémon bites down and never lets go." },
  ["chewtle"] = {   id=833, en="Chewtle", zh="咬咬龟 ", type="Water", species="Snapping Pokémon", desc="It starts off battles by attacking with its rock-hard horn, but as soon as the opponent flinches, this Pokémon bites down and never lets go." },
  ["暴噬龟"] = {   id=834, en="Drednaw", zh="暴噬龟", type="Water, Rock", species="Bite Pokémon", desc="This Pokémon rapidly extends its retractable neck to sink its sharp fangs into distant enemies and take them down." },
  ["drednaw"] = {   id=834, en="Drednaw", zh="暴噬龟", type="Water, Rock", species="Bite Pokémon", desc="This Pokémon rapidly extends its retractable neck to sink its sharp fangs into distant enemies and take them down." },
  ["来电汪"] = {   id=835, en="Yamper", zh="来电汪", type="Electric", species="Puppy Pokémon", desc="This gluttonous Pokémon only assists people with their work because it wants treats. As it runs, it crackles with electricity." },
  ["yamper"] = {   id=835, en="Yamper", zh="来电汪", type="Electric", species="Puppy Pokémon", desc="This gluttonous Pokémon only assists people with their work because it wants treats. As it runs, it crackles with electricity." },
  ["逐电犬"] = {   id=836, en="Boltund", zh="逐电犬", type="Electric", species="Dog Pokémon", desc="It sends electricity through its legs to boost their strength. Running at top speed, it easily breaks 50 mph." },
  ["boltund"] = {   id=836, en="Boltund", zh="逐电犬", type="Electric", species="Dog Pokémon", desc="It sends electricity through its legs to boost their strength. Running at top speed, it easily breaks 50 mph." },
  ["小炭仔"] = {   id=837, en="Rolycoly", zh="小炭仔", type="Rock", species="Coal Pokémon", desc="It can race around like a unicycle, even on rough, rocky terrain. Burning coal sustains it." },
  ["rolycoly"] = {   id=837, en="Rolycoly", zh="小炭仔", type="Rock", species="Coal Pokémon", desc="It can race around like a unicycle, even on rough, rocky terrain. Burning coal sustains it." },
  ["大炭车"] = {   id=838, en="Carkol", zh="大炭车", type="Rock, Fire", species="Coal Pokémon", desc="By rapidly rolling its legs, it can travel at over 18 mph. The temperature of the flames it breathes exceeds 1,800 degrees Fahrenheit." },
  ["carkol"] = {   id=838, en="Carkol", zh="大炭车", type="Rock, Fire", species="Coal Pokémon", desc="By rapidly rolling its legs, it can travel at over 18 mph. The temperature of the flames it breathes exceeds 1,800 degrees Fahrenheit." },
  ["巨炭山"] = {   id=839, en="Coalossal", zh="巨炭山", type="Rock, Fire", species="Coal Pokémon", desc="While it’s engaged in battle, its mountain of coal will burn bright red, sending off sparks that scorch the surrounding area." },
  ["coalossal"] = {   id=839, en="Coalossal", zh="巨炭山", type="Rock, Fire", species="Coal Pokémon", desc="While it’s engaged in battle, its mountain of coal will burn bright red, sending off sparks that scorch the surrounding area." },
  ["啃果虫"] = {   id=840, en="Applin", zh="啃果虫", type="Grass, Dragon", species="Apple Core Pokémon", desc="As soon as it’s born, it burrows into an apple. Not only does the apple serve as its food source, but the flavor of the fruit determines its evolution." },
  ["applin"] = {   id=840, en="Applin", zh="啃果虫", type="Grass, Dragon", species="Apple Core Pokémon", desc="As soon as it’s born, it burrows into an apple. Not only does the apple serve as its food source, but the flavor of the fruit determines its evolution." },
  ["苹裹龙"] = {   id=841, en="Flapple", zh="苹裹龙", type="Grass, Dragon", species="Apple Wing Pokémon", desc="It flies on wings of apple skin and spits a powerful acid. It can also change its shape into that of an apple." },
  ["flapple"] = {   id=841, en="Flapple", zh="苹裹龙", type="Grass, Dragon", species="Apple Wing Pokémon", desc="It flies on wings of apple skin and spits a powerful acid. It can also change its shape into that of an apple." },
  ["丰蜜龙"] = {   id=842, en="Appletun", zh="丰蜜龙", type="Grass, Dragon", species="Apple Nectar Pokémon", desc="Its body is covered in sweet nectar, and the skin on its back is especially yummy. Children used to have it as a snack." },
  ["appletun"] = {   id=842, en="Appletun", zh="丰蜜龙", type="Grass, Dragon", species="Apple Nectar Pokémon", desc="Its body is covered in sweet nectar, and the skin on its back is especially yummy. Children used to have it as a snack." },
  ["沙包蛇"] = {   id=843, en="Silicobra", zh="沙包蛇", type="Ground", species="Sand Snake Pokémon", desc="It spews sand from its nostrils. While the enemy is blinded, it burrows into the ground to hide." },
  ["silicobra"] = {   id=843, en="Silicobra", zh="沙包蛇", type="Ground", species="Sand Snake Pokémon", desc="It spews sand from its nostrils. While the enemy is blinded, it burrows into the ground to hide." },
  ["沙螺蟒"] = {   id=844, en="Sandaconda", zh="沙螺蟒", type="Ground", species="Sand Snake Pokémon", desc="Its unique style of coiling allows it to blast sand out of its sand sac more efficiently." },
  ["sandaconda"] = {   id=844, en="Sandaconda", zh="沙螺蟒", type="Ground", species="Sand Snake Pokémon", desc="Its unique style of coiling allows it to blast sand out of its sand sac more efficiently." },
  ["古月鸟"] = {   id=845, en="Cramorant", zh="古月鸟", type="Flying, Water", species="Gulp Pokémon", desc="This hungry Pokémon swallows Arrokuda whole. Occasionally, it makes a mistake and tries to swallow a Pokémon other than its preferred prey." },
  ["cramorant"] = {   id=845, en="Cramorant", zh="古月鸟", type="Flying, Water", species="Gulp Pokémon", desc="This hungry Pokémon swallows Arrokuda whole. Occasionally, it makes a mistake and tries to swallow a Pokémon other than its preferred prey." },
  ["刺梭鱼"] = {   id=846, en="Arrokuda", zh="刺梭鱼", type="Water", species="Rush Pokémon", desc="After it’s eaten its fill, its movements become extremely sluggish. That’s when Cramorant swallows it up." },
