  ["戽斗尖梭"] = {   id=847, en="Barraskewda", zh="戽斗尖梭", type="Water", species="Skewer Pokémon", desc="It spins its tail fins to propel itself, surging forward at speeds of over 100 knots before ramming prey and spearing into them." },
  ["barraskewda"] = {   id=847, en="Barraskewda", zh="戽斗尖梭", type="Water", species="Skewer Pokémon", desc="It spins its tail fins to propel itself, surging forward at speeds of over 100 knots before ramming prey and spearing into them." },
  ["毒电婴"] = {   id=848, en="Toxel", zh="毒电婴", type="Electric, Poison", species="Baby Pokémon", desc="It manipulates the chemical makeup of its poison to produce electricity. The voltage is weak, but it can cause a tingling paralysis." },
  ["toxel"] = {   id=848, en="Toxel", zh="毒电婴", type="Electric, Poison", species="Baby Pokémon", desc="It manipulates the chemical makeup of its poison to produce electricity. The voltage is weak, but it can cause a tingling paralysis." },
  ["颤弦蝾螈"] = {   id=849, en="Toxtricity", zh="颤弦蝾螈", type="Electric, Poison", species="Punk Pokémon", desc="This short-tempered and aggressive Pokémon chugs stagnant water to absorb any toxins it might contain." },
  ["toxtricity"] = {   id=849, en="Toxtricity", zh="颤弦蝾螈", type="Electric, Poison", species="Punk Pokémon", desc="This short-tempered and aggressive Pokémon chugs stagnant water to absorb any toxins it might contain." },
  ["烧火蚣"] = {   id=850, en="Sizzlipede", zh="烧火蚣", type="Fire, Bug", species="Radiator Pokémon", desc="It wraps prey up with its heated body, cooking them in its coils. Once they’re well-done, it will voraciously nibble them down to the last morsel." },
