  ["焚焰蚣"] = {   id=851, en="Centiskorch", zh="焚焰蚣", type="Fire, Bug", species="Radiator Pokémon", desc="While its burning body is already dangerous on its own, this excessively hostile Pokémon also has large and very sharp fangs." },
  ["centiskorch"] = {   id=851, en="Centiskorch", zh="焚焰蚣", type="Fire, Bug", species="Radiator Pokémon", desc="While its burning body is already dangerous on its own, this excessively hostile Pokémon also has large and very sharp fangs." },
  ["拳拳蛸"] = {   id=852, en="Clobbopus", zh="拳拳蛸", type="Fighting", species="Tantrum Pokémon", desc="Its tentacles tear off easily, but it isn’t alarmed when that happens—it knows they’ll grow back. It’s about as smart as a three-year-old." },
  ["clobbopus"] = {   id=852, en="Clobbopus", zh="拳拳蛸", type="Fighting", species="Tantrum Pokémon", desc="Its tentacles tear off easily, but it isn’t alarmed when that happens—it knows they’ll grow back. It’s about as smart as a three-year-old." },
  ["八爪武师"] = {   id=853, en="Grapploct", zh="八爪武师", type="Fighting", species="Tantrum Pokémon", desc="Searching for an opponent to test its skills against, it emerges onto land. Once the battle is over, it returns to the sea." },
