  ["来悲茶"] = {   id=854, en="Sinistea", zh="来悲茶", type="Ghost", species="Black Tea Pokémon", desc="The teacup in which this Pokémon makes its home is a famous piece of antique tableware. Many forgeries are in circulation." },
