  ["怖思壶"] = {   id=855, en="Polteageist", zh="怖思壶", type="Ghost", species="Black Tea Pokémon", desc="Leaving leftover black tea unattended is asking for this Pokémon to come along and pour itself into it, turning the tea into a new Polteageist." },
