  ["布莉姆温"] = {   id=858, en="Hatterene", zh="布莉姆温", type="Psychic, Fairy", species="Silent Pokémon", desc="If you’re too loud around it, you risk being torn apart by the claws on its tentacle. This Pokémon is also known as the Forest Witch." },
  ["hatterene"] = {   id=858, en="Hatterene", zh="布莉姆温", type="Psychic, Fairy", species="Silent Pokémon", desc="If you’re too loud around it, you risk being torn apart by the claws on its tentacle. This Pokémon is also known as the Forest Witch." },
  ["捣蛋小妖"] = {   id=859, en="Impidimp", zh="捣蛋小妖", type="Dark, Fairy", species="Wily Pokémon", desc="It sneaks into people’s homes, stealing things and feasting on the negative energy of the frustrated occupants." },
