  ["长毛巨魔"] = {   id=861, en="Grimmsnarl", zh="长毛巨魔", type="Dark, Fairy", species="Bulk Up Pokémon", desc="Its hairs work like muscle fibers. When its hairs unfurl, they latch on to opponents, ensnaring them as tentacles would." },
