  ["堵拦熊"] = {   id=862, en="Obstagoon", zh="堵拦熊", type="Dark, Normal", species="Blocking Pokémon", desc="It evolved after experiencing numerous fights. While crossing its arms, it lets out a shout that would make any opponent flinch." },
