  ["魔灵珊瑚"] = {   id=864, en="Cursola", zh="魔灵珊瑚", type="Ghost", species="Coral Pokémon", desc="Be cautious of the ectoplasmic body surrounding its soul. You’ll become stiff as stone if you touch it." },
