  ["葱游兵"] = {   id=865, en="Sirfetch'd", zh="葱游兵", type="Fighting", species="Wild Duck Pokémon", desc="After deflecting attacks with its hard leaf shield, it strikes back with its sharp leek stalk. The leek stalk is both weapon and food." },
  ["sirfetch'd"] = {   id=865, en="Sirfetch'd", zh="葱游兵", type="Fighting", species="Wild Duck Pokémon", desc="After deflecting attacks with its hard leaf shield, it strikes back with its sharp leek stalk. The leek stalk is both weapon and food." },
  ["踏冰人偶"] = {   id=866, en="Mr. Rime", zh="踏冰人偶", type="Ice, Psychic", species="Comedian Pokémon", desc="Its amusing movements make it very popular. It releases its psychic power from the pattern on its belly." },
  ["mr. rime"] = {   id=866, en="Mr. Rime", zh="踏冰人偶", type="Ice, Psychic", species="Comedian Pokémon", desc="Its amusing movements make it very popular. It releases its psychic power from the pattern on its belly." },
  ["死神板"] = {   id=867, en="Runerigus", zh="死神板", type="Ground, Ghost", species="Grudge Pokémon", desc="Never touch its shadowlike body, or you’ll be shown the horrific memories behind the picture carved into it." },
