  ["霜奶仙"] = {   id=869, en="Alcremie", zh="霜奶仙", type="Fairy", species="Cream Pokémon", desc="When Alcremie is content, the cream it secretes from its hands becomes sweeter and richer." },
  ["alcremie"] = {   id=869, en="Alcremie", zh="霜奶仙", type="Fairy", species="Cream Pokémon", desc="When Alcremie is content, the cream it secretes from its hands becomes sweeter and richer." },
  ["列阵兵"] = {   id=870, en="Falinks", zh="列阵兵", type="Fighting", species="Formation Pokémon", desc="The six of them work together as one Pokémon. Teamwork is also their battle strategy, and they constantly change their formation as they fight." },
