  ["啪嚓海胆"] = {   id=871, en="Pincurchin", zh="啪嚓海胆", type="Electric", species="Sea Urchin Pokémon", desc="It stores electricity in each spine. Even if one gets broken off, it still continues to emit electricity for at least three hours." },
  ["pincurchin"] = {   id=871, en="Pincurchin", zh="啪嚓海胆", type="Electric", species="Sea Urchin Pokémon", desc="It stores electricity in each spine. Even if one gets broken off, it still continues to emit electricity for at least three hours." },
  ["雪吞虫"] = {   id=872, en="Snom", zh="雪吞虫", type="Ice, Bug", species="Worm Pokémon", desc="It eats snow that piles up on the ground. The more snow it eats, the bigger and more impressive the spikes on its back grow." },
  ["snom"] = {   id=872, en="Snom", zh="雪吞虫", type="Ice, Bug", species="Worm Pokémon", desc="It eats snow that piles up on the ground. The more snow it eats, the bigger and more impressive the spikes on its back grow." },
  ["雪绒蛾"] = {   id=873, en="Frosmoth", zh="雪绒蛾", type="Ice, Bug", species="Frost Moth Pokémon", desc="It shows no mercy to any who desecrate fields and mountains. It will fly around on its icy wings, causing a blizzard to chase offenders away." },
  ["frosmoth"] = {   id=873, en="Frosmoth", zh="雪绒蛾", type="Ice, Bug", species="Frost Moth Pokémon", desc="It shows no mercy to any who desecrate fields and mountains. It will fly around on its icy wings, causing a blizzard to chase offenders away." },
  ["巨石丁"] = {   id=874, en="Stonjourner", zh="巨石丁", type="Rock", species="Big Rock Pokémon", desc="Once a year, on a specific date and at a specific time, they gather out of nowhere and form up in a circle." },
  ["stonjourner"] = {   id=874, en="Stonjourner", zh="巨石丁", type="Rock", species="Big Rock Pokémon", desc="Once a year, on a specific date and at a specific time, they gather out of nowhere and form up in a circle." },
  ["冰砌鹅"] = {   id=875, en="Eiscue", zh="冰砌鹅", type="Ice", species="Penguin Pokémon", desc="This Pokémon keeps its heat-sensitive head cool with ice. It fishes for its food, dangling its single hair into the sea to lure in prey." },
  ["eiscue"] = {   id=875, en="Eiscue", zh="冰砌鹅", type="Ice", species="Penguin Pokémon", desc="This Pokémon keeps its heat-sensitive head cool with ice. It fishes for its food, dangling its single hair into the sea to lure in prey." },
  ["爱管侍"] = {   id=876, en="Indeedee", zh="爱管侍", type="Psychic, Normal", species="Emotion Pokémon", desc="Through its horns, it can pick up on the emotions of creatures around it. Positive emotions are the source of its strength." },
  ["indeedee"] = {   id=876, en="Indeedee", zh="爱管侍", type="Psychic, Normal", species="Emotion Pokémon", desc="Through its horns, it can pick up on the emotions of creatures around it. Positive emotions are the source of its strength." },
  ["莫鲁贝可"] = {   id=877, en="Morpeko", zh="莫鲁贝可", type="Electric, Dark", species="Two-Sided Pokémon", desc="It carries electrically roasted seeds with it as if they’re precious treasures. No matter how much it eats, it always gets hungry again in short order." },
  ["morpeko"] = {   id=877, en="Morpeko", zh="莫鲁贝可", type="Electric, Dark", species="Two-Sided Pokémon", desc="It carries electrically roasted seeds with it as if they’re precious treasures. No matter how much it eats, it always gets hungry again in short order." },
  ["铜象"] = {   id=878, en="Cufant", zh="铜象", type="Steel", species="Copperderm Pokémon", desc="If a job requires serious strength, this Pokémon will excel at it. Its copper body tarnishes in the rain, turning a vibrant green color." },
  ["cufant"] = {   id=878, en="Cufant", zh="铜象", type="Steel", species="Copperderm Pokémon", desc="If a job requires serious strength, this Pokémon will excel at it. Its copper body tarnishes in the rain, turning a vibrant green color." },
  ["大王铜象"] = {   id=879, en="Copperajah", zh="大王铜象", type="Steel", species="Copperderm Pokémon", desc="These Pokémon live in herds. Their trunks have incredible grip strength, strong enough to crush giant rocks into powder." },
  ["copperajah"] = {   id=879, en="Copperajah", zh="大王铜象", type="Steel", species="Copperderm Pokémon", desc="These Pokémon live in herds. Their trunks have incredible grip strength, strong enough to crush giant rocks into powder." },
  ["雷鸟龙"] = {   id=880, en="Dracozolt", zh="雷鸟龙", type="Electric, Dragon", species="Fossil Pokémon", desc="The powerful muscles in its tail generate its electricity. Compared to its lower body, its upper half is entirely too small." },
  ["dracozolt"] = {   id=880, en="Dracozolt", zh="雷鸟龙", type="Electric, Dragon", species="Fossil Pokémon", desc="The powerful muscles in its tail generate its electricity. Compared to its lower body, its upper half is entirely too small." },
  ["雷鸟海兽"] = {   id=881, en="Arctozolt", zh="雷鸟海兽", type="Electric, Ice", species="Fossil Pokémon", desc="This Pokémon lived on prehistoric seashores and was able to preserve food with the ice on its body. It went extinct because it moved so slowly." },
  ["arctozolt"] = {   id=881, en="Arctozolt", zh="雷鸟海兽", type="Electric, Ice", species="Fossil Pokémon", desc="This Pokémon lived on prehistoric seashores and was able to preserve food with the ice on its body. It went extinct because it moved so slowly." },
  ["鳃鱼龙"] = {   id=882, en="Dracovish", zh="鳃鱼龙", type="Water, Dragon", species="Fossil Pokémon", desc="Its mighty legs are capable of running at speeds exceeding 40 mph, but this Pokémon can’t breathe unless it’s underwater." },
  ["dracovish"] = {   id=882, en="Dracovish", zh="鳃鱼龙", type="Water, Dragon", species="Fossil Pokémon", desc="Its mighty legs are capable of running at speeds exceeding 40 mph, but this Pokémon can’t breathe unless it’s underwater." },
  ["鳃鱼海兽"] = {   id=883, en="Arctovish", zh="鳃鱼海兽", type="Water, Ice", species="Fossil Pokémon", desc="The skin on its face is impervious to attack, but breathing difficulties made this Pokémon go extinct anyway." },
  ["arctovish"] = {   id=883, en="Arctovish", zh="鳃鱼海兽", type="Water, Ice", species="Fossil Pokémon", desc="The skin on its face is impervious to attack, but breathing difficulties made this Pokémon go extinct anyway." },
  ["铝钢龙"] = {   id=884, en="Duraludon", zh="铝钢龙", type="Steel, Dragon", species="Alloy Pokémon", desc="The special metal that composes its body is very light, so this Pokémon has considerable agility. It lives in caves because it dislikes the rain." },
  ["duraludon"] = {   id=884, en="Duraludon", zh="铝钢龙", type="Steel, Dragon", species="Alloy Pokémon", desc="The special metal that composes its body is very light, so this Pokémon has considerable agility. It lives in caves because it dislikes the rain." },
  ["多龙梅西亚"] = {   id=885, en="Dreepy", zh="多龙梅西亚", type="Dragon, Ghost", species="Lingering Pokémon", desc="If this weak Pokémon is by itself, a mere child could defeat it. But if Dreepy has friends to help it train, it can evolve and become much stronger." },
  ["dreepy"] = {   id=885, en="Dreepy", zh="多龙梅西亚", type="Dragon, Ghost", species="Lingering Pokémon", desc="If this weak Pokémon is by itself, a mere child could defeat it. But if Dreepy has friends to help it train, it can evolve and become much stronger." },
  ["多龙奇"] = {   id=886, en="Drakloak", zh="多龙奇", type="Dragon, Ghost", species="Caretaker Pokémon", desc="Without a Dreepy to place on its head and care for, it gets so uneasy it’ll try to substitute any Pokémon it finds for the missing Dreepy." },
  ["drakloak"] = {   id=886, en="Drakloak", zh="多龙奇", type="Dragon, Ghost", species="Caretaker Pokémon", desc="Without a Dreepy to place on its head and care for, it gets so uneasy it’ll try to substitute any Pokémon it finds for the missing Dreepy." },
  ["多龙巴鲁托"] = {   id=887, en="Dragapult", zh="多龙巴鲁托", type="Dragon, Ghost", species="Stealth Pokémon", desc="Apparently the Dreepy inside Dragapult’s horns eagerly look forward to being launched out at Mach speeds." },
  ["dragapult"] = {   id=887, en="Dragapult", zh="多龙巴鲁托", type="Dragon, Ghost", species="Stealth Pokémon", desc="Apparently the Dreepy inside Dragapult’s horns eagerly look forward to being launched out at Mach speeds." },
  ["苍响"] = {   id=888, en="Zacian", zh="苍响", type="Fairy", species="Warrior Pokémon", desc="This Pokémon has slumbered for many years. Some say it’s Zamazenta’s elder sister—others say the two Pokémon are rivals." },
  ["zacian"] = {   id=888, en="Zacian", zh="苍响", type="Fairy", species="Warrior Pokémon", desc="This Pokémon has slumbered for many years. Some say it’s Zamazenta’s elder sister—others say the two Pokémon are rivals." },
  ["藏玛然特"] = {   id=889, en="Zamazenta", zh="藏玛然特", type="Fighting", species="Warrior Pokémon", desc="This Pokémon slept for aeons while in the form of a statue. It was asleep for so long, people forgot that it ever existed." },
  ["zamazenta"] = {   id=889, en="Zamazenta", zh="藏玛然特", type="Fighting", species="Warrior Pokémon", desc="This Pokémon slept for aeons while in the form of a statue. It was asleep for so long, people forgot that it ever existed." },
  ["无极汰那"] = {   id=890, en="Eternatus", zh="无极汰那", type="Poison, Dragon", species="Gigantic Pokémon", desc="It was inside a meteorite that fell 20,000 years ago. There seems to be a connection between this Pokémon and the Dynamax phenomenon." },
  ["eternatus"] = {   id=890, en="Eternatus", zh="无极汰那", type="Poison, Dragon", species="Gigantic Pokémon", desc="It was inside a meteorite that fell 20,000 years ago. There seems to be a connection between this Pokémon and the Dynamax phenomenon." },
  ["熊徒弟"] = {   id=891, en="Kubfu", zh="熊徒弟", type="Fighting", species="Wushu Pokémon", desc="If Kubfu pulls the long white hair on its head, its fighting spirit heightens and power wells up from the depths of its belly." },
  ["kubfu"] = {   id=891, en="Kubfu", zh="熊徒弟", type="Fighting", species="Wushu Pokémon", desc="If Kubfu pulls the long white hair on its head, its fighting spirit heightens and power wells up from the depths of its belly." },
  ["武道熊师"] = {   id=892, en="Urshifu", zh="武道熊师", type="Fighting, Dark", species="Wushu Pokémon", desc="Inhabiting the mountains of a distant region, this Pokémon races across sheer cliffs, training its legs and refining its moves." },
  ["urshifu"] = {   id=892, en="Urshifu", zh="武道熊师", type="Fighting, Dark", species="Wushu Pokémon", desc="Inhabiting the mountains of a distant region, this Pokémon races across sheer cliffs, training its legs and refining its moves." },
  ["萨戮德"] = {   id=893, en="Zarude", zh="萨戮德", type="Dark, Grass", species="Rogue Monkey Pokémon", desc="Once the vines on Zarude’s body tear off, they become nutrients in the soil. This helps the plants of the forest grow." },
  ["zarude"] = {   id=893, en="Zarude", zh="萨戮德", type="Dark, Grass", species="Rogue Monkey Pokémon", desc="Once the vines on Zarude’s body tear off, they become nutrients in the soil. This helps the plants of the forest grow." },
  ["雷吉艾勒奇"] = {   id=894, en="Regieleki", zh="雷吉艾勒奇", type="Electric", species="Electron Pokémon", desc="Its entire body is made up of a single organ that generates electrical energy. Regieleki is capable of creating all Galar’s electricity." },
  ["regieleki"] = {   id=894, en="Regieleki", zh="雷吉艾勒奇", type="Electric", species="Electron Pokémon", desc="Its entire body is made up of a single organ that generates electrical energy. Regieleki is capable of creating all Galar’s electricity." },
  ["雷吉铎拉戈"] = {   id=895, en="Regidrago", zh="雷吉铎拉戈", type="Dragon", species="Dragon Orb Pokémon", desc="Its body is composed of crystallized dragon energy. Regidrago is said to have the powers of every dragon Pokémon." },
  ["regidrago"] = {   id=895, en="Regidrago", zh="雷吉铎拉戈", type="Dragon", species="Dragon Orb Pokémon", desc="Its body is composed of crystallized dragon energy. Regidrago is said to have the powers of every dragon Pokémon." },
  ["雪暴马"] = {   id=896, en="Glastrier", zh="雪暴马", type="Ice", species="Wild Horse Pokémon", desc="Glastrier has tremendous physical strength, and the mask of ice covering its face is 100 times harder than diamond." },
  ["glastrier"] = {   id=896, en="Glastrier", zh="雪暴马", type="Ice", species="Wild Horse Pokémon", desc="Glastrier has tremendous physical strength, and the mask of ice covering its face is 100 times harder than diamond." },
  ["灵幽马"] = {   id=897, en="Spectrier", zh="灵幽马", type="Ghost", species="Swift Horse Pokémon", desc="As it dashes through the night, Spectrier absorbs the life-force of sleeping creatures. It craves silence and solitude." },
  ["spectrier"] = {   id=897, en="Spectrier", zh="灵幽马", type="Ghost", species="Swift Horse Pokémon", desc="As it dashes through the night, Spectrier absorbs the life-force of sleeping creatures. It craves silence and solitude." },
  ["蕾冠王"] = {   id=898, en="Calyrex", zh="蕾冠王", type="Psychic, Grass", species="King Pokémon", desc="Calyrex is known in legend as a king that ruled over Galar in ancient times. It has the power to cause hearts to mend and plants to spring forth." },
